const MULTITENANT_DB_FILE = path.join(UPLOAD_DIR, 'edutest_multitenant_db.json');

const MAX_QUESTIONS_PER_BATCH = 15;
const DEFAULT_GEMINI_MODEL = 'gemini-3-flash-preview';
const FALLBACK_GEMINI_MODEL = 'gemini-flash-latest';

interface LiveGeminiCallExecutionContext {
  invoked: boolean;
  modelUsed: string;
  inputTokens: number;
  outputTokens: number;
}

const geminiCallContextStorage = new AsyncLocalStorage<LiveGeminiCallExecutionContext>();

let checkLiveAiQuotaPrecheckHook:
  | ((req: express.Request) => Promise<{
      allowed: boolean;
      httpStatus?: number;
      errorCode?: string;
      message?: string;
    }>)
  | null = null;

let recordLiveAiTelemetryHook:
  | ((
      req: express.Request,
      statusCode: number,
      ctx: LiveGeminiCallExecutionContext
    ) => Promise<void>)
  | null = null;

function createGeminiClient(apiKey: string): GoogleGenAI {
  const client = new GoogleGenAI({
    apiKey,
    httpOptions: {
      headers: {
        'User-Agent': 'aistudio-build',
      },
    },
  });
  const origGenerateContent = client.models.generateContent.bind(client.models);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  (client.models as any).generateContent = async (args: any) => {
    const store = geminiCallContextStorage.getStore();
    if (store) {
      store.invoked = true;
      store.modelUsed = String(args?.model || DEFAULT_GEMINI_MODEL);
    }
    const resp = await origGenerateContent(args);
    if (store) {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const meta = (resp as any)?.usageMetadata;
      const fallbackOut = Math.max(120, Math.round(String(resp?.text || '').length / 4));
      store.inputTokens += Number(meta?.promptTokenCount || 850);
      store.outputTokens += Number(meta?.candidatesTokenCount || fallbackOut);
    }
    return resp;
  };
  return client;
}

// Gọi Gemini Multimodal / Text (Gemini 3 Flash) với cơ chế tự động dự phòng model để đảm bảo đọc PDF dạng ảnh & tạo câu hỏi NLP luôn ổn định
// eslint-disable-next-line @typescript-eslint/no-explicit-any
async function generateContentWithModelFallback(ai: GoogleGenAI, params: { contents: any; config?: any }) {
  const candidateModels = [DEFAULT_GEMINI_MODEL, FALLBACK_GEMINI_MODEL, 'gemini-2.5-flash'];
  let lastError: unknown = null;
  for (const modelName of candidateModels) {
    try {
      return await ai.models.generateContent({
        model: modelName,
        contents: params.contents,
        config: params.config,
      });
    } catch (err) {
      lastError = err;
      console.warn(`Gemini model ${modelName} warning, trying next fallback:`, err);
    }
  }
  throw lastError;
}

