  function resolveRolesForPositionTitle(positionTitle: string): string[] {
    if (positionTitle === 'Hiệu trưởng') {
      return ['PRINCIPAL', 'TEACHER'];
    }
    if (positionTitle === 'Phó hiệu trưởng') {
      return ['VICE_PRINCIPAL', 'TEACHER'];
    }
    if (positionTitle === 'Tổ trưởng' || positionTitle === 'Tổ phó') {
      return ['HEAD_OF_DEPARTMENT', 'PEER_REVIEWER', 'TEACHER'];
    }
    return ['TEACHER'];
  }

  function resolveGradesForDepartmentAndSubject(
    departmentName: string,
    subjectName: string,
    educationLevelInPdf?: 'Tiểu học' | 'THCS'
  ): number[] {
    if (departmentName.includes('1-2-3')) return [1, 2, 3];
    if (departmentName.includes('4-5')) return [4, 5];
    if (subjectName === 'Tiểu học') return [1, 2, 3, 4, 5];
    if (educationLevelInPdf === 'Tiểu học') {
      if (subjectName.includes('Tin học') || subjectName.includes('Công nghệ')) return [3, 4, 5];
      return [1, 2, 3, 4, 5];
    }
    return [6, 7, 8, 9];
  }

  function resolveSubjectAllocationsForPdfAccount(acc: {
    departmentName: string;
    subjectName: string;
    educationLevelInPdf: 'Tiểu học' | 'THCS';
  }): Array<{
    subjectId: string;
    subjectName: string;
    educationLevelId: 'PRIMARY' | 'LOWER_SECONDARY';
    grades: number[];
    assessmentMode: string;
  }> {
    const isPrimary =
      acc.subjectName === 'Tiểu học' ||
      acc.departmentName.includes('1-2-3') ||
      acc.departmentName.includes('4-5') ||
      acc.educationLevelInPdf === 'Tiểu học';
    const levelId: 'PRIMARY' | 'LOWER_SECONDARY' = isPrimary ? 'PRIMARY' : 'LOWER_SECONDARY';
    const grades = resolveGradesForDepartmentAndSubject(
      acc.departmentName,
      acc.subjectName,
      acc.educationLevelInPdf
    );

    if (acc.subjectName === 'Tiểu học') {
      return [
        {
          subjectId: 'SUB_PRI_TOAN',
          subjectName: 'Toán',
          educationLevelId: 'PRIMARY',
          grades,
          assessmentMode: 'PAPER_EXAM',
        },
        {
          subjectId: 'SUB_PRI_TIENGVIET',
          subjectName: 'Tiếng Việt',
          educationLevelId: 'PRIMARY',
          grades,
          assessmentMode: 'PAPER_EXAM',
        },
      ];
    }

    if (acc.subjectName === 'Vật lí, Công nghệ') {
      return [
        {
          subjectId: 'SUB_SEC_KHTN',
          subjectName: 'Khoa học tự nhiên',
          educationLevelId: 'LOWER_SECONDARY',
          grades: [6, 7, 8, 9],
          assessmentMode: 'PAPER_EXAM',
        },
        {
          subjectId: 'SUB_SEC_CONGNGHE',
          subjectName: 'Công nghệ',
          educationLevelId: 'LOWER_SECONDARY',
          grades: [6, 7, 8, 9],
          assessmentMode: 'HYBRID_PAPER_PRACTICE',
        },
      ];
    }

    if (acc.subjectName === 'Tiếng Anh') {
      return [
        {
          subjectId: levelId === 'PRIMARY' ? 'SUB_PRI_NN1' : 'SUB_SEC_NN1',
          subjectName: 'Ngoại ngữ 1',
          educationLevelId: levelId,
          grades,
          assessmentMode: 'PAPER_EXAM',
        },
      ];
    }

    if (acc.subjectName === 'Giáo dục thể chất' || acc.subjectName === 'GDTC') {
      return [
        {
          subjectId: levelId === 'PRIMARY' ? 'SUB_PRI_GDTC' : 'SUB_SEC_GDTC',
          subjectName: 'Giáo dục thể chất',
          educationLevelId: levelId,
          grades,
          assessmentMode: 'COMMENT_AND_PRACTICE',
        },
      ];
    }

    if (acc.subjectName === 'Âm nhạc') {
      return [
        {
          subjectId: levelId === 'PRIMARY' ? 'SUB_PRI_AMNHAC' : 'SUB_SEC_AMNHAC',
          subjectName: 'Âm nhạc',
          educationLevelId: levelId,
          grades,
          assessmentMode: 'COMMENT_AND_PRACTICE',
        },
      ];
    }

    if (acc.subjectName === 'Mĩ thuật' || acc.subjectName === 'Mỹ thuật') {
      return [
        {
          subjectId: levelId === 'PRIMARY' ? 'SUB_PRI_MITHUAT' : 'SUB_SEC_MITHUAT',
          subjectName: 'Mĩ thuật',
          educationLevelId: levelId,
          grades,
          assessmentMode: 'COMMENT_AND_PRACTICE',
        },
      ];
    }

    if (acc.subjectName === 'Tin học') {
      return [
        {
          subjectId: levelId === 'PRIMARY' ? 'SUB_PRI_TINHOC' : 'SUB_SEC_TINHOC',
          subjectName: 'Tin học',
          educationLevelId: levelId,
          grades: levelId === 'PRIMARY' ? [3, 4, 5] : [6, 7, 8, 9],
          assessmentMode: 'HYBRID_PAPER_PRACTICE',
        },
      ];
    }

    if (acc.subjectName === 'HĐTN-HN') {
      return [
        {
          subjectId: levelId === 'PRIMARY' ? 'SUB_PRI_HDTN' : 'SUB_SEC_HDTNHN',
          subjectName:
            levelId === 'PRIMARY'
              ? 'Hoạt động trải nghiệm'
              : 'Hoạt động trải nghiệm, hướng nghiệp',
          educationLevelId: levelId,
          grades,
          assessmentMode: 'COMMENT_AND_PRACTICE',
        },
      ];
    }

    if (acc.subjectName === 'Sinh học' || acc.subjectName === 'Hóa học' || acc.subjectName === 'Vật lí') {
      return [
        {
          subjectId: 'SUB_SEC_KHTN',
          subjectName: 'Khoa học tự nhiên',
          educationLevelId: 'LOWER_SECONDARY',
          grades: [6, 7, 8, 9],
          assessmentMode: 'PAPER_EXAM',
        },
      ];
    }

    if (acc.subjectName === 'Địa lý' || acc.subjectName === 'Địa lí' || acc.subjectName === 'Lịch sử') {
      return [
        {
          subjectId: 'SUB_SEC_LSDL',
          subjectName: 'Lịch sử và Địa lí',
          educationLevelId: 'LOWER_SECONDARY',
          grades: [6, 7, 8, 9],
          assessmentMode: 'PAPER_EXAM',
        },
      ];
    }

    if (acc.subjectName === 'Giáo dục công dân' || acc.subjectName === 'GDCD') {
      return [
        {
          subjectId: 'SUB_SEC_GDCD',
          subjectName: 'Giáo dục công dân',
          educationLevelId: 'LOWER_SECONDARY',
          grades: [6, 7, 8, 9],
          assessmentMode: 'PAPER_EXAM',
        },
      ];
    }

    if (acc.subjectName === 'Ngữ văn') {
      return [
        {
          subjectId: 'SUB_SEC_NGUVAN',
          subjectName: 'Ngữ văn',
          educationLevelId: 'LOWER_SECONDARY',
          grades: [6, 7, 8, 9],
          assessmentMode: 'PAPER_EXAM',
        },
      ];
    }

    return [
      {
        subjectId: levelId === 'PRIMARY' ? 'SUB_PRI_TOAN' : 'SUB_SEC_TOAN',
        subjectName: 'Toán',
        educationLevelId: levelId,
        grades,
        assessmentMode: 'PAPER_EXAM',
      },
    ];
  }

