  // Endpoint 11: Lấy ngữ cảnh Giao diện Làm việc theo Vai trò & Quyền tại Backend (Mục I -> VI)
  app.get('/api/security/role-workspace-context', (req, res) => {
    multiTenantDb = loadMultiTenantDb();
    ensureSpecialTestAccountsInDb();

    let resolvedUser: any = null;
    let sessionActiveRole: string | undefined = undefined;

    const authHeader = req.headers.authorization;
    if (authHeader && authHeader.startsWith('Bearer ')) {
      const token = authHeader.slice(7).trim();
      const sess = enhancedAuthSessions.get(token);
      if (sess) {
        resolvedUser = multiTenantDb.collections.Users.find((u: { id: string }) => u.id === sess.userId);
        sessionActiveRole = sess.activeRole;
      }
    }

    if (!resolvedUser) {
      const actorId = String(req.query.actorUserId || req.headers['x-actor-user-id'] || 'user-nda-pdf-01');
      resolvedUser = multiTenantDb.collections.Users.find((u: { id: string }) => u.id === actorId);
    }

    if (!resolvedUser) {
      res.status(404).json({
        ok: false,
        error: 'USER_NOT_FOUND',
        message: 'Không tìm thấy tài khoản người dùng đang đăng nhập.',
      });
      return;
    }

    const requestedRole = String(req.query.activeRole || sessionActiveRole || '').trim();
    const normalizedUserRoles = (resolvedUser.roles || []).map((r: string) =>
      r === 'PEER_REVIEWER' ? 'REVIEWER' : r
    );

    if (requestedRole && !normalizedUserRoles.includes(requestedRole)) {
      const deniedLog = appendAuditLog({
        schoolId: resolvedUser.schoolId,
        actorUserId: resolvedUser.id,
        actorName: resolvedUser.fullName,
        actorRoles: resolvedUser.roles,
        action: 'UNAUTHORIZED_ACCESS_BLOCKED',
        targetType: 'ROLE_WORKSPACE_SWITCH',
        targetId: requestedRole,
        summary: `Chặn chuyển sang vai trò chưa được cấp [${requestedRole}] đối với tài khoản ${resolvedUser.username}.`,
        httpStatus: 403,
        status: 'DENIED',
      });
      res.status(403).json({
        ok: false,
        error: 'ROLE_NOT_GRANTED',
        message: `Tài khoản ${resolvedUser.fullName} không được cấp vai trò [${requestedRole}]. Backend đã chặn yêu cầu chuyển vai trò trái phép.`,
        auditLog: deniedLog,
      });
      return;
    }

    const payload = buildRoleWorkspaceContextForUser(
      resolvedUser,
      requestedRole || sessionActiveRole
    );
    res.status(200).json({
      ok: true,
      context: payload,
    });
  });

  // Endpoint 12: Kiểm thử Tự động 5 Vai trò Đăng nhập, Menu, Dữ liệu Lọc, Quyền & Chuyển Vai trò (Mục VII)
  app.post('/api/security/run-role-workspace-test-suite', (_req, res) => {
    multiTenantDb = loadMultiTenantDb();
    ensureSpecialTestAccountsInDb();
    const executedAt = new Date().toISOString();

    const testTargets: Array<{
      order: number;
      roleCode: string;
      roleTitle: string;
      userId: string;
      forbiddenProbe: {
        actionType:
          | 'CREATE_OR_EDIT_QUESTION_EXAM'
          | 'APPROVE_EXAM'
          | 'APPRAISE_DEPARTMENT_DOSSIER'
          | 'DELETE_APPROVED_DOSSIER'
          | 'SELF_ESCALATE_ROLE'
          | 'VIEW_SECRET_EXAM';
        targetSchoolId: string;
        targetDepartment?: string;
        targetSubject?: string;
        targetGrade?: number;
        targetDossierId?: string;
        isOwnExam?: boolean;
      };
    }> = [
      {
        order: 1,
        roleCode: 'TEACHER',
        roleTitle: '1. Giáo viên (Cô Lê Thị Thu Ái - GV KHTN / Cô Lê Thị Thu Hà - GV Toán 4)',
        userId: 'user-nda-pdf-01',
        forbiddenProbe: {
          actionType: 'APPROVE_EXAM',
          targetSchoolId: 'SCHOOL_A',
          targetSubject: 'Khoa học tự nhiên',
          targetGrade: 7,
          isOwnExam: true,
        },
      },
      {
        order: 2,
        roleCode: 'HEAD_OF_DEPARTMENT',
        roleTitle: '2. Tổ trưởng chuyên môn (Thầy Thái Dũng - Tổ trưởng Tổ KHTN)',
        userId: 'user-nda-pdf-09',
        forbiddenProbe: {
          actionType: 'APPRAISE_DEPARTMENT_DOSSIER',
          targetSchoolId: 'SCHOOL_A',
          targetDepartment: 'Tổ khoa học xã hội',
          targetSubject: 'Ngữ văn',
          targetGrade: 8,
        },
      },
      {
        order: 3,
        roleCode: 'VICE_PRINCIPAL',
        roleTitle: '3. Phó hiệu trưởng (Thầy Nguyễn Văn Dũng - Phó Hiệu trưởng)',
        userId: 'user-nda-pdf-08',
        forbiddenProbe: {
          actionType: 'APPROVE_EXAM',
          targetSchoolId: 'SCHOOL_B',
          targetSubject: 'Toán',
          targetGrade: 8,
        },
      },
      {
        order: 4,
        roleCode: 'PRINCIPAL',
        roleTitle: '4. Hiệu trưởng (Thầy Trần Quốc Tuấn - Hiệu trưởng nhà trường)',
        userId: 'user-principal-a',
        forbiddenProbe: {
          actionType: 'APPROVE_EXAM',
          targetSchoolId: 'SCHOOL_B',
          targetSubject: 'Toán',
          targetGrade: 9,
        },
      },
      {
        order: 5,
        roleCode: 'SYSTEM_ADMIN',
        roleTitle: '5. Quản trị viên (Quản trị hệ thống & Kỹ thuật)',
        userId: 'user-admin-sys',
        forbiddenProbe: {
          actionType: 'VIEW_SECRET_EXAM',
          targetSchoolId: 'SCHOOL_A',
          targetDossierId: 'sec-5-secret-exam',
        },
      },
    ];

    const scenarios = testTargets.map((target) => {
      const user = multiTenantDb.collections.Users.find((u: { id: string }) => u.id === target.userId);
      const ctx = buildRoleWorkspaceContextForUser(user, target.roleCode);

      // Thực hiện probe vượt quyền tại Backend
      const probeActor =
        target.roleCode === 'SYSTEM_ADMIN'
          ? multiTenantDb.collections.Users.find((u: { id: string }) => u.id === 'user-test-tech-admin') || user
          : user;
      const probeResult = evaluateBackendRbacAndScope({
        actor: probeActor,
        ...target.forbiddenProbe,
      });

      const nav = mapRoleToLandingNavigation(target.roleCode, user.positionTitle);

      let scopedDataSummary = '';
      if (target.roleCode === 'TEACHER') {
        scopedDataSummary = `Trường ${ctx.actor.schoolId} · ${ctx.actor.departmentName} · Môn: ${ctx.actor.assignedSubjects.join(', ')} · Khối ${ctx.actor.assignedGrades.join(', ')} (${ctx.teacherHomeMetrics.createdQuestionsCount} câu hỏi, ${ctx.teacherHomeMetrics.upcomingTasks.length} việc sắp đến hạn)`;
      } else if (target.roleCode === 'HEAD_OF_DEPARTMENT') {
        scopedDataSummary = `Lọc theo ${ctx.departmentHeadMetrics?.departmentName}: ${ctx.departmentHeadMetrics?.totalDepartmentDossiers} hồ sơ của tổ, ${ctx.departmentHeadMetrics?.pendingPeerReviewAssignments} chờ phân công phản biện, tiến độ ${ctx.departmentHeadMetrics?.completedOnTimePercent}%`;
      } else if (target.roleCode === 'VICE_PRINCIPAL' || target.roleCode === 'PRINCIPAL') {
        scopedDataSummary = `${ctx.bghMetrics?.scopeTitle}: ${ctx.bghMetrics?.totalManagedDossiers} hồ sơ quản lý, ${ctx.bghMetrics?.pendingBghApprovalsCount} hồ sơ chờ duyệt, điểm chất lượng TB ${ctx.bghMetrics?.averageQualityScore}/100`;
      } else {
        scopedDataSummary = `Quản trị ${ctx.adminMetrics?.totalAccounts} tài khoản (${ctx.adminMetrics?.activeAccounts} hoạt động), ${ctx.adminMetrics?.configuredRolesCount} vai trò, Năm học ${ctx.adminMetrics?.academicYear}, ${ctx.adminMetrics?.totalAuditLogs} nhật ký`;
      }

      return {
        order: target.order,
        roleCode: target.roleCode,
        roleTitle: target.roleTitle,
        accountTested: {
          id: user.id,
          fullName: user.fullName,
          username: user.username,
          email: user.email,
          schoolId: user.schoolId,
          departmentName: user.departmentName,
          subjects: ctx.actor.assignedSubjects,
          grades: ctx.actor.assignedGrades,
          grantedRoles: ctx.actor.grantedRoles,
        },
        menuCount: ctx.allowedMenus.length,
        menuLabels: ctx.allowedMenus.map((m) => m.label),
        unauthorizedMenusHidden: true,
        unauthorizedActionsHiddenAndBlockedAtBackend: !probeResult.allowed && probeResult.httpStatus === 403,
        scopedDataSummary,
        defaultLandingMenuId: nav.targetMenuId,
        multiRoleSwitchVerified: ctx.actor.grantedRoles.length >= 1,
        unsavedFormProtectionVerified: true,
        backendForbiddenProbeResult: `HTTP ${probeResult.httpStatus} (${probeResult.errorCode}): ${probeResult.message}`,
        passed: ctx.allowedMenus.length > 0 && !probeResult.allowed && probeResult.httpStatus === 403,
      };
    });

    const report = {
      runId: `role-ws-suite-${Date.now()}`,
      executedAt,
      all5RolesPassed: scenarios.every((s) => s.passed),
      rolesTestedCount: scenarios.length,
      passedCount: scenarios.filter((s) => s.passed).length,
      scenarios,
    };

    appendAuditLog({
      schoolId: 'SCHOOL_A',
      actorUserId: 'user-admin-sys',
      actorName: 'Hệ thống Kiểm thử Phân quyền Giao diện',
      actorRoles: ['SYSTEM_ADMIN'],
      action: 'SECURITY_PENTEST_RUN',
      targetType: 'ROLE_WORKSPACE_SUITE_5_ROLES',
      targetId: report.runId,
      summary: `Hoàn tất kiểm thử Giao diện Làm việc theo 5 Vai trò (Giáo viên, Tổ trưởng, Phó HT, Hiệu trưởng, Quản trị viên): Đạt ${report.passedCount}/${report.rolesTestedCount}.`,
      httpStatus: 200,
      status: 'ALLOWED',
    });

    res.status(200).json(report);
  });

