  let initializedPermStoreDbRef: object | null = null;
  let initializedPermStoreUsersCount = -1;

  interface TeacherPermissionLookupIndex {
    userById: Map<string, any>;
    activeGrantsByUserId: Map<string, any[]>;
  }

  function buildTeacherPermissionLookupIndex(): TeacherPermissionLookupIndex {
    const collections = multiTenantDb.collections as Record<string, any[]>;
    const userById = new Map<string, any>();
    for (const u of collections.Users || []) {
      if (u && u.id) {
        userById.set(u.id, u);
      }
    }
    const activeGrantsByUserId = new Map<string, any[]>();
    for (const g of collections.TeacherPermissionGrants || []) {
      if (g && g.Status === 'ACTIVE' && g.UserId) {
        let list = activeGrantsByUserId.get(g.UserId);
        if (!list) {
          list = [];
          activeGrantsByUserId.set(g.UserId, list);
        }
        list.push(g);
      }
    }
    return { userById, activeGrantsByUserId };
  }

  function ensureTeacherPermissionStoreAndTestAccounts(force = false) {
    ensureSpecialTestAccountsInDb(force);
    const collections = multiTenantDb.collections as Record<string, any[]>;
    if (
      !force &&
      initializedPermStoreDbRef === multiTenantDb &&
      Array.isArray(collections.SchoolCurriculumSubjects) &&
      collections.SchoolCurriculumSubjects.length > 0 &&
      Array.isArray(collections.TeacherPermissionGrants) &&
      Array.isArray(collections.BulkTeacherPermissionLogs) &&
      Array.isArray(collections.Users) &&
      collections.Users.length === initializedPermStoreUsersCount
    ) {
      return;
    }

    if (!Array.isArray(collections.SchoolCurriculumSubjects) || collections.SchoolCurriculumSubjects.length === 0) {
      collections.SchoolCurriculumSubjects = JSON.parse(JSON.stringify(INITIAL_SCHOOL_CURRICULUM_SUBJECTS));
    }
    if (!Array.isArray(collections.TeacherPermissionGrants)) {
      collections.TeacherPermissionGrants = [];
    }
    if (!Array.isArray(collections.BulkTeacherPermissionLogs)) {
      collections.BulkTeacherPermissionLogs = [];
    }

    const users = collections.Users;
    const nowIso = new Date().toISOString();

    let modified = false;
    const grants = collections.TeacherPermissionGrants;

    const grantsByUserId = new Map<string, any[]>();
    for (const g of grants) {
      if (g && g.UserId) {
        let arr = grantsByUserId.get(g.UserId);
        if (!arr) {
          arr = [];
          grantsByUserId.set(g.UserId, arr);
        }
        arr.push(g);
      }
    }

    const seedGrantsForUser = (
      userId: string,
      roleId: string,
      items: Array<{
        levelId: 'PRIMARY' | 'LOWER_SECONDARY';
        subjectId: string;
        subjectName: string;
        grades: number[];
        assessmentMode: string;
      }>,
      permissionCodes: string[],
      targetSchoolId = 'SCHOOL_A'
    ) => {
      const existing = (grantsByUserId.get(userId) || []).filter((g: any) => g.Status === 'ACTIVE');
      if (existing.length > 0) return;
      const createdList: any[] = grantsByUserId.get(userId) || [];
      for (const item of items) {
        for (const grade of item.grades) {
          const rec = {
            id: `tpg-${userId}-${item.subjectId}-g${grade}`,
            UserId: userId,
            SchoolId: targetSchoolId,
            RoleId: roleId,
            EducationLevelId: item.levelId,
            GradeId: grade,
            SubjectName: item.subjectName,
            SubjectId: item.subjectId,
            AssessmentMode: item.assessmentMode,
            PermissionCodes: [...permissionCodes],
            GrantedBy: 'Quản trị hệ thống (admin.nda)',
            GrantedAt: nowIso,
            UpdatedAt: nowIso,
            Status: 'ACTIVE',
          };
          grants.push(rec);
          createdList.push(rec);
        }
      }
      grantsByUserId.set(userId, createdList);
      modified = true;
    };

    const normalizeAllocSubjectId = (
      levelId: 'PRIMARY' | 'LOWER_SECONDARY',
      rawId: unknown,
      rawName: unknown
    ): { subjectId: string; subjectName: string; assessmentMode: string } => {
      const idStr = String(rawId || '').trim();
      const nameStr = String(rawName || '').trim();
      const nameLower = nameStr.toLowerCase();
      const catalog =
        collections.SchoolCurriculumSubjects || INITIAL_SCHOOL_CURRICULUM_SUBJECTS;

      const mappedId =
        idStr === 'SUB_PRI_TIENGVIET'
          ? 'SUB_PRI_TV'
          : idStr === 'SUB_PRI_TIENGANH'
          ? 'SUB_PRI_NN1'
          : idStr === 'SUB_SEC_TIENGANH'
          ? 'SUB_SEC_NN1'
          : idStr;

      const byId = catalog.find(
        (c: any) => c.educationLevelId === levelId && c.subjectId === mappedId
      );
      if (byId) {
        return {
          subjectId: byId.subjectId,
          subjectName: byId.subjectName,
          assessmentMode: byId.defaultAssessmentMode || 'PAPER_EXAM',
        };
      }

      const aliasName =
        nameLower === 'tiếng anh' || nameLower === 'ngoại ngữ 1 (tiếng anh)'
          ? 'ngoại ngữ 1'
          : nameLower === 'sinh học' || nameLower === 'vật lí' || nameLower === 'hóa học'
          ? 'khoa học tự nhiên'
          : nameLower === 'lịch sử' || nameLower === 'địa lí'
          ? 'lịch sử và địa lí'
          : nameLower;

      const byName = catalog.find(
        (c: any) =>
          c.educationLevelId === levelId &&
          String(c.subjectName || '').trim().toLowerCase() === aliasName
      );
      if (byName) {
        return {
          subjectId: byName.subjectId,
          subjectName: byName.subjectName,
          assessmentMode: byName.defaultAssessmentMode || 'PAPER_EXAM',
        };
      }

      return {
        subjectId: mappedId || `subj-${levelId.toLowerCase()}`,
        subjectName: nameStr || 'Toán',
        assessmentMode: 'PAPER_EXAM',
      };
    };

    // Chuẩn hóa subjectAllocations trên Users & đồng bộ lại TeacherPermissionGrants mặc định bị lệch từ phiên bản cũ
    for (const u of users) {
      if (!u.schoolId) continue;
      if (Array.isArray(u.subjectAllocations) && u.subjectAllocations.length > 0) {
        let userAllocFixed = false;
        u.subjectAllocations = u.subjectAllocations.map((alloc: any) => {
          const lv: 'PRIMARY' | 'LOWER_SECONDARY' =
            alloc.educationLevelId === 'PRIMARY' ? 'PRIMARY' : 'LOWER_SECONDARY';
          const resolved = normalizeAllocSubjectId(lv, alloc.subjectId, alloc.subjectName);
          if (
            alloc.subjectId !== resolved.subjectId ||
            alloc.subjectName !== resolved.subjectName
          ) {
            userAllocFixed = true;
            return {
              ...alloc,
              educationLevelId: lv,
              subjectId: resolved.subjectId,
              subjectName: resolved.subjectName,
              assessmentMode: alloc.assessmentMode || resolved.assessmentMode,
            };
          }
          return alloc;
        });
        if (userAllocFixed) modified = true;
      }

      const uRoles: string[] = Array.isArray(u.roles) ? u.roles : ['TEACHER'];
      if (
        uRoles.some((r) => ['SYSTEM_ADMIN', 'SCHOOL_ADMIN', 'SUPER_ADMIN'].includes(r)) &&
        !uRoles.includes('TEACHER')
      ) {
        continue;
      }

      let existingUserGrants = grantsByUserId.get(u.id) || [];
      if (
        String(u.id || '').startsWith('user-nda-pdf-') &&
        Array.isArray(u.subjectAllocations) &&
        u.subjectAllocations.length > 0 &&
        existingUserGrants.length > 0
      ) {
        const allAutoSeeded = existingUserGrants.every(
          (g: any) =>
            !g.GrantedBy ||
            String(g.GrantedBy).includes('admin.nda') ||
            String(g.GrantedBy).includes('Quản trị hệ thống')
        );
        if (allAutoSeeded) {
          const expectedKeys = new Set<string>();
          for (const alloc of u.subjectAllocations) {
            const lv = alloc.educationLevelId === 'PRIMARY' ? 'PRIMARY' : 'LOWER_SECONDARY';
            for (const gr of alloc.grades || []) {
              expectedKeys.add(`${lv}__${alloc.subjectId}__${Number(gr)}`);
            }
          }
          const actualKeys = new Set<string>(
            existingUserGrants
              .filter((g: any) => g.Status === 'ACTIVE')
              .map((g: any) => `${g.EducationLevelId}__${g.SubjectId}__${Number(g.GradeId)}`)
          );
          const isMismatch =
            expectedKeys.size !== actualKeys.size ||
            Array.from(expectedKeys).some((k) => !actualKeys.has(k));
          if (isMismatch) {
            for (let gi = grants.length - 1; gi >= 0; gi--) {
              if (grants[gi].UserId === u.id) {
                grants.splice(gi, 1);
              }
            }
            existingUserGrants = [];
            grantsByUserId.set(u.id, []);
            modified = true;
          }
        }
      }

      if (existingUserGrants.length > 0) continue;

      const defaultPerms: string[] = [
        'VIEW_CURRICULUM',
        'VIEW_QUESTION_BANK',
        'CREATE_QUESTION',
        'EDIT_QUESTION',
        'DELETE_DRAFT_QUESTION',
        'USE_AI_QUESTION_GENERATOR',
        'CREATE_EXAM_MATRIX',
        'CREATE_EXAM_SPECIFICATION',
        'CREATE_EXAM_PAPER',
        'GENERATE_MULTI_EXAM_CODES',
        'USE_AI_QUALITY_REVIEW',
        'EDIT_EXAM_PAPER',
        'SUBMIT_FOR_APPRAISAL',
        'EXPORT_EXAM_WORD_PDF',
        'VIEW_RESULT_REPORTS',
        'ANALYZE_QUESTION_QUALITY',
      ];
      if (
        uRoles.includes('HEAD_OF_DEPARTMENT') ||
        uRoles.includes('REVIEWER') ||
        uRoles.includes('PEER_REVIEWER')
      ) {
        defaultPerms.push('APPRAISE_EXAM');
      }
      if (uRoles.includes('HEAD_OF_DEPARTMENT')) {
        defaultPerms.push('MANAGE_DEPARTMENT_QUESTION_BANK');
      }
      if (
        uRoles.includes('PRINCIPAL') ||
        (uRoles.includes('VICE_PRINCIPAL') && u.delegatedApprovalAuthority)
      ) {
        defaultPerms.push('APPROVE_EXAM', 'EXPORT_ANSWER_KEY_RUBRIC');
      }

      const itemsToSeed: Array<{
        levelId: 'PRIMARY' | 'LOWER_SECONDARY';
        subjectId: string;
        subjectName: string;
        grades: number[];
        assessmentMode: string;
      }> = [];

      if (Array.isArray(u.subjectAllocations) && u.subjectAllocations.length > 0) {
        for (const alloc of u.subjectAllocations) {
          if (Array.isArray(alloc.grades) && alloc.grades.length > 0) {
            const lv: 'PRIMARY' | 'LOWER_SECONDARY' =
              alloc.educationLevelId === 'PRIMARY' ? 'PRIMARY' : 'LOWER_SECONDARY';
            const resolved = normalizeAllocSubjectId(lv, alloc.subjectId, alloc.subjectName);
            itemsToSeed.push({
              levelId: lv,
              subjectId: resolved.subjectId,
              subjectName: resolved.subjectName,
              grades: alloc.grades.map(Number),
              assessmentMode: alloc.assessmentMode || resolved.assessmentMode,
            });
          }
        }
      } else if (
        Array.isArray(u.assignedSubjects) &&
        u.assignedSubjects.length > 0 &&
        Array.isArray(u.assignedGrades) &&
        u.assignedGrades.length > 0
      ) {
        const numericGrades = u.assignedGrades.map(Number).filter((g: number) => g >= 1 && g <= 9);
        const primaryGrades = numericGrades.filter((g: number) => g <= 5);
        const secGrades = numericGrades.filter((g: number) => g >= 6);
        for (const rawSubj of u.assignedSubjects) {
          const subjName = String(rawSubj || '').trim();
          if (!subjName) continue;
          if (primaryGrades.length > 0) {
            const resolved = normalizeAllocSubjectId('PRIMARY', '', subjName);
            itemsToSeed.push({
              levelId: 'PRIMARY',
              subjectId: resolved.subjectId,
              subjectName: resolved.subjectName,
              grades: primaryGrades,
              assessmentMode: resolved.assessmentMode,
            });
          }
          if (secGrades.length > 0) {
            const resolved = normalizeAllocSubjectId('LOWER_SECONDARY', '', subjName);
            itemsToSeed.push({
              levelId: 'LOWER_SECONDARY',
              subjectId: resolved.subjectId,
              subjectName: resolved.subjectName,
              grades: secGrades,
              assessmentMode: resolved.assessmentMode,
            });
          }
        }
      }

      if (itemsToSeed.length > 0) {
        seedGrantsForUser(
          u.id,
          uRoles[0] || 'TEACHER',
          itemsToSeed,
          defaultPerms,
          u.schoolId || 'SCHOOL_A'
        );
      }
    }

    if (modified) {
      saveMultiTenantDb(multiTenantDb);
    }
    initializedPermStoreDbRef = multiTenantDb;
    initializedPermStoreUsersCount = Array.isArray(collections.Users) ? collections.Users.length : 0;
  }

  function buildTeacherPermissionProfile(
    userId: string,
    lookupIndex?: TeacherPermissionLookupIndex
  ) {
    if (!lookupIndex) {
      ensureTeacherPermissionStoreAndTestAccounts();
    }
    const collections = multiTenantDb.collections as Record<string, any[]>;
    const user = lookupIndex
      ? lookupIndex.userById.get(userId)
      : (collections.Users || []).find((u: any) => u.id === userId);
    if (!user) return null;

    const activeRecords = lookupIndex
      ? lookupIndex.activeGrantsByUserId.get(userId) || []
      : (collections.TeacherPermissionGrants || []).filter(
          (g: any) => g.UserId === userId && g.Status === 'ACTIVE'
        );

    const educationLevelsSet = new Set<'PRIMARY' | 'LOWER_SECONDARY'>();
    const subjectMap = new Map<
      string,
      {
        subjectId: string;
        subjectName: string;
        educationLevelId: 'PRIMARY' | 'LOWER_SECONDARY';
        grades: number[];
        assessmentMode: string;
      }
    >();
    const permissionCodesSet = new Set<string>();

    let grantedBy = 'Quản trị hệ thống (admin.nda)';
    let grantedAt = user.createdAt || new Date().toISOString();
    let updatedAt = user.updatedAt || new Date().toISOString();

    for (const rec of activeRecords) {
      educationLevelsSet.add(rec.EducationLevelId);
      const key = `${rec.EducationLevelId}__${rec.SubjectId}`;
      const existing = subjectMap.get(key);
      if (existing) {
        if (!existing.grades.includes(Number(rec.GradeId))) {
          existing.grades.push(Number(rec.GradeId));
          existing.grades.sort((a, b) => a - b);
        }
      } else {
        subjectMap.set(key, {
          subjectId: rec.SubjectId,
          subjectName: rec.SubjectName,
          educationLevelId: rec.EducationLevelId,
          grades: [Number(rec.GradeId)],
          assessmentMode: rec.AssessmentMode || 'PAPER_EXAM',
        });
      }
      if (Array.isArray(rec.PermissionCodes)) {
        for (const p of rec.PermissionCodes) {
          permissionCodesSet.add(p);
        }
      }
      if (rec.GrantedBy) grantedBy = rec.GrantedBy;
      if (rec.GrantedAt) grantedAt = rec.GrantedAt;
      if (rec.UpdatedAt) updatedAt = rec.UpdatedAt;
    }

    const subjectAllocations = Array.from(subjectMap.values());
    const activeDossiers: string[] = Array.isArray(user.assignedDossierIds)
      ? user.assignedDossierIds
      : [];

    const activeWorkItemsSummary =
      activeDossiers.length > 0
        ? activeDossiers.map((d) => `Hồ sơ đề đang xử lý: ${d}`)
        : subjectAllocations.map(
            (s) => `Phân công chuyên môn: ${s.subjectName} (Khối ${s.grades.join(', ')})`
          );

    return {
      userId: user.id,
      schoolId: user.schoolId || 'SCHOOL_A',
      fullName: user.fullName,
      username: user.username,
      email: user.email,
      departmentName: user.departmentName || 'Tổ chuyên môn',
      positionTitle: user.positionTitle || 'Giáo viên',
      roles: Array.isArray(user.roles) ? user.roles : ['TEACHER'],
      activeRole: user.activeRole || (Array.isArray(user.roles) ? user.roles[0] : 'TEACHER'),
      accountStatus: user.status || 'ACTIVE',
      educationLevels: Array.from(educationLevelsSet),
      subjectAllocations,
      permissionCodes: Array.from(permissionCodesSet),
      normalizedRecords: activeRecords,
      activeWorkItemsCount: activeWorkItemsSummary.length,
      activeWorkItemsSummary,
      grantedBy,
      grantedAt,
      updatedAt,
    };
  }

