    const snapshotAllGrants = JSON.parse(
      JSON.stringify(collections.TeacherPermissionGrants || [])
    );

    const profA = buildTeacherPermissionProfile('user-gv-a')!;
    const profB = buildTeacherPermissionProfile('user-gv-b')!;
    const profC = buildTeacherPermissionProfile('user-gv-c')!;

    const catalog = collections.SchoolCurriculumSubjects || INITIAL_SCHOOL_CURRICULUM_SUBJECTS;
