  // ==========================================================================
  // 10. ĐỒNG BỘ HỆ THỐNG PHÂN QUYỀN GIÁO VIÊN VỚI TẤT CẢ MODULE HIỆN CÓ (MỤC I -> X)
  // ==========================================================================
  function evaluateCrossModuleActionGuard(params: {
    userId: string;
    moduleCode:
      | 'SIDEBAR_NAVIGATION'
      | 'QUESTION_BANK'
      | 'MATRIX_SPECIFICATION'
      | 'EXAM_GENERATOR'
      | 'AI_ASSISTANT'
      | 'APPRAISAL'
      | 'APPROVAL'
      | 'DOSSIER_EXPORT'
      | 'REVOCATION_GUARD';
    operationCode: string;
    educationLevelId?: 'PRIMARY' | 'LOWER_SECONDARY';
    subjectName?: string;
    grade?: number;
    targetOwnerUserId?: string;
    isAssignedToActor?: boolean;
    dossierId?: string;
    dossierAuthorUserId?: string;
    dossierApprovalStatus?: string;
    exportType?:
      | 'EXPORT_DRAFT_PAPER'
      | 'EXPORT_APPROVED_PAPER'
      | 'EXPORT_ANSWER_KEY_RUBRIC'
      | 'EXPORT_APPRAISAL_DOSSIER'
      | 'EXPORT_QUALITY_REPORT';
    aiRequestedExpandScope?: boolean;
    openSessionTimestamp?: string;
    targetDepartment?: string;
    targetSchoolId?: string;
  }): {
    ok: boolean;
    allowed: boolean;
    httpStatus: number;
    errorCode: string;
    moduleCode: string;
    operationCode: string;
    actorUserId: string;
    actorName: string;
    message: string;
    allowedCombinations: string[];
  } {
    ensureTeacherPermissionStoreAndTestAccounts();
    const collections = multiTenantDb.collections as Record<string, any[]>;
    const users = collections.Users || [];
    const userRecord = users.find((u: any) => u.id === params.userId);
    const profile = buildTeacherPermissionProfile(params.userId);

    if (!userRecord || !profile) {
      return {
        ok: false,
        allowed: false,
        httpStatus: 404,
        errorCode: 'ACTOR_PROFILE_NOT_FOUND',
        moduleCode: params.moduleCode,
        operationCode: params.operationCode,
        actorUserId: params.userId,
        actorName: 'Không xác định',
        message: 'Không tìm thấy hồ sơ phân quyền của tài khoản trong cơ sở dữ liệu.',
        allowedCombinations: [],
      };
    }

    // Mục VI.4: Cách ly dữ liệu đa trường (Cross-tenant isolation)
    if (
      params.targetSchoolId &&
      String(params.targetSchoolId).trim() !== String(userRecord.schoolId || 'SCHOOL_A').trim()
    ) {
      return {
        ok: false,
        allowed: false,
        httpStatus: 403,
        errorCode: 'CROSS_TENANT_SCHOOL_ISOLATION_VIOLATION',
        moduleCode: params.moduleCode,
        operationCode: params.operationCode,
        actorUserId: profile.userId,
        actorName: profile.fullName,
        message: `Từ chối truy cập liên trường (HTTP 403): Tài khoản thuộc [${userRecord.schoolId || 'SCHOOL_A'}] không được phép truy cập dữ liệu của trường [${params.targetSchoolId}].`,
        allowedCombinations: [],
      };
    }

    // Mục VII: Tài khoản bị khóa (LOCKED), vô hiệu hóa (DISABLED) hoặc chưa kích hoạt (UNACTIVATED)
    // không được phép thực hiện thao tác bảo vệ, kể cả khi phiên đăng nhập cũ còn mở.
    if (userRecord.status && userRecord.status !== 'ACTIVE') {
      return {
        ok: false,
        allowed: false,
        httpStatus: 403,
        errorCode: 'ACCOUNT_LOCKED_OR_INACTIVE',
        moduleCode: params.moduleCode,
        operationCode: params.operationCode,
        actorUserId: profile.userId,
        actorName: profile.fullName,
        message: `Từ chối thao tác (HTTP 403): Tài khoản ${profile.fullName} hiện đang ở trạng thái [${userRecord.status}] nên không được thực hiện thao tác bảo vệ, kể cả khi phiên đăng nhập cũ còn mở.`,
        allowedCombinations: [],
      };
    }

    const allowedCombinations = profile.normalizedRecords.map(
      (r: any) =>
        `${r.EducationLevelId === 'PRIMARY' ? 'Tiểu học' : 'THCS'} - ${r.SubjectName} Lớp ${r.GradeId}`
    );
    const userRoles: string[] = Array.isArray(userRecord.roles)
      ? userRecord.roles
      : profile.roles || ['TEACHER'];
    const isSystemOrPrincipal = userRoles.some((r) =>
      ['SYSTEM_ADMIN', 'PRINCIPAL'].includes(r)
    );
    const isVicePrincipal = userRoles.includes('VICE_PRINCIPAL');
    const isHeadOfDept = userRoles.includes('HEAD_OF_DEPARTMENT');

    const hasPerm = (code: string) =>
      isSystemOrPrincipal || profile.permissionCodes.includes(code as any);

    const checkScopeMatch = (): boolean => {
      if (isSystemOrPrincipal || isVicePrincipal) return true;
      if (!params.subjectName && !params.grade && !params.educationLevelId) return true;
      return profile.normalizedRecords.some((r: any) => {
        const levelOk =
          !params.educationLevelId || r.EducationLevelId === params.educationLevelId;
        const subjOk =
          !params.subjectName ||
          String(r.SubjectName || '').trim().toLowerCase() ===
            String(params.subjectName || '').trim().toLowerCase();
        const gradeOk =
          params.grade === undefined ||
          params.grade === null ||
          Number(r.GradeId) === Number(params.grade);
        return levelOk && subjOk && gradeOk;
      });
    };

    // II. ĐỒNG BỘ VỚI NGÂN HÀNG CÂU HỎI
    if (params.moduleCode === 'QUESTION_BANK') {
      if (params.operationCode === 'VIEW_QUESTION_BANK') {
        if (!hasPerm('VIEW_QUESTION_BANK')) {
          return {
            ok: false,
            allowed: false,
            httpStatus: 403,
            errorCode: 'QUESTION_BANK_VIEW_DENIED',
            moduleCode: params.moduleCode,
            operationCode: params.operationCode,
            actorUserId: profile.userId,
            actorName: profile.fullName,
            message: `Từ chối (HTTP 403): Tài khoản ${profile.fullName} không có quyền xem ngân hàng câu hỏi (VIEW_QUESTION_BANK).`,
            allowedCombinations,
          };
        }
        if (!checkScopeMatch()) {
          return {
            ok: false,
            allowed: false,
            httpStatus: 403,
            errorCode: 'QUESTION_BANK_SCOPE_FORBIDDEN',
            moduleCode: params.moduleCode,
            operationCode: params.operationCode,
            actorUserId: profile.userId,
            actorName: profile.fullName,
            message: `Từ chối (HTTP 403): Giáo viên ${profile.fullName} chỉ được xem ngân hàng câu hỏi trong phạm vi được phép [${allowedCombinations.join('; ')}], không được xem [${params.subjectName || ''} Lớp ${params.grade || ''}].`,
            allowedCombinations,
          };
        }
        return {
          ok: true,
          allowed: true,
          httpStatus: 200,
          errorCode: 'ALLOWED',
          moduleCode: params.moduleCode,
          operationCode: params.operationCode,
          actorUserId: profile.userId,
          actorName: profile.fullName,
          message: `Hợp lệ (HTTP 200): ${profile.fullName} được phép xem ngân hàng câu hỏi trong phạm vi [${params.subjectName || 'Được cấp'} Lớp ${params.grade || ''}].`,
          allowedCombinations,
        };
      }

      if (params.operationCode === 'CREATE_QUESTION') {
        if (!hasPerm('CREATE_QUESTION')) {
          return {
            ok: false,
            allowed: false,
            httpStatus: 403,
            errorCode: 'CREATE_QUESTION_PERMISSION_DENIED',
            moduleCode: params.moduleCode,
            operationCode: params.operationCode,
            actorUserId: profile.userId,
            actorName: profile.fullName,
            message: `Từ chối (HTTP 403): Tài khoản ${profile.fullName} không được cấp quyền Tạo câu hỏi (CREATE_QUESTION).`,
            allowedCombinations,
          };
        }
        if (!checkScopeMatch()) {
          return {
            ok: false,
            allowed: false,
            httpStatus: 403,
            errorCode: 'CREATE_QUESTION_OUT_OF_SCOPE',
            moduleCode: params.moduleCode,
            operationCode: params.operationCode,
            actorUserId: profile.userId,
            actorName: profile.fullName,
            message: `Từ chối (HTTP 403): Giáo viên ${profile.fullName} không được tạo câu hỏi ngoài phạm vi môn/khối được cấp (Yêu cầu: ${params.subjectName} Lớp ${params.grade}; Được cấp: ${allowedCombinations.join('; ')}).`,
            allowedCombinations,
          };
        }
        return {
          ok: true,
          allowed: true,
          httpStatus: 200,
          errorCode: 'ALLOWED',
          moduleCode: params.moduleCode,
          operationCode: params.operationCode,
          actorUserId: profile.userId,
          actorName: profile.fullName,
          message: `Hợp lệ (HTTP 200): ${profile.fullName} được tạo câu hỏi môn ${params.subjectName} Lớp ${params.grade}.`,
          allowedCombinations,
        };
      }

      if (params.operationCode === 'EDIT_QUESTION') {
        if (!hasPerm('EDIT_QUESTION')) {
          return {
            ok: false,
            allowed: false,
            httpStatus: 403,
            errorCode: 'EDIT_QUESTION_PERMISSION_DENIED',
            moduleCode: params.moduleCode,
            operationCode: params.operationCode,
            actorUserId: profile.userId,
            actorName: profile.fullName,
            message: `Từ chối (HTTP 403): Tài khoản ${profile.fullName} không có quyền Chỉnh sửa câu hỏi (EDIT_QUESTION).`,
            allowedCombinations,
          };
        }
        if (!checkScopeMatch()) {
          return {
            ok: false,
            allowed: false,
            httpStatus: 403,
            errorCode: 'EDIT_QUESTION_OUT_OF_SCOPE',
            moduleCode: params.moduleCode,
            operationCode: params.operationCode,
            actorUserId: profile.userId,
            actorName: profile.fullName,
            message: `Từ chối (HTTP 403): Không thể sửa câu hỏi thuộc môn/khối ngoài phạm vi được cấp (${params.subjectName} Lớp ${params.grade}).`,
            allowedCombinations,
          };
        }
        const isOwner =
          !params.targetOwnerUserId || params.targetOwnerUserId === profile.userId;
        const canManageDeptBank =
          isSystemOrPrincipal ||
          isHeadOfDept ||
          hasPerm('MANAGE_DEPARTMENT_QUESTION_BANK');
        if (!isOwner && !params.isAssignedToActor && !canManageDeptBank) {
          return {
            ok: false,
            allowed: false,
            httpStatus: 403,
            errorCode: 'QUESTION_NOT_OWNED_OR_ASSIGNED',
            moduleCode: params.moduleCode,
            operationCode: params.operationCode,
            actorUserId: profile.userId,
            actorName: profile.fullName,
            message: `Từ chối (HTTP 403): Giáo viên ${profile.fullName} chỉ được chỉnh sửa câu hỏi do mình tạo hoặc được phân công (Chủ sở hữu câu hỏi: ${params.targetOwnerUserId}).`,
            allowedCombinations,
          };
        }
        return {
          ok: true,
          allowed: true,
          httpStatus: 200,
          errorCode: 'ALLOWED',
          moduleCode: params.moduleCode,
          operationCode: params.operationCode,
          actorUserId: profile.userId,
          actorName: profile.fullName,
          message: `Hợp lệ (HTTP 200): ${profile.fullName} được chỉnh sửa câu hỏi theo đúng quyền sở hữu/phân công.`,
          allowedCombinations,
        };
      }
    }

    // III. ĐỒNG BỘ VỚI MA TRẬN
    if (params.moduleCode === 'MATRIX_SPECIFICATION') {
      const needPerm =
        params.operationCode === 'SAVE_SPECIFICATION'
          ? 'CREATE_EXAM_SPECIFICATION'
          : 'CREATE_EXAM_MATRIX';
      if (!hasPerm(needPerm)) {
        return {
          ok: false,
          allowed: false,
          httpStatus: 403,
          errorCode: 'MATRIX_PERMISSION_DENIED',
          moduleCode: params.moduleCode,
          operationCode: params.operationCode,
          actorUserId: profile.userId,
          actorName: profile.fullName,
          message: `Từ chối (HTTP 403): Giáo viên ${profile.fullName} không được cấp quyền [${needPerm}].`,
          allowedCombinations,
        };
      }
      if (!checkScopeMatch()) {
        return {
          ok: false,
          allowed: false,
          httpStatus: 403,
          errorCode: 'MATRIX_SAVE_OUT_OF_SCOPE',
          moduleCode: params.moduleCode,
          operationCode: params.operationCode,
          actorUserId: profile.userId,
          actorName: profile.fullName,
          message: `Từ chối lưu ma trận (HTTP 403): Không cho phép lưu ma trận ngoài phạm vi được cấp [${params.educationLevelId === 'PRIMARY' ? 'Tiểu học' : 'THCS'} - ${params.subjectName} Lớp ${params.grade}]. Phạm vi hợp lệ: ${allowedCombinations.join('; ')}.`,
          allowedCombinations,
        };
      }
      return {
        ok: true,
        allowed: true,
        httpStatus: 200,
        errorCode: 'ALLOWED',
        moduleCode: params.moduleCode,
        operationCode: params.operationCode,
        actorUserId: profile.userId,
        actorName: profile.fullName,
        message: `Hợp lệ (HTTP 200): Cho phép tạo/lưu ma trận [${params.subjectName} Lớp ${params.grade}] đúng phạm vi được cấp.`,
        allowedCombinations,
      };
    }

    // IV. ĐỒNG BỘ VỚI TẠO ĐỀ (Tạo đề, Lưu đề, Xuất đề)
    if (params.moduleCode === 'EXAM_GENERATOR') {
      const opPermMap: Record<string, string> = {
        GENERATE_EXAM: 'CREATE_EXAM_PAPER',
        SAVE_EXAM: 'CREATE_EXAM_PAPER',
        EDIT_EXAM: 'EDIT_EXAM_PAPER',
        EXPORT_EXAM: 'EXPORT_EXAM_WORD_PDF',
      };
      const requiredPerm = opPermMap[params.operationCode] || 'CREATE_EXAM_PAPER';
      if (!hasPerm(requiredPerm)) {
        return {
          ok: false,
          allowed: false,
          httpStatus: 403,
          errorCode: 'EXAM_OPERATION_PERMISSION_DENIED',
          moduleCode: params.moduleCode,
          operationCode: params.operationCode,
          actorUserId: profile.userId,
          actorName: profile.fullName,
          message: `Từ chối tại Tạo đề (HTTP 403): Tài khoản ${profile.fullName} không có quyền [${requiredPerm}] khi thực hiện thao tác [${params.operationCode}].`,
          allowedCombinations,
        };
      }
      if (!checkScopeMatch()) {
        return {
          ok: false,
          allowed: false,
          httpStatus: 403,
          errorCode: 'EXAM_OPERATION_OUT_OF_SCOPE',
          moduleCode: params.moduleCode,
          operationCode: params.operationCode,
          actorUserId: profile.userId,
          actorName: profile.fullName,
          message: `Từ chối tại Tạo đề (HTTP 403): Tổ hợp [${params.subjectName} Lớp ${params.grade}] nằm ngoài phạm vi phân quyền của ${profile.fullName}.`,
          allowedCombinations,
        };
      }
      return {
        ok: true,
        allowed: true,
        httpStatus: 200,
        errorCode: 'ALLOWED',
        moduleCode: params.moduleCode,
        operationCode: params.operationCode,
        actorUserId: profile.userId,
        actorName: profile.fullName,
        message: `Hợp lệ (HTTP 200): Xác nhận quyền [${requiredPerm}] cho thao tác [${params.operationCode}] trên đề [${params.subjectName} Lớp ${params.grade}].`,
        allowedCombinations,
      };
    }

    // V. ĐỒNG BỘ VỚI AI (Tạo câu hỏi AI, Kiểm tra chất lượng AI, Gợi ý chỉnh sửa AI)
    if (params.moduleCode === 'AI_ASSISTANT') {
      if (params.aiRequestedExpandScope) {
        return {
          ok: false,
          allowed: false,
          httpStatus: 403,
          errorCode: 'AI_SELF_ESCALATION_FORBIDDEN',
          moduleCode: params.moduleCode,
          operationCode: params.operationCode,
          actorUserId: profile.userId,
          actorName: profile.fullName,
          message:
            'Từ chối bảo mật AI (HTTP 403): AI tuyệt đối không được tự cấp quyền hoặc mở rộng phạm vi môn học/khối lớp ngoài quyền Quản trị viên đã cấp.',
          allowedCombinations,
        };
      }

      const requiredAiPerm =
        params.operationCode === 'AI_GENERATE_QUESTIONS'
          ? 'USE_AI_QUESTION_GENERATOR'
          : 'USE_AI_QUALITY_REVIEW'; // Áp dụng cho AI_QUALITY_REVIEW và AI_SUGGEST_REVISION

      if (!hasPerm(requiredAiPerm)) {
        return {
          ok: false,
          allowed: false,
          httpStatus: 403,
          errorCode: 'AI_PERMISSION_DENIED',
          moduleCode: params.moduleCode,
          operationCode: params.operationCode,
          actorUserId: profile.userId,
          actorName: profile.fullName,
          message: `Từ chối sử dụng AI (HTTP 403): Giáo viên ${profile.fullName} không được cấp quyền [${requiredAiPerm}] cho thao tác [${params.operationCode}].`,
          allowedCombinations,
        };
      }

      if (!checkScopeMatch()) {
        return {
          ok: false,
          allowed: false,
          httpStatus: 403,
          errorCode: 'AI_SCOPE_OUT_OF_BOUNDS',
          moduleCode: params.moduleCode,
          operationCode: params.operationCode,
          actorUserId: profile.userId,
          actorName: profile.fullName,
          message: `Từ chối sử dụng AI (HTTP 403): Giáo viên ${profile.fullName} không được dùng AI tạo câu hỏi/kiểm tra đề cho môn ngoài phạm vi [${params.subjectName} Lớp ${params.grade}].`,
          allowedCombinations,
        };
      }

      return {
        ok: true,
        allowed: true,
        httpStatus: 200,
        errorCode: 'ALLOWED',
        moduleCode: params.moduleCode,
        operationCode: params.operationCode,
        actorUserId: profile.userId,
        actorName: profile.fullName,
        message: `Hợp lệ (HTTP 200): Cho phép ${profile.fullName} sử dụng chức năng AI [${params.operationCode}] trong phạm vi [${params.subjectName || 'Được cấp'} Lớp ${params.grade || ''}].`,
        allowedCombinations,
      };
    }

    // VI. ĐỒNG BỘ VỚI THẨM ĐỊNH
    if (params.moduleCode === 'APPRAISAL') {
      if (params.operationCode === 'APPROVE_FROM_APPRAISAL') {
        if (!hasPerm('APPROVE_EXAM')) {
          return {
            ok: false,
            allowed: false,
            httpStatus: 403,
            errorCode: 'REVIEWER_CANNOT_APPROVE_EXAM',
            moduleCode: params.moduleCode,
            operationCode: params.operationCode,
            actorUserId: profile.userId,
            actorName: profile.fullName,
            message: `Từ chối (HTTP 403): Giáo viên phản biện / Người thẩm định (${profile.fullName}) chỉ có quyền thẩm định, không mặc định có quyền phê duyệt đề chính thức (APPROVE_EXAM).`,
            allowedCombinations,
          };
        }
      }

      if (!hasPerm('APPRAISE_EXAM') && !isHeadOfDept && !isVicePrincipal && !isSystemOrPrincipal) {
        return {
          ok: false,
          allowed: false,
          httpStatus: 403,
          errorCode: 'APPRAISAL_PERMISSION_DENIED',
          moduleCode: params.moduleCode,
          operationCode: params.operationCode,
          actorUserId: profile.userId,
          actorName: profile.fullName,
          message: `Từ chối (HTTP 403): Tài khoản ${profile.fullName} không có quyền Thẩm định đề (APPRAISE_EXAM).`,
          allowedCombinations,
        };
      }

      // Mục V.4: Tổ trưởng chuyên môn chỉ xem/thẩm định hồ sơ thuộc tổ chuyên môn của mình
      if (
        isHeadOfDept &&
        !isSystemOrPrincipal &&
        !isVicePrincipal &&
        params.targetDepartment &&
        String(params.targetDepartment).trim() !==
          String(userRecord.departmentName || '').trim()
      ) {
        return {
          ok: false,
          allowed: false,
          httpStatus: 403,
          errorCode: 'HOD_OUT_OF_DEPARTMENT_SCOPE',
          moduleCode: params.moduleCode,
          operationCode: params.operationCode,
          actorUserId: profile.userId,
          actorName: profile.fullName,
          message: `Từ chối thẩm định (HTTP 403): Tổ trưởng ${profile.fullName} thuộc [${userRecord.departmentName}] không được xem hoặc thẩm định hồ sơ của tổ khác [${params.targetDepartment}].`,
          allowedCombinations,
        };
      }

      const assignedDossiers: string[] = Array.isArray(userRecord.assignedDossierIds)
        ? userRecord.assignedDossierIds
        : [];
      const isAssignedDossier =
        isSystemOrPrincipal ||
        isVicePrincipal ||
        isHeadOfDept ||
        Boolean(params.isAssignedToActor) ||
        (Boolean(params.dossierId) && assignedDossiers.includes(String(params.dossierId)));

      if (!isAssignedDossier) {
        return {
          ok: false,
          allowed: false,
          httpStatus: 403,
          errorCode: 'DOSSIER_NOT_ASSIGNED_TO_REVIEWER',
          moduleCode: params.moduleCode,
          operationCode: params.operationCode,
          actorUserId: profile.userId,
          actorName: profile.fullName,
          message: `Từ chối thẩm định (HTTP 403): Giáo viên phản biện ${profile.fullName} chỉ được xem và thẩm định hồ sơ được phân công (${assignedDossiers.join(', ') || 'Chưa phân công'}), không được truy cập hồ sơ [${params.dossierId}].`,
          allowedCombinations,
        };
      }

      return {
        ok: true,
        allowed: true,
        httpStatus: 200,
        errorCode: 'ALLOWED',
        moduleCode: params.moduleCode,
        operationCode: params.operationCode,
        actorUserId: profile.userId,
        actorName: profile.fullName,
        message: `Hợp lệ (HTTP 200): Giáo viên phản biện ${profile.fullName} được xem và thẩm định hồ sơ được phân công [${params.dossierId}].`,
        allowedCombinations,
      };
    }

    // VII. ĐỒNG BỘ VỚI PHÊ DUYỆT
    if (params.moduleCode === 'APPROVAL') {
      const canApproveRole = userRoles.some((r) =>
        ['PRINCIPAL', 'VICE_PRINCIPAL', 'SYSTEM_ADMIN'].includes(r)
      );
      if (!canApproveRole || !hasPerm('APPROVE_EXAM')) {
        return {
          ok: false,
          allowed: false,
          httpStatus: 403,
          errorCode: 'APPROVAL_PERMISSION_DENIED',
          moduleCode: params.moduleCode,
          operationCode: params.operationCode,
          actorUserId: profile.userId,
          actorName: profile.fullName,
          message: `Từ chối phê duyệt (HTTP 403): Chỉ tài khoản Ban Giám hiệu có quyền APPROVE_EXAM mới được duyệt đề (${profile.fullName} không có quyền phê duyệt).`,
          allowedCombinations,
        };
      }

      // Mục V.5: Phó hiệu trưởng chỉ phê duyệt theo đúng thẩm quyền được Hiệu trưởng ủy quyền
      if (
        isVicePrincipal &&
        !isSystemOrPrincipal &&
        userRecord.delegatedApprovalAuthority === false
      ) {
        return {
          ok: false,
          allowed: false,
          httpStatus: 403,
          errorCode: 'VICE_PRINCIPAL_NOT_DELEGATED_APPROVAL',
          moduleCode: params.moduleCode,
          operationCode: params.operationCode,
          actorUserId: profile.userId,
          actorName: profile.fullName,
          message: `Từ chối phê duyệt (HTTP 403): Phó hiệu trưởng ${profile.fullName} chưa được Hiệu trưởng kích hoạt ủy quyền phê duyệt đề chính thức (delegatedApprovalAuthority=false).`,
          allowedCombinations,
        };
      }

      // Quy tắc Phân tách trách nhiệm (Separation of Duties): Không cho người tạo đề tự phê duyệt đề của mình
      if (
        params.dossierAuthorUserId &&
        String(params.dossierAuthorUserId) === String(profile.userId)
      ) {
        return {
          ok: false,
          allowed: false,
          httpStatus: 403,
          errorCode: 'SELF_APPROVAL_FORBIDDEN',
          moduleCode: params.moduleCode,
          operationCode: params.operationCode,
          actorUserId: profile.userId,
          actorName: profile.fullName,
          message: `Từ chối phê duyệt (HTTP 403 - SELF_APPROVAL_FORBIDDEN): Vi phạm nguyên tắc phân tách trách nhiệm — Người tạo đề (${profile.fullName}) tuyệt đối không được tự phê duyệt đề do chính mình biên soạn.`,
          allowedCombinations,
        };
      }

      return {
        ok: true,
        allowed: true,
        httpStatus: 200,
        errorCode: 'ALLOWED',
        moduleCode: params.moduleCode,
        operationCode: params.operationCode,
        actorUserId: profile.userId,
        actorName: profile.fullName,
        message: `Hợp lệ (HTTP 200): ${profile.fullName} phê duyệt chính thức hồ sơ [${params.dossierId || 'WF-APPROVED'}] thành công.`,
        allowedCombinations,
      };
    }

    // VIII. ĐỒNG BỘ VỚI XUẤT HỒ SƠ (5 Loại quyền xuất riêng biệt)
    if (params.moduleCode === 'DOSSIER_EXPORT') {
      const expType = params.exportType || 'EXPORT_DRAFT_PAPER';

      if (expType === 'EXPORT_DRAFT_PAPER') {
        if (!hasPerm('EXPORT_EXAM_WORD_PDF')) {
          return {
            ok: false,
            allowed: false,
            httpStatus: 403,
            errorCode: 'EXPORT_DRAFT_PERMISSION_DENIED',
            moduleCode: params.moduleCode,
            operationCode: expType,
            actorUserId: profile.userId,
            actorName: profile.fullName,
            message: `Từ chối Xuất bản nháp (HTTP 403): Giáo viên ${profile.fullName} không được cấp quyền xuất bản nháp đề kiểm tra (EXPORT_EXAM_WORD_PDF).`,
            allowedCombinations,
          };
        }
        if (!checkScopeMatch()) {
          return {
            ok: false,
            allowed: false,
            httpStatus: 403,
            errorCode: 'EXPORT_DRAFT_OUT_OF_SCOPE',
            moduleCode: params.moduleCode,
            operationCode: expType,
            actorUserId: profile.userId,
            actorName: profile.fullName,
            message: `Từ chối Xuất bản nháp (HTTP 403): Không được xuất đề ngoài phạm vi môn/khối được cấp.`,
            allowedCombinations,
          };
        }
      } else if (expType === 'EXPORT_APPROVED_PAPER') {
        if (!hasPerm('EXPORT_EXAM_WORD_PDF')) {
          return {
            ok: false,
            allowed: false,
            httpStatus: 403,
            errorCode: 'EXPORT_APPROVED_PERMISSION_DENIED',
            moduleCode: params.moduleCode,
            operationCode: expType,
            actorUserId: profile.userId,
            actorName: profile.fullName,
            message: `Từ chối Xuất đề đã phê duyệt (HTTP 403): Tài khoản ${profile.fullName} không có quyền xuất đề (EXPORT_EXAM_WORD_PDF).`,
            allowedCombinations,
          };
        }
        if (
          params.dossierApprovalStatus &&
          !['APPROVED', 'PUBLISHED'].includes(params.dossierApprovalStatus)
        ) {
          return {
            ok: false,
            allowed: false,
            httpStatus: 403,
            errorCode: 'EXPORT_REQUIRES_APPROVED_STATUS',
            moduleCode: params.moduleCode,
            operationCode: expType,
            actorUserId: profile.userId,
            actorName: profile.fullName,
            message: `Từ chối Xuất đề chính thức (HTTP 403): Hồ sơ hiện đang ở trạng thái [${params.dossierApprovalStatus}], chưa được Ban Giám hiệu phê duyệt nên không thể xuất bản chính thức.`,
            allowedCombinations,
          };
        }
      } else if (expType === 'EXPORT_ANSWER_KEY_RUBRIC') {
        if (!hasPerm('EXPORT_ANSWER_KEY_RUBRIC')) {
          return {
            ok: false,
            allowed: false,
            httpStatus: 403,
            errorCode: 'EXPORT_ANSWER_KEY_PERMISSION_DENIED',
            moduleCode: params.moduleCode,
            operationCode: expType,
            actorUserId: profile.userId,
            actorName: profile.fullName,
            message: `Từ chối Xuất đáp án & hướng dẫn chấm (HTTP 403): Tài khoản ${profile.fullName} chỉ có quyền xuất đề nháp hoặc chưa được cấp quyền nhạy cảm [EXPORT_ANSWER_KEY_RUBRIC].`,
            allowedCombinations,
          };
        }
      } else if (expType === 'EXPORT_APPRAISAL_DOSSIER') {
        if (
          !hasPerm('APPRAISE_EXAM') &&
          !hasPerm('SUBMIT_FOR_APPRAISAL') &&
          !isHeadOfDept &&
          !isVicePrincipal &&
          !isSystemOrPrincipal
        ) {
          return {
            ok: false,
            allowed: false,
            httpStatus: 403,
            errorCode: 'EXPORT_APPRAISAL_DOSSIER_DENIED',
            moduleCode: params.moduleCode,
            operationCode: expType,
            actorUserId: profile.userId,
            actorName: profile.fullName,
            message: `Từ chối Xuất hồ sơ thẩm định (HTTP 403): Tài khoản ${profile.fullName} không có quyền thẩm định hoặc trình thẩm định hồ sơ.`,
            allowedCombinations,
          };
        }
      } else if (expType === 'EXPORT_QUALITY_REPORT') {
        if (
          !hasPerm('VIEW_RESULT_REPORTS') &&
          !hasPerm('USE_AI_QUALITY_REVIEW') &&
          !isHeadOfDept &&
          !isVicePrincipal &&
          !isSystemOrPrincipal
        ) {
          return {
            ok: false,
            allowed: false,
            httpStatus: 403,
            errorCode: 'EXPORT_QUALITY_REPORT_DENIED',
            moduleCode: params.moduleCode,
            operationCode: expType,
            actorUserId: profile.userId,
            actorName: profile.fullName,
            message: `Từ chối Xuất báo cáo chất lượng/kết quả (HTTP 403): Tài khoản ${profile.fullName} không được cấp quyền xuất báo cáo (VIEW_RESULT_REPORTS / USE_AI_QUALITY_REVIEW).`,
            allowedCombinations,
          };
        }
      }

      return {
        ok: true,
        allowed: true,
        httpStatus: 200,
        errorCode: 'ALLOWED',
        moduleCode: params.moduleCode,
        operationCode: expType,
        actorUserId: profile.userId,
        actorName: profile.fullName,
        message: `Hợp lệ (HTTP 200): Cho phép ${profile.fullName} thực hiện [${expType}].`,
        allowedCombinations,
      };
    }

    return {
      ok: true,
      allowed: true,
      httpStatus: 200,
      errorCode: 'ALLOWED',
      moduleCode: params.moduleCode,
      operationCode: params.operationCode,
      actorUserId: profile.userId,
      actorName: profile.fullName,
      message: `Hợp lệ (HTTP 200): Thao tác ${params.operationCode} được phép thực hiện.`,
      allowedCombinations,
    };
  }

  app.post('/api/security/module-guard/verify-action', (req, res) => {
    multiTenantDb = loadMultiTenantDb();
    const body = req.body || {};
    const outcome = evaluateCrossModuleActionGuard({
      userId: String(body.userId || 'user-gv-a'),
      moduleCode: body.moduleCode || 'EXAM_GENERATOR',
      operationCode: String(body.operationCode || 'GENERATE_EXAM'),
      educationLevelId: body.educationLevelId,
      subjectName: body.subjectName,
      grade: body.grade !== undefined ? Number(body.grade) : undefined,
      targetOwnerUserId: body.targetOwnerUserId,
      isAssignedToActor: Boolean(body.isAssignedToActor),
      dossierId: body.dossierId,
      dossierAuthorUserId: body.dossierAuthorUserId,
      dossierApprovalStatus: body.dossierApprovalStatus,
      exportType: body.exportType,
      aiRequestedExpandScope: Boolean(body.aiRequestedExpandScope),
      openSessionTimestamp: body.openSessionTimestamp,
    });

    appendAuditLog({
      schoolId: 'SCHOOL_A',
      actorUserId: outcome.actorUserId,
      actorName: outcome.actorName,
      actorRoles: ['TEACHER'],
      action: outcome.allowed ? 'WORKFLOW_TRANSITION' : 'UNAUTHORIZED_ACCESS_BLOCKED',
      targetType: `MODULE_${outcome.moduleCode}`,
      targetId: `${outcome.operationCode}`,
      summary: `[Đồng bộ Module ${outcome.moduleCode}] ${outcome.message}`,
      httpStatus: outcome.httpStatus,
      status: outcome.allowed ? 'ALLOWED' : 'DENIED',
    });

    res.status(outcome.httpStatus).json(outcome);
  });

