  const EMAIL_REGEX_STRICT = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
  const VALID_ACCOUNT_STATUSES = new Set(['UNACTIVATED', 'ACTIVE', 'LOCKED', 'DISABLED']);
  const VALID_ACTOR_ROLES = new Set([
    'SYSTEM_ADMIN',
    'SCHOOL_ADMIN',
    'PRINCIPAL',
    'VICE_PRINCIPAL',
    'HEAD_OF_DEPARTMENT',
    'TEACHER',
    'REVIEWER',
  ]);
  const SCHOOL_DEPARTMENTS_CATALOG = [
    'Tổ 1-2-3',
    'Tổ 4-5',
    'Tổ khoa học tự nhiên',
    'Tổ khoa học xã hội',
    'Tổ Tiếng Anh - GDTC',
    'Ban Giám hiệu và quản trị',
  ];

  function getActiveDepartmentNamesCatalog(schoolId?: string): string[] {
    const collections = multiTenantDb.collections as Record<string, any[]>;
    const dynamicActive = Array.isArray(collections.SchoolDepartments)
      ? collections.SchoolDepartments.filter(
          (d: any) =>
            d.status === 'ACTIVE' &&
            (!schoolId || (d.schoolId || 'SCHOOL_A') === schoolId)
        ).map((d: any) => String(d.departmentName || '').trim())
      : [];
    const baseDepts =
      schoolId === 'SCHOOL_B'
        ? ['Tổ 1', 'Tổ 2', 'Tổ 3', 'Tổ 4', 'Tổ 5']
        : schoolId === 'SCHOOL_C'
        ? [
            'Tổ khoa học tự nhiên',
            'Tổ khoa học xã hội',
            'Tổ Tiếng Anh - GDTC',
            'Ban Giám hiệu và quản trị',
          ]
        : SCHOOL_DEPARTMENTS_CATALOG;
    return Array.from(new Set([...baseDepts, ...dynamicActive])).filter(Boolean);
  }

  function revokeAllOpenSessionsForUser(userId: string) {
    for (const [token, sess] of enhancedAuthSessions.entries()) {
      if (sess.userId === userId) {
        enhancedAuthSessions.delete(token);
      }
    }
    for (const [token, sess] of activeSessions.entries()) {
      if (sess.userId === userId) {
        activeSessions.delete(token);
      }
    }
  }

  function buildSafeTeacherAccountRecord(
    user: any,
    index: number,
    lookupIndex?: TeacherPermissionLookupIndex
  ) {
    const permProfile = buildTeacherPermissionProfile(user.id, lookupIndex);
    const subjectAllocations =
      permProfile && permProfile.subjectAllocations.length > 0
        ? permProfile.subjectAllocations
        : Array.isArray(user.subjectAllocations)
        ? user.subjectAllocations
        : [];
    const educationLevels = Array.from(
      new Set<string>([
        ...(Array.isArray(user.educationLevels) ? user.educationLevels : []),
        ...(permProfile?.educationLevels || []),
        ...subjectAllocations.map((s: any) => s.educationLevelId),
      ])
    ).filter((lv): lv is 'PRIMARY' | 'LOWER_SECONDARY' =>
      lv === 'PRIMARY' || lv === 'LOWER_SECONDARY'
    );

    const assignedSubjectsDisplay = Array.from(
      new Set<string>(
        subjectAllocations.length > 0
          ? subjectAllocations.map(
              (s: any) =>
                `${s.subjectName} (${s.educationLevelId === 'PRIMARY' ? 'TH' : 'THCS'}: K${(
                  s.grades || []
                ).join(',')})`
            )
          : Array.isArray(user.assignedSubjects)
          ? user.assignedSubjects
          : []
      )
    );

    const assignedGradesDisplay = Array.from(
      new Set<number>(
        subjectAllocations.length > 0
          ? subjectAllocations.flatMap((s: any) => (s.grades || []).map(Number))
          : Array.isArray(user.assignedGrades)
          ? user.assignedGrades.map(Number)
          : []
      )
    ).sort((a, b) => a - b);

    const normalizedStatus = VALID_ACCOUNT_STATUSES.has(user.status)
      ? user.status
      : 'ACTIVE';

    return {
      id: user.id,
      schoolId: user.schoolId || 'SCHOOL_A',
      stt: typeof user.orderNumber === 'number' ? user.orderNumber : index + 1,
      teacherCode: user.teacherCode || '',
      positionTitle: user.positionTitle || 'Giáo viên',
      contactPhone: user.contactPhone || '',
      fullName: user.fullName || '',
      email: user.email || `${user.username || user.id}@nguyendinhanh.edu.vn`,
      username: user.username || (user.email ? String(user.email).split('@')[0] : user.id),
      departmentName: normalizeOfficialDepartmentName(user.departmentName, user.roles),
      educationLevels:
        educationLevels.length > 0 ? educationLevels : (['LOWER_SECONDARY'] as ('PRIMARY' | 'LOWER_SECONDARY')[]),
      subjectAllocations,
      assignedSubjectsDisplay,
      assignedGradesDisplay,
      roles: Array.isArray(user.roles) && user.roles.length > 0 ? user.roles : ['TEACHER'],
      status: normalizedStatus,
      lastLoginAt: user.lastLoginAt || null,
      notes: user.notes || '',
      mustChangePasswordOnNextLogin: Boolean(user.mustChangePasswordOnNextLogin),
      passwordSetupMethod: user.passwordSetupMethod || 'SEND_RESET_LINK',
      lastPasswordResetLinkSentAt: user.lastPasswordResetLinkSentAt || null,
      grantedPermissionsCount: permProfile ? permProfile.permissionCodes.length : 0,
      grantedPermissionCodes: permProfile ? permProfile.permissionCodes : [],
      createdBy: user.createdBy || 'Quản trị hệ thống',
      createdAt: user.createdAt || '2026-09-01T08:00:00.000Z',
      updatedAt: user.updatedAt || new Date().toISOString(),
    };
  }

  function validateSubjectAllocationsAgainstCurriculum(
    educationLevels: string[],
    subjectAllocations: any[]
  ): { valid: boolean; errorCode?: string; message?: string; normalizedAllocations: any[] } {
    const collections = multiTenantDb.collections as Record<string, any[]>;
    const catalog =
      collections.SchoolCurriculumSubjects || INITIAL_SCHOOL_CURRICULUM_SUBJECTS;

    const normalizedLevels = Array.isArray(educationLevels)
      ? educationLevels.filter((lv) => lv === 'PRIMARY' || lv === 'LOWER_SECONDARY')
      : [];

    if (normalizedLevels.length === 0) {
      return {
        valid: false,
        errorCode: 'MISSING_EDUCATION_LEVEL',
        message: 'Vui lòng chọn ít nhất một Cấp học giảng dạy (Tiểu học hoặc THCS).',
        normalizedAllocations: [],
      };
    }

    const normalizedAllocations: any[] = [];
    for (const rawAlloc of Array.isArray(subjectAllocations) ? subjectAllocations : []) {
      const levelId = rawAlloc.educationLevelId;
      if (levelId !== 'PRIMARY' && levelId !== 'LOWER_SECONDARY') {
        return {
          valid: false,
          errorCode: 'INVALID_SUBJECT_LEVEL',
          message: `Cấp học của môn "${rawAlloc.subjectName || rawAlloc.subjectId}" không hợp lệ.`,
          normalizedAllocations: [],
        };
      }

      if (!normalizedLevels.includes(levelId)) {
        return {
          valid: false,
          errorCode: 'SUBJECT_LEVEL_NOT_SELECTED',
          message: `Môn "${rawAlloc.subjectName}" thuộc cấp ${
            levelId === 'PRIMARY' ? 'Tiểu học' : 'THCS'
          }, nhưng tài khoản chưa được tích chọn cấp học này (Mục IV).`,
          normalizedAllocations: [],
        };
      }

      const normalizedRawId =
        rawAlloc.subjectId === 'SUB_PRI_TIENGVIET'
          ? 'SUB_PRI_TV'
          : rawAlloc.subjectId === 'SUB_PRI_TIENGANH'
          ? 'SUB_PRI_NN1'
          : rawAlloc.subjectId === 'SUB_SEC_TIENGANH'
          ? 'SUB_SEC_NN1'
          : rawAlloc.subjectId;
      const rawSubNameLower = String(rawAlloc.subjectName || '').trim().toLowerCase();
      const normalizedSubNameLower =
        rawSubNameLower === 'tiếng anh' || rawSubNameLower === 'ngoại ngữ 1 (tiếng anh)'
          ? 'ngoại ngữ 1'
          : rawSubNameLower === 'sinh học' ||
            rawSubNameLower === 'vật lí' ||
            rawSubNameLower === 'hóa học'
          ? 'khoa học tự nhiên'
          : rawSubNameLower === 'lịch sử' || rawSubNameLower === 'địa lí'
          ? 'lịch sử và địa lí'
          : rawSubNameLower;

      const catItem = catalog.find(
        (c: any) =>
          c.educationLevelId === levelId &&
          (c.subjectId === normalizedRawId ||
            String(c.subjectName).toLowerCase() === rawSubNameLower ||
            String(c.subjectName).toLowerCase() === normalizedSubNameLower)
      );

      if (!catItem) {
        return {
          valid: false,
          errorCode: 'SUBJECT_NOT_IN_CURRICULUM_CATALOG',
          message: `Môn học "${rawAlloc.subjectName || rawAlloc.subjectId}" không tồn tại trong danh mục Chương trình ${
            levelId === 'PRIMARY' ? 'Tiểu học' : 'THCS'
          } (Mục IV: Không dùng chung danh sách môn phẳng giữa hai cấp).`,
          normalizedAllocations: [],
        };
      }

      const grades: number[] = Array.isArray(rawAlloc.grades)
        ? Array.from(new Set<number>(rawAlloc.grades.map((v: any) => Number(v)))).sort(
            (a, b) => a - b
          )
        : [];

      if (grades.length === 0) {
        return {
          valid: false,
          errorCode: 'EMPTY_SUBJECT_GRADES',
          message: `Vui lòng chọn ít nhất một khối lớp cho môn "${catItem.subjectName}".`,
          normalizedAllocations: [],
        };
      }

      for (const g of grades) {
        if (levelId === 'PRIMARY' && (g < 1 || g > 5)) {
          return {
            valid: false,
            errorCode: 'PRIMARY_GRADE_OUT_OF_RANGE',
            message: `Cấp Tiểu học chỉ cho phép chọn Khối 1 đến Khối 5 (Đang chọn Khối ${g} cho môn ${catItem.subjectName}).`,
            normalizedAllocations: [],
          };
        }
        if (levelId === 'LOWER_SECONDARY' && (g < 6 || g > 9)) {
          return {
            valid: false,
            errorCode: 'SECONDARY_GRADE_OUT_OF_RANGE',
            message: `Cấp THCS chỉ cho phép chọn Khối 6 đến Khối 9 (Đang chọn Khối ${g} cho môn ${catItem.subjectName}).`,
            normalizedAllocations: [],
          };
        }
        if (Array.isArray(catItem.allowedGrades) && !catItem.allowedGrades.includes(g)) {
          return {
            valid: false,
            errorCode: 'GRADE_NOT_IN_SUBJECT_CURRICULUM',
            message: `Theo Chương trình GDPT 2018, môn "${catItem.subjectName}" (${
              levelId === 'PRIMARY' ? 'Tiểu học' : 'THCS'
            }) chỉ giảng dạy ở các khối [${catItem.allowedGrades.join(', ')}], không giảng dạy ở Khối ${g}.`,
            normalizedAllocations: [],
          };
        }
      }

      normalizedAllocations.push({
        subjectId: catItem.subjectId,
        subjectName: catItem.subjectName,
        educationLevelId: levelId,
        grades,
        assessmentMode: catItem.assessmentMode || 'PAPER_EXAM',
      });
    }

    return {
      valid: true,
      normalizedAllocations,
    };
  }

  function syncTeacherPermissionGrantsWithAccountAllocations(params: {
    userId: string;
    normalizedAllocations: any[];
    actorName: string;
    isNewAccount: boolean;
  }) {
    const collections = multiTenantDb.collections as Record<string, any[]>;
    if (!Array.isArray(collections.TeacherPermissionGrants)) {
      collections.TeacherPermissionGrants = [];
    }

    const nowIso = new Date().toISOString();
    const existingActiveRecords = collections.TeacherPermissionGrants.filter(
      (r: any) => r.UserId === params.userId && r.Status === 'ACTIVE'
    );

    // Mục VIII: Không bao giờ tự động cấp toàn bộ 20 quyền cho tài khoản mới.
    // Khi tạo mới chỉ khởi tạo quyền cơ sở tối thiểu (Xem chương trình & Xem ngân hàng câu hỏi).
    // Khi chỉnh sửa môn giảng dạy của tài khoản cũ, giữ nguyên danh sách PermissionCodes hiện có của giáo viên đó.
    const existingPerms =
      existingActiveRecords.length > 0
        ? Array.from(
            new Set<string>(
              existingActiveRecords.flatMap((r: any) =>
                Array.isArray(r.PermissionCodes) ? r.PermissionCodes : []
              )
            )
          )
        : ['VIEW_CURRICULUM', 'VIEW_QUESTION_BANK'];

    const desiredComboKeys = new Set<string>();
    for (const alloc of params.normalizedAllocations) {
      for (const gradeNum of alloc.grades || []) {
        const key = `${alloc.educationLevelId}::${alloc.subjectId}::${gradeNum}`;
        desiredComboKeys.add(key);

        const matchExisting = existingActiveRecords.find(
          (r: any) =>
            r.EducationLevelId === alloc.educationLevelId &&
            r.SubjectId === alloc.subjectId &&
            Number(r.GradeId) === Number(gradeNum)
        );

        if (matchExisting) {
          matchExisting.SubjectName = alloc.subjectName;
          matchExisting.UpdatedAt = nowIso;
        } else {
          collections.TeacherPermissionGrants.push({
            id: `tpg-${params.userId}-${alloc.subjectId}-g${gradeNum}-${Date.now()}`,
            UserId: params.userId,
            EducationLevelId: alloc.educationLevelId,
            SubjectId: alloc.subjectId,
            SubjectName: alloc.subjectName,
            GradeId: Number(gradeNum),
            PermissionCodes: [...existingPerms],
            GrantedBy: params.actorName,
            GrantedAt: nowIso,
            UpdatedAt: nowIso,
            Status: 'ACTIVE',
          });
        }
      }
    }

    // Thu hồi (REVOKED) những bản ghi môn/khối không còn nằm trong phân công giảng dạy của tài khoản
    if (!params.isNewAccount) {
      for (const rec of existingActiveRecords) {
        const recKey = `${rec.EducationLevelId}::${rec.SubjectId}::${Number(rec.GradeId)}`;
        if (!desiredComboKeys.has(recKey)) {
          rec.Status = 'REVOKED';
          rec.UpdatedAt = nowIso;
        }
      }
    }
  }

  function createTeacherAccountInternal(
    body: any,
    reqSchoolId?: string
  ): {
    httpStatus: number;
    ok: boolean;
    errorCode?: string;
    message: string;
    account?: any;
    resetInviteLink?: string | null;
  } {
    ensureTeacherPermissionStoreAndTestAccounts();
    const collections = multiTenantDb.collections as Record<string, any[]>;
    const users = collections.Users || [];

    const {
      adminUserId = 'user-admin-sys',
      fullName,
      email,
      passwordSetupMethod = 'SEND_RESET_LINK',
      initialPassword,
      confirmPassword,
      mustChangePasswordOnNextLogin = true,
      departmentName = 'Tổ khoa học tự nhiên',
      educationLevels = ['LOWER_SECONDARY'],
      subjectAllocations = [],
      roles = ['TEACHER'],
      status = 'ACTIVE',
      notes = '',
    } = body || {};

    const targetSchoolId = resolveActiveSchoolIdFromRequest(
      undefined,
      reqSchoolId || body?.schoolId,
      adminUserId
    );

    // Kiểm tra quyền quản trị tại Backend (Mục IX & Mục V.6)
    const adminUser = users.find((u: any) => u.id === adminUserId);
    const isAuthorizedAdmin =
      adminUserId === 'user-admin-sys' ||
      isSchoolAdminMetaAccountId(adminUserId) ||
      (adminUser &&
        Array.isArray(adminUser.roles) &&
        adminUser.roles.some((r: string) =>
          ['SYSTEM_ADMIN', 'SCHOOL_ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL'].includes(r)
        ));

    if (!isAuthorizedAdmin) {
      return {
        httpStatus: 403,
        ok: false,
        errorCode: 'ADMIN_AUTHORITY_REQUIRED',
        message: 'Từ chối tại Backend (HTTP 403): Chỉ Quản trị hệ thống hoặc Ban Giám hiệu mới có thẩm quyền tạo tài khoản giáo viên.',
      };
    }

    const trimmedName = String(fullName || '').trim();
    if (!trimmedName || trimmedName.length < 2) {
      return {
        httpStatus: 400,
        ok: false,
        errorCode: 'INVALID_FULL_NAME',
        message: 'Vui lòng nhập Họ và tên giáo viên hợp lệ (tối thiểu 2 ký tự).',
      };
    }

    const normalizedEmail = String(email || '').trim().toLowerCase();
    if (!normalizedEmail || !EMAIL_REGEX_STRICT.test(normalizedEmail)) {
      return {
        httpStatus: 400,
        ok: false,
        errorCode: 'INVALID_EMAIL_FORMAT',
        message: `Email đăng nhập "${email || ''}" không đúng định dạng chuẩn (ví dụ: ten.giaovien@nguyendinhanh.edu.vn).`,
      };
    }

    // Kiểm tra Tổ chuyên môn phải nằm trong danh mục tổ chuyên môn đang hoạt động của nhà trường (Mục III.1 & IV.5)
    const rawDept = String(departmentName || '').trim();
    const activeDepts = getActiveDepartmentNamesCatalog();
    if (!rawDept || !activeDepts.includes(rawDept)) {
      return {
        httpStatus: 400,
        ok: false,
        errorCode: 'DEPARTMENT_NOT_FOUND',
        message: `Tổ chuyên môn "${rawDept || '(Trống)'}" không tồn tại trong danh mục tổ chuyên môn của trường (${activeDepts.join(', ')}).`,
      };
    }

    // Mục III.2: Kiểm tra trùng email trên toàn hệ thống xác thực
    const duplicateUser = users.find(
      (u: any) => String(u.email || '').trim().toLowerCase() === normalizedEmail
    );
    if (duplicateUser) {
      return {
        httpStatus: 409,
        ok: false,
        errorCode: 'EMAIL_ALREADY_EXISTS',
        message: `Email đăng nhập "${normalizedEmail}" đã tồn tại trên hệ thống (Thuộc tài khoản: ${duplicateUser.fullName} [${duplicateUser.id}]). Không cho phép tạo trùng email.`,
      };
    }

    const validRoles = (Array.isArray(roles) ? roles : ['TEACHER']).filter((r: string) =>
      VALID_ACTOR_ROLES.has(r)
    );
    const finalRoles = validRoles.length > 0 ? validRoles : ['TEACHER'];

    // Kiểm tra bắt buộc phân công môn giảng dạy đối với tài khoản giáo viên (Mục I.4)
    if (
      !finalRoles.includes('SYSTEM_ADMIN') &&
      (!Array.isArray(subjectAllocations) || subjectAllocations.length === 0)
    ) {
      return {
        httpStatus: 400,
        ok: false,
        errorCode: 'MISSING_SUBJECT_ALLOCATION',
        message: 'Thiếu thông tin bắt buộc: Vui lòng phân công ít nhất 1 môn giảng dạy và khối lớp cho giáo viên.',
      };
    }

    // Mục IV: Kiểm tra quy tắc cấp học – môn học – khối lớp từ CSDL chương trình
    const allocValidation = validateSubjectAllocationsAgainstCurriculum(
      educationLevels,
      subjectAllocations
    );
    if (!allocValidation.valid) {
      return {
        httpStatus: 400,
        ok: false,
        errorCode: allocValidation.errorCode || 'INVALID_SUBJECT_ALLOCATION',
        message: allocValidation.message || 'Phân công môn học và khối lớp không hợp lệ.',
      };
    }

    // Mục VI: Xử lý mật khẩu an toàn tại Backend (PBKDF2 hoặc Gửi liên kết thiết lập mật khẩu)
    let passwordHashFull = '';
    let resetInviteLink: string | null = null;
    let passwordResetTokenHash: string | null = null;
    let passwordResetExpiresAt: string | null = null;
    const nowIso = new Date().toISOString();

    if (passwordSetupMethod === 'ADMIN_SET_INITIAL_PASSWORD') {
      const rawPass = String(initialPassword || '');
      const rawConfirm = String(confirmPassword ?? initialPassword ?? '');
      if (rawPass.length < 8) {
        return {
          httpStatus: 400,
          ok: false,
          errorCode: 'WEAK_INITIAL_PASSWORD',
          message: 'Mật khẩu ban đầu phải có ít nhất 8 ký tự.',
        };
      }
      if (rawPass !== rawConfirm) {
        return {
          httpStatus: 400,
          ok: false,
          errorCode: 'PASSWORD_CONFIRMATION_MISMATCH',
          message: 'Mật khẩu xác nhận không trùng khớp với mật khẩu ban đầu.',
        };
      }
      passwordHashFull = hashPasswordPBKDF2(rawPass).fullHash;
    } else {
      // SEND_RESET_LINK: Tạo mật khẩu ngẫu nhiên một chiều trong DB và phát hành liên kết thiết lập mật khẩu một lần
      const randomOneTimeSecret = crypto.randomBytes(24).toString('hex');
      passwordHashFull = hashPasswordPBKDF2(randomOneTimeSecret).fullHash;
      const resetToken = crypto.randomBytes(16).toString('hex');
      passwordResetTokenHash = crypto.createHash('sha256').update(resetToken).digest('hex');
      passwordResetExpiresAt = new Date(Date.now() + 24 * 3600 * 1000).toISOString();
      resetInviteLink = `https://edutest.nguyendinhanh.edu.vn/auth/setup-password?token=${resetToken}&uid=pending`;
    }

    // Mục IX: Sinh ID ổn định duy nhất (bất biến), tuyệt đối không dùng email làm khóa chính
    const stableUserId = `user-gv-${Date.now()}-${crypto.randomBytes(3).toString('hex')}`;
    if (resetInviteLink) {
      resetInviteLink = resetInviteLink.replace('uid=pending', `uid=${stableUserId}`);
    }

    const baseUsername = normalizedEmail.split('@')[0].replace(/[^a-z0-9._-]/g, '');
    const uniqueUsername = users.some((u: any) => u.username === baseUsername)
      ? `${baseUsername}.${stableUserId.slice(-4)}`
      : baseUsername;

    const finalStatus = VALID_ACCOUNT_STATUSES.has(status) ? status : 'ACTIVE';

    const assignedSubjectsFlat = Array.from(
      new Set(allocValidation.normalizedAllocations.map((a: any) => a.subjectName))
    );
    const assignedGradesFlat = Array.from(
      new Set(allocValidation.normalizedAllocations.flatMap((a: any) => a.grades))
    ).sort((a: any, b: any) => Number(a) - Number(b));

    const actorName = adminUser ? adminUser.fullName : 'Quản trị hệ thống (admin.nda)';

    const newUserRecord = {
      id: stableUserId,
      schoolId: targetSchoolId,
      username: uniqueUsername,
      email: normalizedEmail,
      fullName: trimmedName,
      roles: finalRoles,
      status: finalStatus,
      departmentId: 'DEPT_CUSTOM',
      departmentName: rawDept,
      educationLevels: Array.from(new Set(educationLevels)),
      subjectAllocations: allocValidation.normalizedAllocations,
      assignedSubjects: assignedSubjectsFlat,
      assignedGrades: assignedGradesFlat,
      assignedDossierIds: [],
      delegatedApprovalAuthority: false,
      notes: String(notes || '').trim(),
      mustChangePasswordOnNextLogin: Boolean(mustChangePasswordOnNextLogin),
      passwordSetupMethod,
      lastPasswordResetLinkSentAt:
        passwordSetupMethod === 'SEND_RESET_LINK' ? nowIso : null,
      passwordResetTokenHash,
      passwordResetExpiresAt,
      passwordHashFull, // Chỉ lưu băm PBKDF2 tại Backend DB, tuyệt đối không lưu vào Firestore hay trả về API
      lastLoginAt: null,
      loginHistory: [],
      createdBy: actorName,
      createdAt: nowIso,
      updatedAt: nowIso,
    };

    users.push(newUserRecord);

    // Đồng bộ sang TeacherPermissionGrants với quyền tối thiểu ban đầu (Mục VIII: Không tự động cấp toàn bộ quyền)
    syncTeacherPermissionGrantsWithAccountAllocations({
      userId: stableUserId,
      normalizedAllocations: allocValidation.normalizedAllocations,
      actorName,
      isNewAccount: true,
    });

    // Ghi nhật ký AuditLogs mà TUYỆT ĐỐI KHÔNG GHI MẬT KHẨU (Mục VI)
    appendAuditLog({
      schoolId: targetSchoolId,
      actorUserId: adminUserId,
      actorName,
      actorRoles: adminUser?.roles || ['SYSTEM_ADMIN'],
      action: 'CREATE_TEACHER_ACCOUNT',
      targetType: 'USER_ACCOUNT',
      targetId: stableUserId,
      summary: `Tạo mới tài khoản giáo viên: ${trimmedName} (${normalizedEmail}) · ID ổn định: ${stableUserId} · Tổ: ${newUserRecord.departmentName} · Trạng thái: ${finalStatus} · Phương thức mật khẩu: ${passwordSetupMethod}.`,
      httpStatus: 201,
      status: 'ALLOWED',
    });

    saveMultiTenantDb(multiTenantDb);

    const safeRecord = buildSafeTeacherAccountRecord(newUserRecord, users.length - 1);
    return {
      httpStatus: 201,
      ok: true,
      message: `Đã tạo tài khoản giáo viên "${trimmedName}" (${normalizedEmail}) thành công với mã định danh ổn định [${stableUserId}].`,
      account: safeRecord,
      resetInviteLink,
    };
  }

  function updateTeacherAccountInternal(userId: string, body: any): {
    httpStatus: number;
    ok: boolean;
    errorCode?: string;
    message: string;
    account?: any;
  } {
    ensureTeacherPermissionStoreAndTestAccounts();
    const collections = multiTenantDb.collections as Record<string, any[]>;
    const users = collections.Users || [];
    const targetIndex = users.findIndex((u: any) => u.id === userId);

    if (targetIndex === -1) {
      return {
        httpStatus: 404,
        ok: false,
        errorCode: 'ACCOUNT_NOT_FOUND',
        message: `Không tìm thấy tài khoản có mã định danh [${userId}].`,
      };
    }

    const adminUserId = body?.adminUserId || 'user-admin-sys';
    const adminUser = users.find((u: any) => u.id === adminUserId);
    const isAuthorizedAdmin =
      adminUserId === 'user-admin-sys' ||
      isSchoolAdminMetaAccountId(adminUserId) ||
      (adminUser &&
        Array.isArray(adminUser.roles) &&
        adminUser.roles.some((r: string) =>
          ['SYSTEM_ADMIN', 'SCHOOL_ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL'].includes(r)
        ));

    if (!isAuthorizedAdmin) {
      appendAuditLog({
        schoolId: 'SCHOOL_A',
        actorUserId: String(adminUserId),
        actorName: String(adminUser?.fullName || adminUserId),
        actorRoles: adminUser?.roles || ['TEACHER'],
        action: 'UNAUTHORIZED_ACCOUNT_EDIT_BLOCKED',
        targetType: 'USER_ACCOUNT',
        targetId: userId,
        summary: `Chặn chỉnh sửa tài khoản trái phép: Người dùng [${adminUserId}] không có quyền quản trị để sửa tài khoản [${userId}].`,
        httpStatus: 403,
        status: 'DENIED',
      });
      return {
        httpStatus: 403,
        ok: false,
        errorCode: 'ADMIN_AUTHORITY_REQUIRED',
        message: 'Từ chối bảo mật (HTTP 403): Tài khoản không có thẩm quyền chỉnh sửa thông tin tài khoản giáo viên khác.',
      };
    }

    // Mục V: Không cho phép sửa ID tài khoản
    if (body && body.id && String(body.id) !== String(userId)) {
      return {
        httpStatus: 400,
        ok: false,
        errorCode: 'IMMUTABLE_ACCOUNT_ID',
        message: 'Vi phạm quy tắc toàn vẹn (Mục V & IX): Không được phép thay đổi mã định danh gốc (ID) của tài khoản.',
      };
    }

    const userRecord = users[targetIndex];
    const actorName = adminUser ? adminUser.fullName : 'Quản trị hệ thống (admin.nda)';

    const nextFullName =
      body.fullName !== undefined ? String(body.fullName).trim() : userRecord.fullName;
    if (!nextFullName || nextFullName.length < 2) {
      return {
        httpStatus: 400,
        ok: false,
        errorCode: 'INVALID_FULL_NAME',
        message: 'Họ và tên giáo viên không được để trống.',
      };
    }

    const nextEmail =
      body.email !== undefined
        ? String(body.email).trim().toLowerCase()
        : String(userRecord.email || '').trim().toLowerCase();

    if (!nextEmail || !EMAIL_REGEX_STRICT.test(nextEmail)) {
      return {
        httpStatus: 400,
        ok: false,
        errorCode: 'INVALID_EMAIL_FORMAT',
        message: `Email đăng nhập "${body.email || ''}" không đúng định dạng chuẩn.`,
      };
    }

    // Mục V: Nếu thay đổi email đăng nhập, kiểm tra trùng lặp với các tài khoản khác và cập nhật đồng bộ
    const emailConflictUser = users.find(
      (u: any) =>
        u.id !== userId && String(u.email || '').trim().toLowerCase() === nextEmail
    );
    if (emailConflictUser) {
      return {
        httpStatus: 409,
        ok: false,
        errorCode: 'EMAIL_ALREADY_EXISTS',
        message: `Không thể đổi sang email "${nextEmail}" vì đang được sử dụng bởi tài khoản ${emailConflictUser.fullName} (${emailConflictUser.id}).`,
      };
    }

    if (body.departmentName !== undefined) {
      const requestedDept = String(body.departmentName || '').trim();
      const activeDepts = getActiveDepartmentNamesCatalog();
      if (!requestedDept || !activeDepts.includes(requestedDept)) {
        return {
          httpStatus: 400,
          ok: false,
          errorCode: 'DEPARTMENT_NOT_FOUND',
          message: `Tổ chuyên môn "${requestedDept || '(Trống)'}" không tồn tại trong danh mục tổ chuyên môn đang hoạt động của trường.`,
        };
      }
    }

    const nextEducationLevels =
      body.educationLevels !== undefined
        ? body.educationLevels
        : userRecord.educationLevels || ['LOWER_SECONDARY'];

    const nextSubjectAllocations =
      body.subjectAllocations !== undefined
        ? body.subjectAllocations
        : buildSafeTeacherAccountRecord(userRecord, targetIndex).subjectAllocations;

    const allocValidation = validateSubjectAllocationsAgainstCurriculum(
      nextEducationLevels,
      nextSubjectAllocations
    );
    if (!allocValidation.valid) {
      return {
        httpStatus: 400,
        ok: false,
        errorCode: allocValidation.errorCode || 'INVALID_SUBJECT_ALLOCATION',
        message: allocValidation.message || 'Phân công môn học và khối lớp không hợp lệ.',
      };
    }

    const nextRoles =
      body.roles !== undefined && Array.isArray(body.roles)
        ? body.roles.filter((r: string) => VALID_ACTOR_ROLES.has(r))
        : userRecord.roles;

    if (!Array.isArray(nextRoles) || nextRoles.length === 0) {
      return {
        httpStatus: 400,
        ok: false,
        errorCode: 'EMPTY_ROLES',
        message: 'Tài khoản phải có ít nhất một vai trò hợp lệ.',
      };
    }

    const nextStatus =
      body.status !== undefined && VALID_ACCOUNT_STATUSES.has(body.status)
        ? body.status
        : userRecord.status || 'ACTIVE';

    const previousEmail = userRecord.email;
    userRecord.fullName = nextFullName;
    userRecord.email = nextEmail;
    userRecord.departmentName =
      body.departmentName !== undefined
        ? String(body.departmentName).trim()
        : normalizeOfficialDepartmentName(userRecord.departmentName, nextRoles);
    userRecord.educationLevels = Array.from(new Set(nextEducationLevels));
    userRecord.subjectAllocations = allocValidation.normalizedAllocations;
    userRecord.assignedSubjects = Array.from(
      new Set(allocValidation.normalizedAllocations.map((a: any) => a.subjectName))
    );
    userRecord.assignedGrades = Array.from(
      new Set(allocValidation.normalizedAllocations.flatMap((a: any) => a.grades))
    ).sort((a: any, b: any) => Number(a) - Number(b));
    userRecord.roles = nextRoles;
    userRecord.status = nextStatus;
    if (body.notes !== undefined) {
      userRecord.notes = String(body.notes).trim();
    }
    if (body.delegatedApprovalAuthority !== undefined) {
      userRecord.delegatedApprovalAuthority = Boolean(body.delegatedApprovalAuthority);
    }
    userRecord.updatedAt = new Date().toISOString();

    // Nếu trạng thái chuyển sang LOCKED, DISABLED hoặc UNACTIVATED -> Thu hồi ngay phiên đăng nhập đang mở (Mục VII)
    if (nextStatus !== 'ACTIVE') {
      revokeAllOpenSessionsForUser(userId);
    }

    // Đồng bộ môn học thêm/thu hồi sang bảng phân quyền TeacherPermissionGrants (Bảo toàn toàn bộ quyền chức năng khác đang có)
    syncTeacherPermissionGrantsWithAccountAllocations({
      userId,
      normalizedAllocations: allocValidation.normalizedAllocations,
      actorName,
      isNewAccount: false,
    });

    // Đồng bộ Họ tên, Email và Tổ chuyên môn sang các bản ghi Phân công giảng dạy hiện có của giáo viên
    const targetDeptObj = (collections.SchoolDepartments || []).find(
      (d: any) =>
        (d.schoolId || 'SCHOOL_A') === (userRecord.schoolId || 'SCHOOL_A') &&
        d.departmentName === userRecord.departmentName
    );
    (collections.TeachingAssignments || []).forEach((ta: any) => {
      if (ta.teacherUserId === userId) {
        ta.teacherFullName = userRecord.fullName;
        ta.teacherEmail = userRecord.email;
        ta.departmentName = userRecord.departmentName;
        if (targetDeptObj) {
          ta.departmentId = targetDeptObj.id;
        }
        ta.updatedAt = userRecord.updatedAt;
      }
    });

    appendAuditLog({
      schoolId: 'SCHOOL_A',
      actorUserId: adminUserId,
      actorName,
      actorRoles: adminUser?.roles || ['SYSTEM_ADMIN'],
      action: 'UPDATE_TEACHER_ACCOUNT',
      targetType: 'USER_ACCOUNT',
      targetId: userId,
      summary: `Cập nhật tài khoản [${userId}] ${userRecord.fullName} (${
        previousEmail !== nextEmail ? `Đổi email ${previousEmail} -> ${nextEmail}; ` : ''
      }Tổ: ${userRecord.departmentName}; Vai trò: ${nextRoles.join(', ')}; Trạng thái: ${nextStatus}).`,
      httpStatus: 200,
      status: 'ALLOWED',
    });

    saveMultiTenantDb(multiTenantDb);

    return {
      httpStatus: 200,
      ok: true,
      message: `Đã cập nhật thông tin tài khoản "${userRecord.fullName}" (${userRecord.email}) thành công.`,
      account: buildSafeTeacherAccountRecord(userRecord, targetIndex),
    };
  }

  // 1. Lấy danh sách toàn bộ tài khoản giáo viên kèm bộ lọc, danh mục môn học theo cấp và tổ chuyên môn (Mục I & II)
  app.get('/api/admin/teacher-accounts', (req, res) => {
    multiTenantDb = loadMultiTenantDb();
    ensureTeacherPermissionStoreAndTestAccounts();
    const targetSchoolId = resolveActiveSchoolIdFromRequest(req);
    const collections = multiTenantDb.collections as Record<string, any[]>;
    const schoolUsers = (collections.Users || [])
      .filter(
        (u: any) =>
          u.schoolId === targetSchoolId &&
          !isSchoolAdminMetaAccountId(u.id) &&
          !isPurgedTestUserId(u.id)
      )
      .sort((a: any, b: any) => (a.orderNumber || 999) - (b.orderNumber || 999));

    const lookupIndex = buildTeacherPermissionLookupIndex();
    const accounts = schoolUsers.map((u: any, idx: number) =>
      buildSafeTeacherAccountRecord(u, idx, lookupIndex)
    );
    const allCurriculumSubjects =
      collections.SchoolCurriculumSubjects || INITIAL_SCHOOL_CURRICULUM_SUBJECTS;
    const curriculumSubjects = allCurriculumSubjects.filter((c: any) => {
      if (targetSchoolId === 'SCHOOL_B') return c.educationLevelId === 'PRIMARY';
      if (targetSchoolId === 'SCHOOL_C') return c.educationLevelId === 'LOWER_SECONDARY';
      return true;
    });

    res.status(200).json({
      ok: true,
      schoolId: targetSchoolId,
      accounts,
      curriculumSubjects,
      departmentsCatalog: getActiveDepartmentNamesCatalog(targetSchoolId),
      teachingAssignments: (collections.TeachingAssignments || []).filter(
        (ta: any) => ta.schoolId === targetSchoolId
      ),
    });
  });

  // 2. Tạo tài khoản giáo viên mới (Mục III, IV, VI, VIII, IX)
  app.post('/api/admin/teacher-accounts/create', (req, res) => {
    multiTenantDb = loadMultiTenantDb();
    const targetSchoolId = resolveActiveSchoolIdFromRequest(req);
    const result = createTeacherAccountInternal(req.body || {}, targetSchoolId);
    res.status(result.httpStatus).json(result);
  });

  // 3. Chỉnh sửa thông tin tài khoản giáo viên (Mục V)
  app.put('/api/admin/teacher-accounts/:userId', (req, res) => {
    multiTenantDb = loadMultiTenantDb();
    const userId = String(req.params.userId || '').trim();
    const result = updateTeacherAccountInternal(userId, req.body || {});
    res.status(result.httpStatus).json(result);
  });

  // 4. Khóa / Mở khóa / Vô hiệu hóa tài khoản giáo viên (Mục I & VII)
  app.post('/api/admin/teacher-accounts/:userId/status', (req, res) => {
    multiTenantDb = loadMultiTenantDb();
    ensureTeacherPermissionStoreAndTestAccounts();
    const userId = String(req.params.userId || '').trim();
    const { status, reason = '', adminUserId = 'user-admin-sys' } = req.body || {};

    const collections = multiTenantDb.collections as Record<string, any[]>;
    const users = collections.Users || [];
    const adminUser = users.find((u: any) => u.id === adminUserId);
    const isAuthorizedAdmin =
      adminUserId === 'user-admin-sys' ||
      isSchoolAdminMetaAccountId(adminUserId) ||
      (adminUser &&
        Array.isArray(adminUser.roles) &&
        adminUser.roles.some((r: string) =>
          ['SYSTEM_ADMIN', 'SCHOOL_ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL'].includes(r)
        ));

    if (!isAuthorizedAdmin) {
      res.status(403).json({
        ok: false,
        errorCode: 'ADMIN_AUTHORITY_REQUIRED',
        message: 'Từ chối bảo mật (HTTP 403): Chỉ Quản trị viên hoặc Ban Giám hiệu mới có quyền khóa/mở khóa tài khoản.',
      });
      return;
    }

    if (!VALID_ACCOUNT_STATUSES.has(status)) {
      res.status(400).json({
        ok: false,
        errorCode: 'INVALID_ACCOUNT_STATUS',
        message: 'Trạng thái tài khoản không hợp lệ. Chỉ chấp nhận UNACTIVATED, ACTIVE, LOCKED hoặc DISABLED.',
      });
      return;
    }

    const targetIndex = users.findIndex((u: any) => u.id === userId);
    if (targetIndex === -1) {
      res.status(404).json({
        ok: false,
        errorCode: 'ACCOUNT_NOT_FOUND',
        message: `Không tìm thấy tài khoản [${userId}].`,
      });
      return;
    }

    const userRecord = users[targetIndex];
    const prevStatus = userRecord.status || 'ACTIVE';
    userRecord.status = status;
    userRecord.updatedAt = new Date().toISOString();

    if (status !== 'ACTIVE') {
      revokeAllOpenSessionsForUser(userId);
    }

    appendAuditLog({
      schoolId: 'SCHOOL_A',
      actorUserId: adminUserId,
      actorName: adminUser?.fullName || 'Quản trị hệ thống (admin.nda)',
      actorRoles: adminUser?.roles || ['SYSTEM_ADMIN'],
      action:
        status === 'LOCKED'
          ? 'LOCK_TEACHER_ACCOUNT'
          : status === 'DISABLED'
          ? 'DISABLE_TEACHER_ACCOUNT'
          : 'UNLOCK_TEACHER_ACCOUNT',
      targetType: 'USER_ACCOUNT',
      targetId: userId,
      summary: `Chuyển trạng thái tài khoản ${userRecord.fullName} (${userRecord.email}) từ [${prevStatus}] sang [${status}]${reason ? ` · Lý do: ${reason}` : ''}.`,
      httpStatus: 200,
      status: 'ALLOWED',
    });

    saveMultiTenantDb(multiTenantDb);

    res.status(200).json({
      ok: true,
      message: `Đã cập nhật trạng thái tài khoản "${userRecord.fullName}" sang [${status}].`,
      account: buildSafeTeacherAccountRecord(userRecord, targetIndex),
    });
  });

  // 5. Đặt lại mật khẩu an toàn / Gửi liên kết đặt lại mật khẩu (Mục III & VI)
  // TUYỆT ĐỐI KHÔNG HIỂN THỊ MẬT KHẨU HIỆN TẠI, KHÔNG LƯU PLAINTEXT VÀO FIRESTORE, KHÔNG GHI LOG MẬT KHẨU
  function resetTeacherPasswordInternal(params: {
    userId: string;
    method?: string;
    newPassword?: string;
    confirmPassword?: string;
    mustChangePasswordOnNextLogin?: boolean;
    adminUserId?: string;
    expiresInSeconds?: number;
  }) {
    ensureTeacherPermissionStoreAndTestAccounts();
    const {
      userId,
      method = 'SEND_RESET_LINK',
      newPassword,
      confirmPassword,
      mustChangePasswordOnNextLogin = true,
      adminUserId = 'user-admin-sys',
      expiresInSeconds = 86400,
    } = params;

    const collections = multiTenantDb.collections as Record<string, any[]>;
    const users = collections.Users || [];
    const adminUser = users.find((u: any) => u.id === adminUserId);
    const isAuthorizedAdmin =
      adminUserId === 'user-admin-sys' ||
      (adminUser &&
        Array.isArray(adminUser.roles) &&
        adminUser.roles.some((r: string) =>
          ['SYSTEM_ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL'].includes(r)
        ));

    if (!isAuthorizedAdmin) {
      return {
        httpStatus: 403,
        ok: false,
        errorCode: 'ADMIN_AUTHORITY_REQUIRED',
        message: 'Từ chối bảo mật (HTTP 403): Chỉ Quản trị viên hoặc Ban Giám hiệu mới có quyền đặt lại mật khẩu tài khoản.',
      };
    }

    const targetIndex = users.findIndex((u: any) => u.id === userId);
    if (targetIndex === -1) {
      return {
        httpStatus: 404,
        ok: false,
        errorCode: 'ACCOUNT_NOT_FOUND',
        message: `Không tìm thấy tài khoản [${userId}].`,
      };
    }

    const userRecord = users[targetIndex];

    // Mục III.3: Kiểm tra tài khoản bị khóa khi đặt lại mật khẩu
    if (userRecord.status === 'LOCKED' || userRecord.status === 'DISABLED') {
      return {
        httpStatus: 403,
        ok: false,
        errorCode: 'ACCOUNT_LOCKED',
        message: `Tài khoản "${userRecord.fullName}" hiện đang bị khóa/vô hiệu hóa ([${userRecord.status}]). Vui lòng mở khóa tài khoản trước khi sử dụng liên kết đặt lại mật khẩu.`,
      };
    }

    const nowIso = new Date().toISOString();
    let resetInviteLink: string | null = null;
    let resetTokenPlain: string | null = null;
    let passwordResetExpiresAt: string | null = null;

    if (method === 'ADMIN_SET_INITIAL_PASSWORD') {
      const rawPass = String(newPassword || '');
      const rawConfirm = String(confirmPassword ?? newPassword ?? '');
      if (rawPass.length < 8) {
        return {
          httpStatus: 400,
          ok: false,
          errorCode: 'WEAK_PASSWORD',
          message: 'Mật khẩu đặt lại phải có ít nhất 8 ký tự.',
        };
      }
      if (rawPass !== rawConfirm) {
        return {
          httpStatus: 400,
          ok: false,
          errorCode: 'PASSWORD_CONFIRMATION_MISMATCH',
          message: 'Mật khẩu xác nhận không trùng khớp.',
        };
      }
      userRecord.passwordHashFull = hashPasswordPBKDF2(rawPass).fullHash;
      userRecord.passwordSetupMethod = 'ADMIN_SET_INITIAL_PASSWORD';
      userRecord.mustChangePasswordOnNextLogin = Boolean(mustChangePasswordOnNextLogin);
    } else {
      resetTokenPlain = crypto.randomBytes(16).toString('hex');
      const tokenHash = crypto.createHash('sha256').update(resetTokenPlain).digest('hex');
      passwordResetExpiresAt = new Date(
        Date.now() + Number(expiresInSeconds) * 1000
      ).toISOString();
      resetInviteLink = `https://edutest.nguyendinhanh.edu.vn/auth/reset-password?token=${resetTokenPlain}&uid=${encodeURIComponent(
        userId
      )}&exp=${encodeURIComponent(passwordResetExpiresAt)}`;
      userRecord.passwordSetupMethod = 'SEND_RESET_LINK';
      userRecord.lastPasswordResetLinkSentAt = nowIso;
      userRecord.passwordResetTokenHash = tokenHash;
      userRecord.passwordResetExpiresAt = passwordResetExpiresAt;
      userRecord.mustChangePasswordOnNextLogin = true;
    }

    userRecord.updatedAt = nowIso;

    // Ghi log kiểm toán mà TUYỆT ĐỐI KHÔNG CHỨA MẬT KHẨU HAY TOKEN BÍ MẬT
    appendAuditLog({
      schoolId: 'SCHOOL_A',
      actorUserId: adminUserId,
      actorName: adminUser?.fullName || 'Quản trị hệ thống (admin.nda)',
      actorRoles: adminUser?.roles || ['SYSTEM_ADMIN'],
      action: 'RESET_TEACHER_PASSWORD',
      targetType: 'USER_ACCOUNT',
      targetId: userId,
      summary: `Đặt lại mật khẩu an toàn cho tài khoản ${userRecord.fullName} (${userRecord.email}) bằng phương thức [${method}] · Yêu cầu đổi mật khẩu lần đăng nhập kế tiếp: ${Boolean(
        userRecord.mustChangePasswordOnNextLogin
      )}.`,
      httpStatus: 200,
      status: 'ALLOWED',
    });

    saveMultiTenantDb(multiTenantDb);

    return {
      httpStatus: 200,
      ok: true,
      method,
      resetInviteLink,
      resetToken: resetTokenPlain,
      passwordResetExpiresAt,
      mustChangePasswordOnNextLogin: Boolean(userRecord.mustChangePasswordOnNextLogin),
      message:
        method === 'SEND_RESET_LINK'
          ? `Đã phát hành liên kết đặt lại mật khẩu một lần gửi tới email ${userRecord.email} (Hết hạn lúc ${passwordResetExpiresAt}).`
          : `Đã cập nhật mật khẩu băm một chiều (PBKDF2) cho tài khoản ${userRecord.fullName} và bật cờ yêu cầu đổi mật khẩu ở lần đăng nhập kế tiếp.`,
      account: buildSafeTeacherAccountRecord(userRecord, targetIndex),
    };
  }

  function consumePasswordResetTokenInternal(params: {
    userId: string;
    token: string;
    newPassword: string;
    confirmPassword?: string;
  }) {
    ensureTeacherPermissionStoreAndTestAccounts();
    const { userId, token, newPassword, confirmPassword } = params;
    const collections = multiTenantDb.collections as Record<string, any[]>;
    const users = collections.Users || [];
    const userRecord = users.find((u: any) => u.id === userId);
    if (!userRecord) {
      return {
        httpStatus: 404,
        ok: false,
        errorCode: 'ACCOUNT_NOT_FOUND',
        message: 'Không tìm thấy tài khoản yêu cầu đặt lại mật khẩu.',
      };
    }

    if (userRecord.status === 'LOCKED' || userRecord.status === 'DISABLED') {
      return {
        httpStatus: 403,
        ok: false,
        errorCode: 'ACCOUNT_LOCKED',
        message: `Từ chối đặt lại mật khẩu (HTTP 403): Tài khoản ${userRecord.fullName} đang bị khóa ([${userRecord.status}]).`,
      };
    }

    const providedHash = crypto
      .createHash('sha256')
      .update(String(token || ''))
      .digest('hex');
    if (
      !userRecord.passwordResetTokenHash ||
      userRecord.passwordResetTokenHash !== providedHash
    ) {
      return {
        httpStatus: 400,
        ok: false,
        errorCode: 'INVALID_RESET_TOKEN',
        message: 'Liên kết đặt lại mật khẩu không hợp lệ hoặc đã được sử dụng.',
      };
    }

    const expMs = userRecord.passwordResetExpiresAt
      ? new Date(userRecord.passwordResetExpiresAt).getTime()
      : 0;
    if (!expMs || Date.now() > expMs) {
      return {
        httpStatus: 410,
        ok: false,
        errorCode: 'RESET_LINK_EXPIRED',
        message: `Liên kết đặt lại mật khẩu đã hết hạn vào lúc ${userRecord.passwordResetExpiresAt}. Vui lòng yêu cầu Quản trị viên gửi liên kết mới.`,
      };
    }

    const rawPass = String(newPassword || '');
    const rawConfirm = String(confirmPassword ?? newPassword ?? '');
    if (rawPass.length < 8 || rawPass !== rawConfirm) {
      return {
        httpStatus: 400,
        ok: false,
        errorCode: 'INVALID_NEW_PASSWORD',
        message: 'Mật khẩu mới phải từ 8 ký tự trở lên và khớp xác nhận.',
      };
    }

    userRecord.passwordHashFull = hashPasswordPBKDF2(rawPass).fullHash;
    userRecord.passwordResetTokenHash = null;
    userRecord.passwordResetExpiresAt = null;
    userRecord.mustChangePasswordOnNextLogin = false;
    userRecord.updatedAt = new Date().toISOString();
    saveMultiTenantDb(multiTenantDb);

    return {
      httpStatus: 200,
      ok: true,
      errorCode: 'PASSWORD_RESET_COMPLETED',
      message: 'Đã thiết lập mật khẩu mới thành công bằng liên kết một lần.',
    };
  }

  app.post('/api/admin/teacher-accounts/:userId/reset-password', (req, res) => {
    multiTenantDb = loadMultiTenantDb();
    const userId = String(req.params.userId || '').trim();
    const result = resetTeacherPasswordInternal({
      userId,
      ...(req.body || {}),
    });
    res.status(result.httpStatus).json(result);
  });

  app.post('/api/auth/reset-password-with-token', (req, res) => {
    multiTenantDb = loadMultiTenantDb();
    const { userId, token, newPassword, confirmPassword } = req.body || {};
    const result = consumePasswordResetTokenInternal({
      userId: String(userId || '').trim(),
      token: String(token || '').trim(),
      newPassword: String(newPassword || ''),
      confirmPassword,
    });
    res.status(result.httpStatus).json(result);
  });

