    const isTemporaryQaEmail = (em: string) => {
      const lower = String(em || '').trim().toLowerCase();
      return (
        [
          testEmail,
          editedEmail,
          unactivatedEmail,
          'thieu.hoten@nguyendinhanh.edu.vn',
          'thieu.mon@nguyendinhanh.edu.vn',
        ].includes(lower) || /\.xl\d+@nguyendinhanh\.edu\.vn$/i.test(lower)
      );
    };
    const tempUserIds = new Set(
      (collections.Users || [])
        .filter((u: any) => isTemporaryQaEmail(u.email))
        .map((u: any) => u.id)
    );
    if (tempUserIds.size > 0) {
      collections.Users = (collections.Users || []).filter(
        (u: any) => !tempUserIds.has(u.id)
      );
      collections.TeacherPermissionGrants = (
        collections.TeacherPermissionGrants || []
      ).filter((g: any) => !tempUserIds.has(g.UserId));
      saveMultiTenantDb(multiTenantDb);
    }

    // Lưu snapshot dữ liệu sạch trước khi chạy bộ kiểm thử nghiệm thu
    const snapshotUsers = JSON.parse(JSON.stringify(collections.Users || []));
    const snapshotGrants = JSON.parse(
      JSON.stringify(collections.TeacherPermissionGrants || [])
    );
    const snapshotWorkflows = JSON.parse(
      JSON.stringify(collections.ExamWorkflows || [])
    );

    // Đảm bảo có ít nhất 1 hồ sơ kiểm tra đã phê duyệt của tài khoản kiểm thử để kiểm chứng "Không làm thay đổi hồ sơ kiểm tra đã phê duyệt"
    const approvedWorkflowSnapshotBefore = JSON.stringify(
      (collections.ExamWorkflows || []).filter(
        (w: any) => w.status === 'Approved' || w.status === 'APPROVED'
      )
    );

    // =========================================================================
    // I. KIỂM TRA TẠO TÀI KHOẢN (6 KỊCH BẢN: TC-I-01 -> TC-I-06)
    // =========================================================================
