  // ============================================================================
  // GIAI ĐOẠN 17: KẾT NỐI FIREBASE VÀ XÂY DỰNG HỆ THỐNG LƯU TRỮ DỮ LIỆU THỰC
  // ============================================================================

  function ensureStage17CentralStore() {
    const cols = multiTenantDb.collections as Record<string, any>;
    if (!cols.SchoolCentralDomainStore || typeof cols.SchoolCentralDomainStore !== 'object') {
      cols.SchoolCentralDomainStore = {};
    } else {
      let migrated = false;
      for (const storeEntry of Object.values(cols.SchoolCentralDomainStore)) {
        if (
          storeEntry &&
          typeof storeEntry === 'object' &&
          (storeEntry as any).config &&
          typeof (storeEntry as any).config.schoolName === 'string' &&
          (storeEntry as any).config.schoolName.includes('Nguyễn Du')
        ) {
          (storeEntry as any).config.schoolName = 'Trường TH &THCS Nguyễn Đình Anh';
          migrated = true;
        }
      }
      if (migrated) {
        saveMultiTenantDb(multiTenantDb);
      }
    }
    if (!Array.isArray(cols.FirebaseConnectionProbes)) {
      cols.FirebaseConnectionProbes = [];
    }
  }

  function validateFirebaseConfigPayloadServer(cfg: {
    apiKey?: string;
    authDomain?: string;
    projectId?: string;
    storageBucket?: string;
    messagingSenderId?: string;
    appId?: string;
    firestoreDatabaseId?: string;
  }): {
    status: 'VALID' | 'MISSING' | 'INVALID';
    missingFields: string[];
    invalidFields: string[];
    instructionMessage: string;
  } {
    const required = ['apiKey', 'authDomain', 'projectId', 'storageBucket', 'messagingSenderId', 'appId'] as const;
    const missingFields: string[] = [];
    const invalidFields: string[] = [];

    for (const key of required) {
      const val = String(cfg?.[key] || '').trim();
      if (!val) {
        missingFields.push(key);
      } else if (
        val.includes('YOUR_') ||
        val.includes('PLACEHOLDER') ||
        val.includes('FAKE_') ||
        val === 'undefined' ||
        val === 'null'
      ) {
        invalidFields.push(`${key} (chứa giá trị giả lập/placeholder)`);
      }
    }

    if (missingFields.length > 0) {
      return {
        status: 'MISSING',
        missingFields,
        invalidFields,
        instructionMessage: `Thiếu trường cấu hình Firebase bắt buộc: ${missingFields.join(', ')}. Vui lòng cấu hình trong biến môi trường VITE_FIREBASE_* hoặc tệp firebase-applet-config.json.`,
      };
    }

    const apiKey = String(cfg.apiKey || '').trim();
    if (!apiKey.startsWith('AIza') || apiKey.length < 30) {
      invalidFields.push('apiKey (không đúng định dạng khóa công khai Firebase Web SDK)');
    }
    const appId = String(cfg.appId || '').trim();
    if (!appId.includes(':web:')) {
      invalidFields.push('appId (không đúng định dạng App ID của Firebase Web)');
    }

    if (invalidFields.length > 0) {
      return {
        status: 'INVALID',
        missingFields,
        invalidFields,
        instructionMessage: `Cấu hình Firebase không hợp lệ tại: ${invalidFields.join('; ')}. Tuyệt đối không dùng thông tin Firebase giả lập.`,
      };
    }

    return {
      status: 'VALID',
      missingFields: [],
      invalidFields: [],
      instructionMessage: 'Cấu hình Firebase Web SDK hợp lệ và đã xác thực với dự án thực.',
    };
  }

