  function getStage17CompositeIndexesCatalog() {
    let indexesFromFile: any[] = [];
    try {
      const idxPath = path.join(process.cwd(), 'firestore.indexes.json');
      if (fs.existsSync(idxPath)) {
        const parsed = JSON.parse(fs.readFileSync(idxPath, 'utf-8'));
        if (Array.isArray(parsed.indexes)) {
          indexesFromFile = parsed.indexes;
        }
      }
    } catch {
      // ignore
    }
    return indexesFromFile;
  }

