  function ensureDalFirestoreCollectionsStore(schoolId: string) {
    ensureStage17CentralStore();
    const cols = multiTenantDb.collections as Record<string, any>;
    if (!cols.DalSchoolFirestoreCollections || typeof cols.DalSchoolFirestoreCollections !== 'object') {
      cols.DalSchoolFirestoreCollections = {};
    }
    if (!cols.DalSchoolFirestoreCollections[schoolId]) {
      cols.DalSchoolFirestoreCollections[schoolId] = {
        users: [],
        departments: [],
        teachingAssignments: [],
        permissions: [],
        curriculum: [],
        questions: [],
        questionVersions: [],
        matrices: [],
        specifications: [],
        exams: [],
        examVersions: [],
        examWorkflows: [],
        aiReviews: [],
        approvals: [],
        examResults: [],
        auditLogs: [],
        migrationBackups: [],
        migrationReports: [],
        updatedAt: new Date().toISOString(),
      };
    }
    return cols.DalSchoolFirestoreCollections[schoolId] as Record<string, any[]>;
  }

