  // GIAI ĐOẠN 17 (PHẦN 4): TÍCH HỢP FIREBASE STORAGE LƯU TRỮ TỆP TÀI LIỆU
  // 8 LOẠI TỆP + ĐƯỜNG DẪN CHUẨN schoolId/module/documentId/versionId/filename +
  // 12 TRƯỜNG METADATA FIRESTORE + BẢO VỆ ĐỀ MẬT + KIỂM THỬ 9 KỊCH BẢN STORAGE
  // ============================================================================

  const MAX_STORAGE_FILE_SIZE_BYTES = 15 * 1024 * 1024; // 15 MB

  const ALLOWED_STORAGE_EXTENSIONS_MAP: Record<string, string[]> = {
    WORD_DOCUMENT: ['.docx', '.doc'],
    PDF_DOCUMENT: ['.pdf'],
    EXCEL_SPREADSHEET: ['.xlsx', '.xls', '.csv'],
    QUESTION_IMAGE: ['.png', '.jpg', '.jpeg', '.svg', '.webp'],
    CORPUS_MATERIAL: ['.docx', '.pdf', '.txt', '.png', '.jpg'],
    EXAM_DOSSIER_PACKAGE: ['.zip', '.pdf', '.docx'],
    APPRAISAL_REPORT: ['.pdf', '.docx'],
    RESULT_ANALYSIS_REPORT: ['.xlsx', '.pdf', '.csv'],
  };

  function validateStoragePathServer(params: {
    schoolId: string;
    module: string;
    documentId: string;
    versionId: string;
    originalFilename: string;
  }): {
    valid: boolean;
    storagePath: string;
    sanitizedFilename: string;
    errorReason?: string;
  } {
    const safeSegmentRegex = /^[a-zA-Z0-9_-]{1,128}$/;
    const segments = [
      { key: 'schoolId', val: String(params.schoolId || '').trim() },
      { key: 'module', val: String(params.module || '').trim() },
      { key: 'documentId', val: String(params.documentId || '').trim() },
      { key: 'versionId', val: String(params.versionId || '').trim() },
    ];

    for (const seg of segments) {
      if (!seg.val) {
        return {
          valid: false,
          storagePath: '',
          sanitizedFilename: '',
          errorReason: `Thiếu định danh bắt buộc [${seg.key}] trong đường dẫn Firebase Storage.`,
        };
      }
      if (seg.val.includes('@')) {
        return {
          valid: false,
          storagePath: '',
          sanitizedFilename: '',
          errorReason: `Vi phạm quy tắc cấu trúc đường dẫn (Mục II): Không được dùng email [${seg.val}] làm định danh [${seg.key}].`,
        };
      }
      if (!safeSegmentRegex.test(seg.val)) {
        return {
          valid: false,
          storagePath: '',
          sanitizedFilename: '',
          errorReason: `Vi phạm quy tắc cấu trúc đường dẫn (Mục II): Định danh [${seg.key} = "${seg.val}"] không được dùng họ tên có khoảng trắng hoặc ký tự đặc biệt.`,
        };
      }
    }

    const sanitizedFilename = String(params.originalFilename || '')
      .trim()
      .replace(/\.\./g, '')
      .replace(/[/\\]/g, '_')
      .replace(/\s+/g, '_')
      .replace(/[^a-zA-Z0-9._-]/g, '');

    if (!sanitizedFilename || sanitizedFilename.length < 3) {
      return {
        valid: false,
        storagePath: '',
        sanitizedFilename: '',
        errorReason: 'Tên tệp (filename) không hợp lệ.',
      };
    }

    return {
      valid: true,
      storagePath: `${segments[0].val}/${segments[1].val}/${segments[2].val}/${segments[3].val}/${sanitizedFilename}`,
      sanitizedFilename,
    };
  }

