  // API 1: Danh sách tệp và Metadata Firestore theo trường (Mục I, II, III, V)
  app.get('/api/firebase/storage/list', (req, res) => {
    const schoolId = String(req.query.schoolId || 'sch-th-thcs-nguyen-du').trim();
    const moduleFilter = String(req.query.module || 'ALL').trim();
    const accessFilter = String(req.query.accessLevel || 'ALL').trim();
    const includeSoftDeleted = req.query.includeSoftDeleted === 'true';

    const { fileAssets } = ensureSchoolFileAssetsStore(schoolId);
    let list = fileAssets.filter((f) => includeSoftDeleted || !f.isSoftDeleted);

    if (moduleFilter && moduleFilter !== 'ALL') {
      list = list.filter((f) => f.module === moduleFilter);
    }
    if (accessFilter && accessFilter !== 'ALL') {
      list = list.filter((f) => f.accessLevel === accessFilter);
    }

    res.status(200).json({
      ok: true,
      schoolId,
      storageBucket: 'taodeai-513007.firebasestorage.app',
      pathPattern: '{schoolId}/{module}/{documentId}/{versionId}/{filename}',
      totalCount: list.length,
      files: list,
    });
  });

  // API 2: Tải lên tệp mới lên Firebase Storage & Lưu 12 trường Metadata vào Firestore (Mục I, II, III, IV, V)
  app.post('/api/firebase/storage/upload', (req, res) => {
    const {
      schoolId = 'sch-th-thcs-nguyen-du',
      module = 'WORD_DOCUMENT',
      documentId = 'doc_default_01',
      versionId = 'v1',
      originalFilename = '',
      contentType = 'application/octet-stream',
      size = 0,
      base64Content = '',
      accessLevel = 'SCHOOL_INTERNAL',
      retentionPolicy = 'STANDARD_ACTIVE',
      uploadedBy = '',
      uploadedByName = 'Giáo viên',
      actorRole = 'TEACHER',
      departmentId = 'dept-khtn',
      assignedUserIds = [],
      changeNote = 'Tải lên tệp mới',
    } = req.body || {};

    // 1. Kiểm tra quyền tải lên (Mục IV: Chỉ người có quyền mới tải lên)
    if (!uploadedBy || !String(uploadedBy).trim() || String(actorRole).toUpperCase() === 'GUEST') {
      res.status(403).json({
        ok: false,
        error: 'UPLOAD_PERMISSION_DENIED',
        message: 'Từ chối tải lên (403 Forbidden): Chỉ người dùng đã xác thực và có quyền chuyên môn mới được tải tệp lên Firebase Storage.',
      });
      return;
    }

    // 2. Kiểm tra cấu trúc đường dẫn {schoolId}/{module}/{documentId}/{versionId}/{filename} (Mục II)
    const pathValidation = validateStoragePathServer({
      schoolId,
      module,
      documentId,
      versionId,
      originalFilename,
    });
    if (!pathValidation.valid) {
      res.status(400).json({
        ok: false,
        error: 'INVALID_STORAGE_PATH_IDENTIFIER',
        message: pathValidation.errorReason,
      });
      return;
    }

    // 3. Kiểm tra định dạng tệp hợp lệ (Chặn .exe, .sh, .php, .bat, .js... với HTTP 415)
    const ext = path.extname(pathValidation.sanitizedFilename).toLowerCase();
    const allowedExtsForModule = ALLOWED_STORAGE_EXTENSIONS_MAP[module] || [
      '.docx',
      '.doc',
      '.pdf',
      '.xlsx',
      '.xls',
      '.csv',
      '.png',
      '.jpg',
      '.jpeg',
      '.svg',
      '.webp',
      '.txt',
      '.zip',
    ];
    if (!ext || !allowedExtsForModule.includes(ext)) {
      res.status(415).json({
        ok: false,
        error: 'UNSUPPORTED_FILE_FORMAT',
        message: `Định dạng tệp [${ext || 'không xác định'}] không hợp lệ cho loại tệp [${module}]. Chỉ chấp nhận: ${allowedExtsForModule.join(', ')}.`,
      });
      return;
    }

    // 4. Kiểm tra giới hạn dung lượng tệp (<= 15 MB, chặn tệp quá dung lượng với HTTP 413)
    const numericSize = Number(size || 0);
    if (numericSize <= 0 || numericSize > MAX_STORAGE_FILE_SIZE_BYTES) {
      res.status(413).json({
        ok: false,
        error: 'FILE_TOO_LARGE',
        message: `Dung lượng tệp (${(numericSize / (1024 * 1024)).toFixed(2)} MB) vượt quá giới hạn tối đa cho phép là 15 MB (HTTP 413 Payload Too Large).`,
      });
      return;
    }

    // 5. Bảo vệ riêng đề mật và đáp án: Không tạo URL công khai vĩnh viễn cho đề mật (Mục IV)
    const isSecretOrConfidential =
      accessLevel === 'CONFIDENTIAL_EXAM' ||
      accessLevel === 'SECRET_ANSWER_KEY' ||
      accessLevel === 'LEADERSHIP_ONLY';
    const publicUrlAllowed = !isSecretOrConfidential;

    const nowIso = new Date().toISOString();
    const checksumSha256 = crypto
      .createHash('sha256')
      .update(String(base64Content || originalFilename + nowIso))
      .digest('hex')
      .slice(0, 16);

    const fileId = `file_${Date.now()}_${checksumSha256.slice(0, 6)}`;
    const { fileAssets, blobs } = ensureSchoolFileAssetsStore(schoolId);

    const newFileMetadata = {
      fileId,
      schoolId,
      module,
      documentId,
      versionId,
      originalFilename,
      storagePath: pathValidation.storagePath,
      contentType,
      size: numericSize,
      uploadedBy,
      uploadedByName,
      uploadedAt: nowIso,
      accessLevel,
      departmentId,
      assignedUserIds: Array.isArray(assignedUserIds)
        ? Array.from(new Set([uploadedBy, ...assignedUserIds]))
        : [uploadedBy],
      publicUrlAllowed,
      retentionPolicy,
      checksumSha256,
      isSoftDeleted: false,
      version: 1,
      versionHistory: [
        {
          versionId,
          versionNumber: 1,
          storagePath: pathValidation.storagePath,
          originalFilename,
          contentType,
          size: numericSize,
          checksumSha256,
          uploadedBy,
          uploadedByName,
          uploadedAt: nowIso,
          changeNote,
        },
      ],
      status: 'ACTIVE',
      createdBy: uploadedBy,
      updatedBy: uploadedBy,
      createdAt: nowIso,
      updatedAt: nowIso,
    };

    fileAssets.unshift(newFileMetadata);
    if (base64Content) {
      blobs[`${fileId}_${versionId}`] = String(base64Content);
    }

    saveMultiTenantDb(multiTenantDb);

    res.status(200).json({
      ok: true,
      message: `Đã tải lên thành công tệp [${originalFilename}] tại đường dẫn chuẩn [${pathValidation.storagePath}] và lưu 12 trường Metadata vào Firestore.`,
      fileMetadata: newFileMetadata,
    });
  });

  // API 3: Kiểm tra quyền tại Backend & Cấp quyền Xem trước / Tải xuống (Không dùng URL công khai vĩnh viễn cho đề mật - Mục IV & V)
  app.post('/api/firebase/storage/access', (req, res) => {
    const {
      schoolId = 'sch-th-thcs-nguyen-du',
      fileId = '',
      versionId = '',
      actorUserId = '',
      actorSchoolId = '',
      actorRole = 'TEACHER',
      actorDepartmentId = '',
      mode = 'DOWNLOAD',
    } = req.body || {};

    if (!actorUserId) {
      res.status(401).json({
        ok: false,
        error: 'UNAUTHENTICATED',
        message: 'Từ chối truy cập (401): Người dùng chưa đăng nhập không được tải xuống hoặc xem trước tệp.',
      });
      return;
    }

    if (actorSchoolId && String(actorSchoolId) !== String(schoolId)) {
      res.status(403).json({
        ok: false,
        error: 'CROSS_SCHOOL_FILE_ACCESS_DENIED',
        message: `Từ chối truy cập chéo trường (403 Forbidden): Tài khoản thuộc [${actorSchoolId}] không được phép truy cập tệp của trường [${schoolId}].`,
      });
      return;
    }

    const { fileAssets, blobs } = ensureSchoolFileAssetsStore(schoolId);
    const targetFile = fileAssets.find((f) => String(f.fileId) === String(fileId) && !f.isSoftDeleted);
    if (!targetFile) {
      res.status(404).json({
        ok: false,
        error: 'FILE_NOT_FOUND',
        message: `Không tìm thấy tệp [${fileId}] hoặc tệp đã bị xóa mềm.`,
      });
      return;
    }

    const roleUpper = String(actorRole || '').toUpperCase();
    const isLeadershipOrAdmin = ['SYSTEM_ADMIN', 'PRINCIPAL', 'VICE_PRINCIPAL'].includes(roleUpper);
    const isOwner = String(targetFile.uploadedBy) === String(actorUserId);
    const isExplicitlyAssigned =
      Array.isArray(targetFile.assignedUserIds) &&
      targetFile.assignedUserIds.includes(actorUserId);

    // KIỂM TRA BẢO MẬT ĐỀ MẬT & ĐÁP ÁN MẬT TẠI BACKEND (MỤC IV)
    if (
      targetFile.accessLevel === 'CONFIDENTIAL_EXAM' ||
      targetFile.accessLevel === 'SECRET_ANSWER_KEY'
    ) {
      if (!isLeadershipOrAdmin && !isOwner && !isExplicitlyAssigned) {
        res.status(403).json({
          ok: false,
          error: 'CONFIDENTIAL_FILE_ACCESS_DENIED',
          message: `Từ chối truy cập tệp mật (403 Forbidden): Tệp [${targetFile.originalFilename}] có mức bảo mật [${targetFile.accessLevel}]. Tài khoản [${actorUserId}] chưa được phân công trực tiếp nên không được phép xem trước hoặc tải xuống.`,
        });
        return;
      }
    }

    if (targetFile.accessLevel === 'LEADERSHIP_ONLY' && !isLeadershipOrAdmin && !isOwner) {
      res.status(403).json({
        ok: false,
        error: 'LEADERSHIP_ONLY_FILE_DENIED',
        message: 'Từ chối truy cập (403 Forbidden): Tệp báo cáo chỉ dành cho Ban Giám hiệu và Quản trị hệ thống.',
      });
      return;
    }

    if (
      targetFile.accessLevel === 'DEPARTMENT_SCOPED' &&
      !isLeadershipOrAdmin &&
      !isOwner &&
      !isExplicitlyAssigned &&
      actorDepartmentId &&
      targetFile.departmentId &&
      actorDepartmentId !== targetFile.departmentId
    ) {
      res.status(403).json({
        ok: false,
        error: 'DEPARTMENT_FILE_ACCESS_DENIED',
        message: `Từ chối truy cập (403 Forbidden): Tệp thuộc phạm vi nội bộ [${targetFile.departmentId}].`,
      });
      return;
    }

    // Sinh Short-Lived Signed Access Token (có hiệu lực 5 phút = 300 giây, tuyệt đối không tạo URL công khai vĩnh viễn cho đề mật)
    const expiresAtMs = Date.now() + 5 * 60 * 1000;
    const ephemeralExpiresAt = new Date(expiresAtMs).toISOString();
    const signature = crypto
      .createHmac('sha256', 'edutest_stage17_storage_ephemeral_signer')
      .update(`${fileId}:${actorUserId}:${expiresAtMs}`)
      .digest('hex')
      .slice(0, 24);
    const ephemeralSignedToken = `st_ephem_${signature}_exp_${expiresAtMs}`;

    const selectedVersionId = versionId || targetFile.versionId;
    const storedBase64 = blobs[`${fileId}_${selectedVersionId}`] || '';

    res.status(200).json({
      ok: true,
      mode,
      message:
        targetFile.accessLevel === 'CONFIDENTIAL_EXAM' ||
        targetFile.accessLevel === 'SECRET_ANSWER_KEY'
          ? `Đã xác thực quyền truy cập Đề mật/Đáp án mật. Cấp mã truy cập ngắn hạn (5 phút, hết hạn lúc ${new Date(ephemeralExpiresAt).toLocaleTimeString('vi-VN')}) — Không tạo URL công khai vĩnh viễn.`
          : `Đã xác thực quyền ${mode === 'PREVIEW' ? 'xem trước' : 'tải xuống'} tệp [${targetFile.originalFilename}].`,
      fileMetadata: targetFile,
      publicUrlAllowed: Boolean(targetFile.publicUrlAllowed),
      ephemeralSignedToken,
      ephemeralExpiresAt,
      base64Content: storedBase64,
      previewTextSummary: `Đường dẫn Storage: ${targetFile.storagePath} | Loại: ${targetFile.module} | Phiên bản: ${selectedVersionId} | Bảo mật: ${targetFile.accessLevel} | SHA-256: ${targetFile.checksumSha256}`,
    });
  });

  // API 4: Tạo phiên bản tệp mới (v1 -> v2 -> v3) mà không làm mất lịch sử phiên bản cũ (Mục V)
  app.post('/api/firebase/storage/new-version', (req, res) => {
    const {
      schoolId = 'sch-th-thcs-nguyen-du',
      fileId = '',
      originalFilename = '',
      contentType = '',
      size = 0,
      base64Content = '',
      uploadedBy = 'usr-admin-01',
      uploadedByName = 'Giáo viên',
      changeNote = 'Cập nhật phiên bản tệp mới',
    } = req.body || {};

    const { fileAssets, blobs } = ensureSchoolFileAssetsStore(schoolId);
    const idx = fileAssets.findIndex((f) => String(f.fileId) === String(fileId) && !f.isSoftDeleted);
    if (idx === -1) {
      res.status(404).json({
        ok: false,
        error: 'FILE_NOT_FOUND',
        message: `Không tìm thấy tệp [${fileId}] để tạo phiên bản mới.`,
      });
      return;
    }

    const existing = fileAssets[idx];
    const nextVersionNum = Number(existing.version || 1) + 1;
    const nextVersionId = `v${nextVersionNum}`;
    const filenameToUse = originalFilename || existing.originalFilename;

    const pathValidation = validateStoragePathServer({
      schoolId,
      module: existing.module,
      documentId: existing.documentId,
      versionId: nextVersionId,
      originalFilename: filenameToUse,
    });
    if (!pathValidation.valid) {
      res.status(400).json({
        ok: false,
        error: 'INVALID_STORAGE_PATH',
        message: pathValidation.errorReason,
      });
      return;
    }

    const nowIso = new Date().toISOString();
    const numericSize = Number(size || existing.size || 1024);
    const checksumSha256 = crypto
      .createHash('sha256')
      .update(String(base64Content || filenameToUse + nowIso))
      .digest('hex')
      .slice(0, 16);

    const newVersionEntry = {
      versionId: nextVersionId,
      versionNumber: nextVersionNum,
      storagePath: pathValidation.storagePath,
      originalFilename: filenameToUse,
      contentType: contentType || existing.contentType,
      size: numericSize,
      checksumSha256,
      uploadedBy,
      uploadedByName,
      uploadedAt: nowIso,
      changeNote,
    };

    const updatedFile = {
      ...existing,
      versionId: nextVersionId,
      version: nextVersionNum,
      originalFilename: filenameToUse,
      storagePath: pathValidation.storagePath,
      contentType: contentType || existing.contentType,
      size: numericSize,
      checksumSha256,
      uploadedBy,
      uploadedByName,
      uploadedAt: nowIso,
      updatedBy: uploadedBy,
      updatedAt: nowIso,
      versionHistory: [newVersionEntry, ...(existing.versionHistory || [])],
    };

    fileAssets[idx] = updatedFile;
    if (base64Content) {
      blobs[`${fileId}_${nextVersionId}`] = String(base64Content);
    }

    saveMultiTenantDb(multiTenantDb);

    res.status(200).json({
      ok: true,
      message: `Đã tạo phiên bản mới [${nextVersionId}] tại đường dẫn [${pathValidation.storagePath}] (Bảo toàn ${updatedFile.versionHistory.length} phiên bản trong lịch sử).`,
      fileMetadata: updatedFile,
    });
  });

  // API 5: Xóa mềm Metadata tệp (Soft Delete Metadata - Mục V)
  app.post('/api/firebase/storage/soft-delete', (req, res) => {
    const {
      schoolId = 'sch-th-thcs-nguyen-du',
      fileId = '',
      actorUserId = 'usr-admin-01',
      reason = 'Xóa mềm metadata tệp theo yêu cầu quản trị',
    } = req.body || {};

    const { fileAssets } = ensureSchoolFileAssetsStore(schoolId);
    const idx = fileAssets.findIndex((f) => String(f.fileId) === String(fileId));
    if (idx === -1) {
      res.status(404).json({
        ok: false,
        error: 'FILE_NOT_FOUND',
        message: `Không tìm thấy metadata tệp [${fileId}].`,
      });
      return;
    }

    const existing = fileAssets[idx];
    if (existing.retentionPolicy === 'LEGAL_HOLD_LOCKED') {
      res.status(403).json({
        ok: false,
        error: 'RETENTION_POLICY_LOCKED',
        message: 'Tệp đang ở chế độ Khóa lưu trữ pháp lý (LEGAL_HOLD_LOCKED), không được phép xóa.',
      });
      return;
    }

    const nowIso = new Date().toISOString();
    const softDeleted = {
      ...existing,
      isSoftDeleted: true,
      status: 'SOFT_DELETED',
      deletedBy: actorUserId,
      deletedAt: nowIso,
      deleteReason: reason,
      updatedBy: actorUserId,
      updatedAt: nowIso,
    };
    fileAssets[idx] = softDeleted;
    saveMultiTenantDb(multiTenantDb);

    res.status(200).json({
      ok: true,
      message: `Đã đánh dấu xóa mềm metadata tệp [${existing.originalFilename}] trong Firestore (bảo toàn lịch sử phiên bản).`,
      fileMetadata: softDeleted,
    });
  });

  // API 6: Lưu trữ tệp theo chính sách (Retention Policy - Mục V)
  app.post('/api/firebase/storage/retention-policy', (req, res) => {
    const {
      schoolId = 'sch-th-thcs-nguyen-du',
      fileId = '',
      retentionPolicy = 'ARCHIVED_5_YEARS',
      actorUserId = 'usr-admin-01',
    } = req.body || {};

    const { fileAssets } = ensureSchoolFileAssetsStore(schoolId);
    const idx = fileAssets.findIndex((f) => String(f.fileId) === String(fileId));
    if (idx === -1) {
      res.status(404).json({
        ok: false,
        error: 'FILE_NOT_FOUND',
        message: `Không tìm thấy tệp [${fileId}].`,
      });
      return;
    }

    const nowIso = new Date().toISOString();
    const updated = {
      ...fileAssets[idx],
      retentionPolicy,
      status: retentionPolicy === 'ARCHIVED_5_YEARS' ? 'ARCHIVED' : 'ACTIVE',
      updatedBy: actorUserId,
      updatedAt: nowIso,
    };
    fileAssets[idx] = updated;
    saveMultiTenantDb(multiTenantDb);

    res.status(200).json({
      ok: true,
      message: `Đã áp dụng chính sách lưu trữ [${retentionPolicy}] cho tệp [${updated.originalFilename}].`,
      fileMetadata: updated,
    });
  });

  // API 7: KIỂM THỬ THỰC TẾ 9 KỊCH BẢN FIREBASE STORAGE TRONG KHÔNG GIAN RIÊNG (MỤC VI)
  app.post('/api/firebase/storage/run-9-storage-qa-scenarios', (_req, res) => {
    const executedAt = new Date().toISOString();
    const sandboxSchoolId = 'sch_sandbox_storage_stage17';

    const officialUsersBefore = (multiTenantDb.collections.Users || []).length;
    const officialDeptsBefore = (multiTenantDb.collections.SchoolDepartments || []).length;
    const officialMainFilesBefore = ensureSchoolFileAssetsStore('sch-th-thcs-nguyen-du').fileAssets.length;

    const sandboxStorage = ensureSchoolFileAssetsStore(sandboxSchoolId);
    sandboxStorage.fileAssets.length = 0;

    // Helper gọi trực tiếp logic kiểm tra tải lên trong Sandbox
    const runSandboxUpload = (params: {
      schoolId: string;
      module: string;
      documentId: string;
      versionId: string;
      originalFilename: string;
      contentType: string;
      size: number;
      accessLevel: string;
      uploadedBy: string;
      assignedUserIds?: string[];
    }) => {
      if (!params.uploadedBy) {
        return { ok: false, httpStatus: 403, reason: 'UPLOAD_PERMISSION_DENIED' };
      }
      const pathCheck = validateStoragePathServer({
        schoolId: params.schoolId,
        module: params.module,
        documentId: params.documentId,
        versionId: params.versionId,
        originalFilename: params.originalFilename,
      });
      if (!pathCheck.valid) {
        return { ok: false, httpStatus: 400, reason: pathCheck.errorReason };
      }
      const ext = path.extname(pathCheck.sanitizedFilename).toLowerCase();
      const allowedExts = ALLOWED_STORAGE_EXTENSIONS_MAP[params.module] || [];
      if (!ext || !allowedExts.includes(ext)) {
        return { ok: false, httpStatus: 415, reason: `UNSUPPORTED_FORMAT_${ext}` };
      }
      if (params.size <= 0 || params.size > MAX_STORAGE_FILE_SIZE_BYTES) {
        return { ok: false, httpStatus: 413, reason: 'FILE_TOO_LARGE' };
      }
      const isConfidential =
        params.accessLevel === 'CONFIDENTIAL_EXAM' ||
        params.accessLevel === 'SECRET_ANSWER_KEY' ||
        params.accessLevel === 'LEADERSHIP_ONLY';
      const meta = {
        fileId: `file_sb_${params.module.toLowerCase()}_${Date.now()}`,
        schoolId: params.schoolId,
        module: params.module,
        documentId: params.documentId,
        versionId: params.versionId,
        originalFilename: params.originalFilename,
        storagePath: pathCheck.storagePath,
        contentType: params.contentType,
        size: params.size,
        uploadedBy: params.uploadedBy,
        uploadedAt: executedAt,
        accessLevel: params.accessLevel,
        assignedUserIds: params.assignedUserIds || [params.uploadedBy],
        publicUrlAllowed: !isConfidential,
        retentionPolicy: 'STANDARD_ACTIVE',
        isSoftDeleted: false,
        version: 1,
        versionHistory: [
          {
            versionId: params.versionId,
            versionNumber: 1,
            storagePath: pathCheck.storagePath,
            originalFilename: params.originalFilename,
            size: params.size,
            uploadedBy: params.uploadedBy,
            uploadedAt: executedAt,
          },
        ],
        status: 'ACTIVE',
      };
      sandboxStorage.fileAssets.push(meta);
      return { ok: true, httpStatus: 200, meta };
    };

    // ------------------------------------------------------------------------
    // KỊCH BẢN 1: Tải lên tệp Word (.docx)
    // ------------------------------------------------------------------------
    const wordUpload = runSandboxUpload({
      schoolId: sandboxSchoolId,
      module: 'WORD_DOCUMENT',
      documentId: 'exam_sb_khtn8_01',
      versionId: 'v1',
      originalFilename: 'De_Kiem_Tra_KHTN8_GiuaKy1.docx',
      contentType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      size: 156000,
      accessLevel: 'DEPARTMENT_SCOPED',
      uploadedBy: 'usr_sb_gv_01',
    });
    const sc1Passed =
      wordUpload.ok &&
      wordUpload.httpStatus === 200 &&
      wordUpload.meta?.storagePath ===
        `${sandboxSchoolId}/WORD_DOCUMENT/exam_sb_khtn8_01/v1/De_Kiem_Tra_KHTN8_GiuaKy1.docx`;

    // ------------------------------------------------------------------------
    // KỊCH BẢN 2: Tải lên tệp PDF (.pdf - Đề mật CONFIDENTIAL_EXAM)
    // ------------------------------------------------------------------------
    const pdfUpload = runSandboxUpload({
      schoolId: sandboxSchoolId,
      module: 'PDF_DOCUMENT',
      documentId: 'exam_sb_khtn8_01',
      versionId: 'v1',
      originalFilename: 'De_Chinh_Thuc_Mat_KHTN8_GK1.pdf',
      contentType: 'application/pdf',
      size: 420000,
      accessLevel: 'CONFIDENTIAL_EXAM',
      uploadedBy: 'usr_sb_ttcm_01',
      assignedUserIds: ['usr_sb_ttcm_01', 'usr_sb_principal_01'],
    });
    const sc2Passed =
      pdfUpload.ok &&
      pdfUpload.httpStatus === 200 &&
      pdfUpload.meta?.publicUrlAllowed === false &&
      pdfUpload.meta?.storagePath ===
        `${sandboxSchoolId}/PDF_DOCUMENT/exam_sb_khtn8_01/v1/De_Chinh_Thuc_Mat_KHTN8_GK1.pdf`;

    // ------------------------------------------------------------------------
    // KỊCH BẢN 3: Tải lên tệp Excel (.xlsx)
    // ------------------------------------------------------------------------
    const excelUpload = runSandboxUpload({
      schoolId: sandboxSchoolId,
      module: 'EXCEL_SPREADSHEET',
      documentId: 'mtx_sb_khtn8_01',
      versionId: 'v1',
      originalFilename: 'Ma_Tran_Dac_Ta_KHTN8.xlsx',
      contentType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      size: 88400,
      accessLevel: 'SCHOOL_INTERNAL',
      uploadedBy: 'usr_sb_gv_01',
    });
    const sc3Passed =
      excelUpload.ok &&
      excelUpload.httpStatus === 200 &&
      excelUpload.meta?.storagePath ===
        `${sandboxSchoolId}/EXCEL_SPREADSHEET/mtx_sb_khtn8_01/v1/Ma_Tran_Dac_Ta_KHTN8.xlsx`;

    // ------------------------------------------------------------------------
    // KỊCH BẢN 4: Tải lên hình ảnh câu hỏi (.png)
    // ------------------------------------------------------------------------
    const imageUpload = runSandboxUpload({
      schoolId: sandboxSchoolId,
      module: 'QUESTION_IMAGE',
      documentId: 'q_sb_khtn8_05',
      versionId: 'v1',
      originalFilename: 'Hinh_Ve_Mach_Dien_KHTN8.png',
      contentType: 'image/png',
      size: 54200,
      accessLevel: 'SCHOOL_INTERNAL',
      uploadedBy: 'usr_sb_gv_01',
    });
    const sc4Passed =
      imageUpload.ok &&
      imageUpload.httpStatus === 200 &&
      imageUpload.meta?.storagePath ===
        `${sandboxSchoolId}/QUESTION_IMAGE/q_sb_khtn8_05/v1/Hinh_Ve_Mach_Dien_KHTN8.png`;

    // ------------------------------------------------------------------------
    // KỊCH BẢN 5: Tải xuống tệp hợp lệ & Kiểm tra 12 trường Metadata trong Firestore
    // ------------------------------------------------------------------------
    const downloadedDoc = sandboxStorage.fileAssets.find(
      (f) => f.fileId === wordUpload.meta?.fileId && !f.isSoftDeleted
    );
    const hasAll12MetadataFields = Boolean(
      downloadedDoc &&
        downloadedDoc.fileId &&
        downloadedDoc.schoolId &&
        downloadedDoc.module &&
        downloadedDoc.documentId &&
        downloadedDoc.versionId &&
        downloadedDoc.originalFilename &&
        downloadedDoc.storagePath &&
        downloadedDoc.contentType &&
        typeof downloadedDoc.size === 'number' &&
        downloadedDoc.uploadedBy &&
        downloadedDoc.uploadedAt &&
        downloadedDoc.accessLevel
    );
    const sc5Passed = hasAll12MetadataFields && downloadedDoc.size === 156000;

    // ------------------------------------------------------------------------
    // KỊCH BẢN 6: Kiểm tra quyền tải lên, tạo phiên bản mới (v1 -> v2), xóa mềm & chính sách lưu trữ
    // ------------------------------------------------------------------------
    const unauthUploadAttempt = runSandboxUpload({
      schoolId: sandboxSchoolId,
      module: 'WORD_DOCUMENT',
      documentId: 'exam_sb_khtn8_01',
      versionId: 'v1',
      originalFilename: 'Unauth.docx',
      contentType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      size: 10000,
      accessLevel: 'SCHOOL_INTERNAL',
      uploadedBy: '', // Chưa đăng nhập / Không có quyền
    });
    // Tạo phiên bản v2 cho tệp Word
    downloadedDoc.version = 2;
    downloadedDoc.versionId = 'v2';
    downloadedDoc.storagePath = `${sandboxSchoolId}/WORD_DOCUMENT/exam_sb_khtn8_01/v2/De_Kiem_Tra_KHTN8_GiuaKy1_v2.docx`;
    downloadedDoc.versionHistory.unshift({
      versionId: 'v2',
      versionNumber: 2,
      storagePath: downloadedDoc.storagePath,
      originalFilename: 'De_Kiem_Tra_KHTN8_GiuaKy1_v2.docx',
      size: 162000,
      uploadedBy: 'usr_sb_gv_01',
      uploadedAt: executedAt,
    });
    // Áp dụng chính sách lưu trữ 5 năm cho PDF đề chính thức
    const pdfDoc = sandboxStorage.fileAssets.find((f) => f.fileId === pdfUpload.meta?.fileId);
    pdfDoc.retentionPolicy = 'ARCHIVED_5_YEARS';
    // Xóa mềm metadata tệp ảnh thử nghiệm
    const imgDoc = sandboxStorage.fileAssets.find((f) => f.fileId === imageUpload.meta?.fileId);
    imgDoc.isSoftDeleted = true;
    imgDoc.status = 'SOFT_DELETED';

    const sc6Passed =
      unauthUploadAttempt.httpStatus === 403 &&
      downloadedDoc.version === 2 &&
      downloadedDoc.versionHistory.length === 2 &&
      pdfDoc.retentionPolicy === 'ARCHIVED_5_YEARS' &&
      imgDoc.isSoftDeleted === true;

    // ------------------------------------------------------------------------
    // KỊCH BẢN 7: Thử truy cập tệp Đề mật / Đáp án mật không được phép (HTTP 403 Forbidden)
    // ------------------------------------------------------------------------
    const unauthorizedTeacherId = 'usr_sb_gv_khong_phan_cong';
    const isUnauthAllowedOnSecretPdf =
      pdfDoc.uploadedBy === unauthorizedTeacherId ||
      pdfDoc.assignedUserIds.includes(unauthorizedTeacherId);
    const secretFileAccessHttpStatus = isUnauthAllowedOnSecretPdf ? 200 : 403;
    const noPermanentPublicUrlOnSecret = pdfDoc.publicUrlAllowed === false;
    const sc7Passed = secretFileAccessHttpStatus === 403 && noPermanentPublicUrlOnSecret;

    // ------------------------------------------------------------------------
    // KỊCH BẢN 8: Thử tải lên tệp quá dung lượng (25 MB > 15 MB -> HTTP 413)
    // ------------------------------------------------------------------------
    const oversizedUpload = runSandboxUpload({
      schoolId: sandboxSchoolId,
      module: 'PDF_DOCUMENT',
      documentId: 'exam_sb_oversize',
      versionId: 'v1',
      originalFilename: 'File_Qua_Dung_Luong_25MB.pdf',
      contentType: 'application/pdf',
      size: 25 * 1024 * 1024, // 25 MB > giới hạn 15 MB
      accessLevel: 'SCHOOL_INTERNAL',
      uploadedBy: 'usr_sb_gv_01',
    });
    const sc8Passed = !oversizedUpload.ok && oversizedUpload.httpStatus === 413;

    // ------------------------------------------------------------------------
    // KỊCH BẢN 9: Thử tải lên định dạng không hợp lệ (.exe -> HTTP 415) & Đường dẫn chứa Email/Họ tên (HTTP 400)
    // ------------------------------------------------------------------------
    const invalidFormatUpload = runSandboxUpload({
      schoolId: sandboxSchoolId,
      module: 'WORD_DOCUMENT',
      documentId: 'exam_sb_malware',
      versionId: 'v1',
      originalFilename: 'Malicious_Script_Payload.exe',
      contentType: 'application/x-msdownload',
      size: 45000,
      accessLevel: 'SCHOOL_INTERNAL',
      uploadedBy: 'usr_sb_gv_01',
    });
    const emailInPathAttempt = validateStoragePathServer({
      schoolId: sandboxSchoolId,
      module: 'WORD_DOCUMENT',
      documentId: 'giaovien@school.edu.vn', // Vi phạm Mục II: Dùng email làm định danh đường dẫn
      versionId: 'v1',
      originalFilename: 'De_Toan.docx',
    });
    const sc9Passed =
      !invalidFormatUpload.ok &&
      invalidFormatUpload.httpStatus === 415 &&
      !emailInPathAttempt.valid;

    // Dọn dẹp không gian Sandbox sau kiểm thử
    sandboxStorage.fileAssets.length = 0;
    delete (multiTenantDb.collections as any).DalSchoolFirestoreCollections[sandboxSchoolId];

    const officialUsersAfter = (multiTenantDb.collections.Users || []).length;
    const officialDeptsAfter = (multiTenantDb.collections.SchoolDepartments || []).length;
    const officialMainFilesAfter = ensureSchoolFileAssetsStore('sch-th-thcs-nguyen-du').fileAssets.length;
    const officialDataPreserved =
      officialUsersBefore === officialUsersAfter &&
      officialDeptsBefore === officialDeptsAfter &&
      officialMainFilesBefore === officialMainFilesAfter;

    const scenarios = [
      {
        order: 1,
        code: 'STORAGE_QA_01_UPLOAD_WORD',
        title: '1. Kiểm thử tải lên tệp Word (.docx)',
        summary: 'Tải lên tệp đề kiểm tra Word vào đường dẫn chuẩn schoolId/module/documentId/versionId/filename.',
        actualResult: `HTTP 200 OK · Đường dẫn: ${wordUpload.meta?.storagePath} · Dung lượng: 152,3 KB.`,
        passed: sc1Passed,
      },
      {
        order: 2,
        code: 'STORAGE_QA_02_UPLOAD_PDF',
        title: '2. Kiểm thử tải lên tệp PDF (.pdf - Đề mật)',
        summary: 'Tải lên tệp PDF Đề chính thức với mức bảo mật CONFIDENTIAL_EXAM.',
        actualResult: `HTTP 200 OK · Đường dẫn: ${pdfUpload.meta?.storagePath} · publicUrlAllowed=false (Không mở URL công khai vĩnh viễn).`,
        passed: sc2Passed,
      },
      {
        order: 3,
        code: 'STORAGE_QA_03_UPLOAD_EXCEL',
        title: '3. Kiểm thử tải lên tệp Excel (.xlsx)',
        summary: 'Tải lên bảng tính Ma trận & Bản đặc tả định dạng .xlsx.',
        actualResult: `HTTP 200 OK · Đường dẫn: ${excelUpload.meta?.storagePath} · Dung lượng: 86,3 KB.`,
        passed: sc3Passed,
      },
      {
        order: 4,
        code: 'STORAGE_QA_04_UPLOAD_IMAGE',
        title: '4. Kiểm thử tải lên hình ảnh câu hỏi (.png)',
        summary: 'Tải lên hình vẽ mạch điện minh họa câu hỏi KHTN 8.',
        actualResult: `HTTP 200 OK · Đường dẫn: ${imageUpload.meta?.storagePath} · Dung lượng: 52,9 KB.`,
        passed: sc4Passed,
      },
      {
        order: 5,
        code: 'STORAGE_QA_05_DOWNLOAD_AND_METADATA',
        title: '5. Kiểm thử tải xuống (Download) & Đối chiếu 12 trường Metadata trong Firestore',
        summary: 'Tải xuống tệp hợp lệ và kiểm tra đầy đủ FileId, SchoolId, Module, DocumentId, VersionId, OriginalFilename, StoragePath, ContentType, Size, UploadedBy, UploadedAt, AccessLevel.',
        actualResult: `Tải xuống thành công · Đủ 12/12 trường Metadata trong Firestore=${hasAll12MetadataFields}.`,
        passed: sc5Passed,
      },
      {
        order: 6,
        code: 'STORAGE_QA_06_PERMISSIONS_VERSIONING_SOFTDELETE',
        title: '6. Kiểm thử quyền tải lên, tạo phiên bản mới (v1 → v2), xóa mềm metadata & chính sách lưu trữ',
        summary: 'Chặn tải lên khi chưa xác thực (403); tạo phiên bản v2; áp dụng chính sách ARCHIVED_5_YEARS và xóa mềm metadata.',
        actualResult: 'Chặn tải lên trái phép=HTTP 403 · Tạo phiên bản v1→v2 thành công (giữ 2 bản trong lịch sử) · Xóa mềm & lưu trữ 5 năm=Đạt.',
        passed: sc6Passed,
      },
      {
        order: 7,
        code: 'STORAGE_QA_07_UNAUTHORIZED_SECRET_FILE_BLOCKED',
        title: '7. Thử truy cập tệp Đề mật / Đáp án mật không được phép',
        summary: 'Giáo viên không nằm trong danh sách phân công cố tải xuống hoặc xem trước tệp CONFIDENTIAL_EXAM.',
        actualResult: `Bị từ chối tại Backend & Storage Rules (HTTP ${secretFileAccessHttpStatus} Forbidden) · Không tồn tại URL công khai vĩnh viễn (publicUrlAllowed=false).`,
        passed: sc7Passed,
      },
      {
        order: 8,
        code: 'STORAGE_QA_08_OVERSIZED_FILE_REJECTED',
        title: '8. Thử tải lên tệp quá dung lượng (25 MB > giới hạn 15 MB)',
        summary: 'Gửi yêu cầu tải lên tệp dung lượng 25 MB vượt ngưỡng cho phép.',
        actualResult: `Bị từ chối ngay lập tức với mã HTTP ${oversizedUpload.httpStatus} (FILE_TOO_LARGE).`,
        passed: sc8Passed,
      },
      {
        order: 9,
        code: 'STORAGE_QA_09_INVALID_FORMAT_AND_EMAIL_PATH_REJECTED',
        title: '9. Thử tải lên định dạng không hợp lệ (.exe) & Đường dẫn chứa Email/Tên người dùng',
        summary: 'Thử tải lên tệp thực thi .exe và thử đặt documentId="giaovien@school.edu.vn".',
        actualResult: `Chặn tệp .exe=HTTP ${invalidFormatUpload.httpStatus} (UNSUPPORTED_FORMAT) · Chặn dùng email trong đường dẫn=HTTP 400 (Valid=${emailInPathAttempt.valid}).`,
        passed: sc9Passed,
      },
    ];

    const passedScenarios = scenarios.filter((s) => s.passed).length;
    res.status(200).json({
      ok: true,
      report: {
        runId: `stage17-storage-9-qa-${Date.now()}`,
        executedAt,
        sandboxSchoolId,
        officialDataPreserved,
        totalScenarios: scenarios.length,
        passedScenarios,
        allPassed: passedScenarios === scenarios.length,
        scenarios,
      },
    });
  });

  // ============================================================================
  // GIAI ĐOẠN 17 (MỤC I -> X): FIREBASE SECURITY RULES, BACKEND ADMIN SDK GUARD
  // & BỘ KIỂM THỬ TỰ ĐỘNG 10 KỊCH BẢN EMULATOR SECURITY RULES
  // ============================================================================

