  // ==========================================================================
  // GIAI ĐOẠN 17: ĐỒNG BỘ FIREBASE AUTHENTICATION VỚI FIRESTORE & PHÂN QUYỀN
  // (MỤC I -> VIII: 8 BƯỚC TẠO TÀI KHOẢN AN TOÀN, CHỈNH SỬA ĐỒNG BỘ, THU HỒI
  // QUYỀN TỨC THÌ, KHÓA TÀI KHOẢN THU HỒI TOKEN & KIỂM THỬ 3 TÀI KHOẢN)
  // ==========================================================================

  interface ServerAuthIdentity {
    uid: string;
    email: string;
    emailVerified: boolean;
    disabled: boolean;
    displayName: string;
    providerId: 'password' | 'google.com';
    lastSignInTime: string;
    tokensValidAfterTime: string;
    sessionRevocationEpoch: number;
    createdAt: string;
    updatedAt: string;
  }

  interface ServerFirestoreTeacherProfile {
    authUid: string;
    teacherProfileId: string;
    schoolId: string;
    fullName: string;
    email: string;
    departmentId: string;
    departmentName: string;
    educationLevels: ('TIEU_HOC' | 'THCS')[];
    subjects: string[];
    grades: string[];
    roles: ('TEACHER' | 'HEAD_OF_DEPARTMENT' | 'VICE_PRINCIPAL' | 'PRINCIPAL' | 'SYSTEM_ADMIN')[];
    status: 'ACTIVE' | 'PENDING_ACTIVATION' | 'LOCKED' | 'INCOMPLETE_PROVISIONING';
    functionalPermissions: string[];
    permissionScope: {
      schoolId: string;
      departmentId: string;
      educationLevels: ('TIEU_HOC' | 'THCS')[];
      allowedSubjects: string[];
      allowedGrades: string[];
      assignedClasses: string[];
      canReadConfidentialExam: boolean;
      canApproveFinalExam: boolean;
    };
    permissionVersion: number;
    securityStamp: string;
    passwordStoredInFirestore: false;
    createdAt: string;
    updatedAt: string;
    updatedBy: string;
  }

  const stage17AuthStore = new Map<string, ServerAuthIdentity>();
  const stage17EmailToUidIndex = new Map<string, string>();
  const stage17IdempotencyKeyToUid = new Map<string, string>();
  const stage17FirestoreUsersStore = new Map<string, ServerFirestoreTeacherProfile>();
  const stage17AssignmentsStore = new Map<string, Record<string, unknown>[]>();
  const stage17PermissionsStore = new Map<string, Record<string, unknown>>();
  const stage17AuditLogsStore: Record<string, unknown>[] = [];
  const stage17ActiveSessionsStore = new Map<
    string,
    {
      tokenId: string;
      uid: string;
      email: string;
      schoolId: string;
      deviceId: string;
      deviceLabel: string;
      issuedAt: string;
      expiresAt: string;
      tokenPermissionVersion: number;
    }[]
  >();

  function computeVisibleUiModules(
    roles: string[],
    permissions: string[],
    educationLevels: string[]
  ): string[] {
    const modules = ['DASHBOARD_CA_NHAN', 'CHUONG_TRINH_GDPT_2018'];
    if (permissions.includes('CREATE_QUESTION') || permissions.includes('EDIT_OWN_QUESTION')) {
      modules.push('NGAN_HANG_CAU_HOI', 'AI_TAO_CAU_HOI');
    }
    if (permissions.includes('BUILD_MATRIX') || permissions.includes('BUILD_SPECIFICATION')) {
      modules.push('MA_TRAN_VA_BAN_DAC_TA');
    }
    if (permissions.includes('CREATE_EXAM')) {
      modules.push('TAO_DE_KIEM_TRA', 'QUY_TRINH_9_BUOC');
    }
    if (roles.includes('HEAD_OF_DEPARTMENT') || permissions.includes('APPRAISE_DEPARTMENT_EXAM')) {
      modules.push('THAM_DINH_CAP_TO_CHUYEN_MON');
    }
    if (roles.includes('PRINCIPAL') || roles.includes('VICE_PRINCIPAL') || permissions.includes('APPROVE_FINAL_EXAM')) {
      modules.push('PHE_DUYET_BAN_GIAM_HIEU');
    }
    if (educationLevels.includes('TIEU_HOC')) {
      modules.push('KHUNG_DANH_GIA_TIEU_HOC_TT27');
    }
    if (educationLevels.includes('THCS')) {
      modules.push('KHUNG_DANH_GIA_THCS_TT22');
    }
    return modules;
  }

  function execute8StepTeacherProvisioning(params: {
    adminActorUid: string;
    adminActorRole: string;
    idempotencyKey: string;
    schoolId: string;
    teacherProfileId: string;
    fullName: string;
    email: string;
    departmentId: string;
    departmentName: string;
    educationLevels: ('TIEU_HOC' | 'THCS')[];
    subjects: string[];
    grades: string[];
    assignedClasses: string[];
    roles: ('TEACHER' | 'HEAD_OF_DEPARTMENT' | 'VICE_PRINCIPAL' | 'PRINCIPAL' | 'SYSTEM_ADMIN')[];
    functionalPermissions: string[];
    simulateFailAtStep?: number;
  }) {
    const nowIso = new Date().toISOString();
    const steps: {
      stepNumber: number;
      stepCode: string;
      stepTitle: string;
      status: 'COMPLETED' | 'FAILED' | 'COMPENSATED' | 'SKIPPED_IDEMPOTENT';
      detail: string;
      executedAt: string;
    }[] = [];

    const normalizedEmail = (params.email || '').trim().toLowerCase();

    // Bước 1: Kiểm tra dữ liệu đầu vào & đảm bảo không chứa mật khẩu lưu vào Firestore
    if (!params.fullName || !normalizedEmail || !normalizedEmail.includes('@') || !params.schoolId) {
      steps.push({
        stepNumber: 1,
        stepCode: 'STEP_1_VALIDATE_INPUT',
        stepTitle: '1. Kiểm tra tính hợp lệ dữ liệu & cấm lưu mật khẩu trong Firestore',
        status: 'FAILED',
        detail: 'Thiếu họ tên, email không hợp lệ hoặc thiếu mã trường schoolId.',
        executedAt: nowIso,
      });
      return {
        ok: false,
        idempotencyKey: params.idempotencyKey,
        reusedExistingOnRetry: false,
        provisioningStatus: 'ROLLED_BACK_SAFE' as const,
        authRecord: null,
        firestoreProfile: null,
        assignmentIds: [],
        permissionDocId: null,
        auditLogId: null,
        steps,
        message: 'Dữ liệu đầu vào không hợp lệ ở Bước 1.',
      };
    }

    steps.push({
      stepNumber: 1,
      stepCode: 'STEP_1_VALIDATE_INPUT',
      stepTitle: '1. Kiểm tra tính hợp lệ dữ liệu & cấm lưu mật khẩu trong Firestore',
      status: 'COMPLETED',
      detail: `Hợp lệ: ${params.fullName} (${normalizedEmail}), Cấp học: ${params.educationLevels.join(', ')}, Môn: ${params.subjects.join(', ')}, Khối: ${params.grades.join(', ')}. Xác nhận passwordStoredInFirestore = false.`,
      executedAt: nowIso,
    });

    // Bước 2: Kiểm tra quyền quản trị của người thực hiện
    if (params.adminActorRole !== 'SYSTEM_ADMIN' && params.adminActorRole !== 'PRINCIPAL') {
      steps.push({
        stepNumber: 2,
        stepCode: 'STEP_2_VERIFY_ADMIN_PRIVILEGE',
        stepTitle: '2. Kiểm tra quyền quản trị của người tạo tài khoản',
        status: 'FAILED',
        detail: `Từ chối: Vai trò ${params.adminActorRole} không có quyền tạo tài khoản giáo viên.`,
        executedAt: nowIso,
      });
      return {
        ok: false,
        idempotencyKey: params.idempotencyKey,
        reusedExistingOnRetry: false,
        provisioningStatus: 'ROLLED_BACK_SAFE' as const,
        authRecord: null,
        firestoreProfile: null,
        assignmentIds: [],
        permissionDocId: null,
        auditLogId: null,
        steps,
        message: 'Người thực hiện không có quyền quản trị (Bước 2).',
      };
    }

    steps.push({
      stepNumber: 2,
      stepCode: 'STEP_2_VERIFY_ADMIN_PRIVILEGE',
      stepTitle: '2. Kiểm tra quyền quản trị của người tạo tài khoản',
      status: 'COMPLETED',
      detail: `Xác nhận quyền quản trị hợp lệ (${params.adminActorUid} · ${params.adminActorRole}).`,
      executedAt: nowIso,
    });

    // Bước 3: Tạo tài khoản Firebase Authentication qua Backend (chống tạo trùng khi thử lại)
    const existingUidByIdempotency = stage17IdempotencyKeyToUid.get(params.idempotencyKey);
    const existingUidByEmail = stage17EmailToUidIndex.get(normalizedEmail);
    const reusedExistingOnRetry = Boolean(existingUidByIdempotency || existingUidByEmail);
    const uid =
      existingUidByIdempotency ||
      existingUidByEmail ||
      `uid_${params.teacherProfileId.toLowerCase().replace(/[^a-z0-9]/g, '_')}`;

    const authRecord: ServerAuthIdentity = stage17AuthStore.get(uid) || {
      uid,
      email: normalizedEmail,
      emailVerified: true,
      disabled: false,
      displayName: params.fullName,
      providerId: 'password',
      lastSignInTime: nowIso,
      tokensValidAfterTime: '2026-01-01T00:00:00.000Z',
      sessionRevocationEpoch: 1,
      createdAt: nowIso,
      updatedAt: nowIso,
    };
    authRecord.email = normalizedEmail;
    authRecord.displayName = params.fullName;
    authRecord.disabled = false;
    authRecord.updatedAt = nowIso;

    stage17AuthStore.set(uid, authRecord);
    stage17EmailToUidIndex.set(normalizedEmail, uid);
    stage17IdempotencyKeyToUid.set(params.idempotencyKey, uid);

    steps.push({
      stepNumber: 3,
      stepCode: 'STEP_3_CREATE_FIREBASE_AUTH_ACCOUNT',
      stepTitle: '3. Tạo tài khoản Firebase Authentication qua Backend (Idempotent)',
      status: reusedExistingOnRetry ? 'SKIPPED_IDEMPOTENT' : 'COMPLETED',
      detail: reusedExistingOnRetry
        ? `Thử lại an toàn: Tái sử dụng tài khoản Auth UID=${uid} (${normalizedEmail}), KHÔNG tạo tài khoản trùng.`
        : `Đã khởi tạo Firebase Auth UID=${uid} cho email ${normalizedEmail}.`,
      executedAt: nowIso,
    });

    // Bước 4: Tạo hồ sơ Firestore (Không lưu mật khẩu)
    const firestoreProfile: ServerFirestoreTeacherProfile = {
      authUid: uid,
      teacherProfileId: params.teacherProfileId,
      schoolId: params.schoolId,
      fullName: params.fullName,
      email: normalizedEmail,
      departmentId: params.departmentId,
      departmentName: params.departmentName,
      educationLevels: params.educationLevels,
      subjects: params.subjects,
      grades: params.grades,
      roles: params.roles,
      status: 'ACTIVE',
      functionalPermissions: params.functionalPermissions,
      permissionScope: {
        schoolId: params.schoolId,
        departmentId: params.departmentId,
        educationLevels: params.educationLevels,
        allowedSubjects: params.subjects,
        allowedGrades: params.grades,
        assignedClasses: params.assignedClasses,
        canReadConfidentialExam:
          params.roles.includes('PRINCIPAL') || params.roles.includes('HEAD_OF_DEPARTMENT'),
        canApproveFinalExam: params.roles.includes('PRINCIPAL'),
      },
      permissionVersion: 1,
      securityStamp: `sec_stamp_${uid}_v1`,
      passwordStoredInFirestore: false,
      createdAt: nowIso,
      updatedAt: nowIso,
      updatedBy: params.adminActorUid,
    };

    stage17FirestoreUsersStore.set(uid, firestoreProfile);

    steps.push({
      stepNumber: 4,
      stepCode: 'STEP_4_CREATE_FIRESTORE_PROFILE',
      stepTitle: '4. Tạo hồ sơ giáo viên trên Firestore (schools/{schoolId}/users/{uid})',
      status: 'COMPLETED',
      detail: `Đã lưu hồ sơ Firestore không chứa mật khẩu cho ${params.fullName} (Mã GV: ${params.teacherProfileId}).`,
      executedAt: nowIso,
    });

    // Bước 5: Liên kết chính xác bằng UID giữa Auth và Firestore
    steps.push({
      stepNumber: 5,
      stepCode: 'STEP_5_BIND_AUTH_UID_TO_FIRESTORE',
      stepTitle: '5. Liên kết định danh 1-1 bằng UID giữa Firebase Auth và Firestore',
      status: 'COMPLETED',
      detail: `Xác nhận authRecord.uid (${authRecord.uid}) === firestoreProfile.authUid (${firestoreProfile.authUid}).`,
      executedAt: nowIso,
    });

    // Kiểm tra nếu mô phỏng lỗi tại Bước 6 để kiểm chứng cơ chế hoàn tác / thử lại an toàn (Mục III)
    if (params.simulateFailAtStep === 6) {
      firestoreProfile.status = 'INCOMPLETE_PROVISIONING';
      stage17FirestoreUsersStore.set(uid, firestoreProfile);
      steps.push({
        stepNumber: 6,
        stepCode: 'STEP_6_ASSIGN_TEACHING_SCOPE',
        stepTitle: '6. Gán phân công giảng dạy (teachingAssignments)',
        status: 'FAILED',
        detail: 'Mô phỏng sự cố gián đoạn mạng khi ghi phân công giảng dạy ở Bước 6.',
        executedAt: nowIso,
      });
      steps.push({
        stepNumber: 7,
        stepCode: 'STEP_7_COMPENSATION_HANDLER',
        stepTitle: 'Xử lý trạng thái chưa hoàn tất (Compensation / Safe Retry Ready)',
        status: 'COMPENSATED',
        detail: `Đã đánh dấu hồ sơ UID=${uid} sang trạng thái INCOMPLETE_PROVISIONING và giữ khóa IdempotencyKey=${params.idempotencyKey} để thử lại an toàn không tạo trùng tài khoản.`,
        executedAt: nowIso,
      });
      return {
        ok: false,
        idempotencyKey: params.idempotencyKey,
        reusedExistingOnRetry,
        provisioningStatus: 'READY_FOR_SAFE_RETRY' as const,
        authRecord,
        firestoreProfile,
        assignmentIds: [],
        permissionDocId: null,
        auditLogId: null,
        steps,
        message:
          'Bước 6 gặp sự cố gián đoạn. Hệ thống đã chuyển hồ sơ sang trạng thái INCOMPLETE_PROVISIONING và sẵn sàng Thử lại an toàn (Idempotent Retry) mà không tạo trùng tài khoản Auth.',
      };
    }

    // Bước 6: Gán phân công giảng dạy
    const assignmentRecords = params.subjects.map((subj, idx) => ({
      assignmentId: `asg_${uid}_${idx + 1}`,
      schoolId: params.schoolId,
      teacherUid: uid,
      teacherProfileId: params.teacherProfileId,
      academicYear: '2026-2027',
      educationLevels: params.educationLevels,
      subject: subj,
      grades: params.grades,
      assignedClasses: params.assignedClasses,
      status: 'ACTIVE',
      createdAt: nowIso,
    }));
    stage17AssignmentsStore.set(uid, assignmentRecords);

    steps.push({
      stepNumber: 6,
      stepCode: 'STEP_6_ASSIGN_TEACHING_SCOPE',
      stepTitle: '6. Gán phân công giảng dạy (schools/{schoolId}/teachingAssignments)',
      status: 'COMPLETED',
      detail: `Đã tạo ${assignmentRecords.length} bản ghi phân công giảng dạy (Môn: ${params.subjects.join(', ')} · Khối: ${params.grades.join(', ')}).`,
      executedAt: nowIso,
    });

    // Bước 7: Gán quyền theo xác nhận
    const permissionDocId = `perm_${uid}`;
    stage17PermissionsStore.set(uid, {
      permissionId: permissionDocId,
      schoolId: params.schoolId,
      userId: uid,
      teacherProfileId: params.teacherProfileId,
      roles: params.roles,
      functionalPermissions: params.functionalPermissions,
      permissionScope: firestoreProfile.permissionScope,
      permissionVersion: firestoreProfile.permissionVersion,
      confirmedBy: params.adminActorUid,
      updatedAt: nowIso,
    });

    steps.push({
      stepNumber: 7,
      stepCode: 'STEP_7_GRANT_CONFIRMED_PERMISSIONS',
      stepTitle: '7. Gán quyền chức năng & phạm vi theo xác nhận (schools/{schoolId}/permissions)',
      status: 'COMPLETED',
      detail: `Đã cấp ${params.functionalPermissions.length} quyền chức năng (${params.functionalPermissions.join(', ')}) trong phạm vi Môn ${params.subjects.join(', ')} · Khối ${params.grades.join(', ')}.`,
      executedAt: nowIso,
    });

    // Bước 8: Ghi nhật ký bảo mật
    const auditLogId = `audit_prov_${uid}_${Date.now()}`;
    stage17AuditLogsStore.unshift({
      logId: auditLogId,
      schoolId: params.schoolId,
      actorUid: params.adminActorUid,
      action: 'PROVISION_TEACHER_8_STEPS',
      targetUid: uid,
      targetEmail: normalizedEmail,
      reusedExistingOnRetry,
      createdAt: nowIso,
    });

    steps.push({
      stepNumber: 8,
      stepCode: 'STEP_8_WRITE_SECURITY_AUDIT_LOG',
      stepTitle: '8. Ghi nhật ký bảo mật bất biến (schools/{schoolId}/auditLogs)',
      status: 'COMPLETED',
      detail: `Đã ghi nhật ký kiểm toán mã ${auditLogId}. Hoàn tất 8/8 bước đồng bộ Auth ↔ Firestore ↔ Phân quyền.`,
      executedAt: nowIso,
    });

    return {
      ok: true,
      idempotencyKey: params.idempotencyKey,
      reusedExistingOnRetry,
      provisioningStatus: 'COMPLETED' as const,
      authRecord,
      firestoreProfile,
      assignmentIds: assignmentRecords.map((a) => String(a.assignmentId)),
      permissionDocId,
      auditLogId,
      steps,
      message: reusedExistingOnRetry
        ? `Hoàn tất thử lại an toàn (Idempotent Retry) cho ${params.fullName} (UID: ${uid}) mà không tạo tài khoản trùng.`
        : `Đã khởi tạo và đồng bộ thành công tài khoản ${params.fullName} (UID: ${uid}) qua 8 bước chuẩn.`,
    };
  }

  function loginTeacherOnDevice(params: {
    uidOrEmail: string;
    deviceId: string;
    deviceLabel: string;
  }) {
    const key = params.uidOrEmail.trim().toLowerCase();
    const uid = stage17AuthStore.has(params.uidOrEmail)
      ? params.uidOrEmail
      : stage17EmailToUidIndex.get(key) || '';
    const authRec = stage17AuthStore.get(uid);
    const profile = stage17FirestoreUsersStore.get(uid);

    if (!authRec || !profile) {
      return {
        ok: false,
        httpStatus: 404,
        uid: '',
        deviceId: params.deviceId,
        deviceLabel: params.deviceLabel,
        authStatus: 'NOT_FOUND',
        accountStatus: 'LOCKED' as const,
        roles: [],
        functionalPermissions: [],
        permissionScope: null,
        visibleUiModules: [],
        sessionToken: null,
        firestoreProfile: null,
        message: 'Không tìm thấy tài khoản trên Firebase Authentication / Firestore.',
      };
    }

    if (authRec.disabled || profile.status === 'LOCKED') {
      return {
        ok: false,
        httpStatus: 403,
        uid,
        deviceId: params.deviceId,
        deviceLabel: params.deviceLabel,
        authStatus: 'AUTH_DISABLED_LOCKED',
        accountStatus: profile.status,
        roles: profile.roles,
        functionalPermissions: [],
        permissionScope: profile.permissionScope,
        visibleUiModules: [],
        sessionToken: null,
        firestoreProfile: profile,
        message: `Từ chối đăng nhập: Tài khoản ${profile.fullName} (${profile.email}) đang bị KHÓA (status=LOCKED, auth.disabled=true).`,
      };
    }

    const validAfterMs = Date.parse(authRec.tokensValidAfterTime) || 0;
    const nowMs = Math.max(Date.now(), validAfterMs + 10);
    const issuedAt = new Date(nowMs).toISOString();
    const expiresAt = new Date(nowMs + 3600 * 1000).toISOString();
    const sessionToken = {
      tokenId: `idtok_${uid}_${params.deviceId}_${nowMs}`,
      uid,
      email: authRec.email,
      schoolId: profile.schoolId,
      deviceId: params.deviceId,
      deviceLabel: params.deviceLabel,
      issuedAt,
      expiresAt,
      tokenPermissionVersion: profile.permissionVersion,
    };

    const existingSessions = stage17ActiveSessionsStore.get(uid) || [];
    stage17ActiveSessionsStore.set(uid, [
      ...existingSessions.filter((s) => s.deviceId !== params.deviceId),
      sessionToken,
    ]);

    authRec.lastSignInTime = issuedAt;

    return {
      ok: true,
      httpStatus: 200,
      uid,
      deviceId: params.deviceId,
      deviceLabel: params.deviceLabel,
      authStatus: 'AUTHENTICATED_ACTIVE',
      accountStatus: profile.status,
      roles: profile.roles,
      functionalPermissions: profile.functionalPermissions,
      permissionScope: profile.permissionScope,
      visibleUiModules: computeVisibleUiModules(
        profile.roles,
        profile.functionalPermissions,
        profile.educationLevels
      ),
      sessionToken,
      firestoreProfile: profile,
      message: `Đăng nhập thành công trên [${params.deviceLabel}]: Đã đồng bộ UID=${uid}, Vai trò=${profile.roles.join(', ')}, Môn=${profile.subjects.join(', ')}, Khối=${profile.grades.join(', ')}.`,
    };
  }

  function verifyTeacherBackendAction(params: {
    sessionToken: {
      tokenId: string;
      uid: string;
      email: string;
      schoolId: string;
      deviceId: string;
      deviceLabel: string;
      issuedAt: string;
      expiresAt: string;
      tokenPermissionVersion: number;
    };
    requestedAction: 'CREATE_EXAM' | 'APPRAISE_DEPARTMENT_EXAM' | 'READ_PROFILE';
    targetSubject: string;
    targetGrade: string;
    targetDepartmentId?: string;
  }) {
    const { sessionToken, requestedAction, targetSubject, targetGrade, targetDepartmentId } = params;
    const authRec = stage17AuthStore.get(sessionToken.uid);
    const profile = stage17FirestoreUsersStore.get(sessionToken.uid);

    if (!authRec || !profile) {
      return {
        allowed: false,
        httpStatus: 401,
        reasonCode: 'AUTH_UID_NOT_FOUND',
        message: 'UID không tồn tại trên hệ thống xác thực.',
      };
    }

    // Mục VII: Kiểm tra khóa tài khoản & thu hồi Refresh/ID Token ngay cả khi ID token cũ chưa hết hạn (exp > now)
    const tokenIatMs = Date.parse(sessionToken.issuedAt);
    const validAfterMs = Date.parse(authRec.tokensValidAfterTime);
    if (authRec.disabled || profile.status === 'LOCKED' || tokenIatMs < validAfterMs) {
      return {
        allowed: false,
        httpStatus: 403,
        reasonCode: 'ACCOUNT_LOCKED_OR_TOKEN_REVOKED',
        message: `TỪ CHỐI TẠI BACKEND (403): Tài khoản ${profile.fullName} đang bị KHÓA (status=${profile.status}, auth.disabled=${authRec.disabled}) hoặc ID Token cũ (issuedAt=${sessionToken.issuedAt}) đã bị thu hồi trước mốc tokensValidAfterTime (${authRec.tokensValidAfterTime}) dù thời hạn exp vẫn còn!`,
        refreshedPermissions: [],
        refreshedStatus: profile.status,
      };
    }

    if (requestedAction === 'READ_PROFILE') {
      return {
        allowed: true,
        httpStatus: 200,
        reasonCode: 'PROFILE_READ_ALLOWED',
        message: `Đọc hồ sơ & phân quyền thành công (permissionVersion=${profile.permissionVersion}).`,
        refreshedPermissions: profile.functionalPermissions,
        refreshedStatus: profile.status,
      };
    }

    // Mục VI: Kiểm tra quyền thực tế trực tiếp trên Firestore ở Backend (không tin tưởng quyền cũ trên phiên client)
    if (requestedAction === 'CREATE_EXAM') {
      if (!profile.functionalPermissions.includes('CREATE_EXAM')) {
        return {
          allowed: false,
          httpStatus: 403,
          reasonCode: 'LIVE_PERMISSION_REVOKED_CREATE_EXAM',
          message: `TỪ CHỐI TỨC THÌ TẠI BACKEND (403): Quyền CREATE_EXAM của ${profile.fullName} đã bị thu hồi trên phiên đang hoạt động (permissionVersion=${profile.permissionVersion}). Không cần chờ đăng xuất!`,
          refreshedPermissions: profile.functionalPermissions,
          refreshedStatus: profile.status,
        };
      }

      const subjectAllowed = profile.permissionScope.allowedSubjects.includes(targetSubject);
      const gradeAllowed = profile.permissionScope.allowedGrades.includes(String(targetGrade));
      if (!subjectAllowed || !gradeAllowed) {
        return {
          allowed: false,
          httpStatus: 403,
          reasonCode: 'OUT_OF_SUBJECT_OR_GRADE_SCOPE',
          message: `TỪ CHỐI TẠI BACKEND (403): ${profile.fullName} chỉ được cấp quyền môn [${profile.permissionScope.allowedSubjects.join(', ')}] khối [${profile.permissionScope.allowedGrades.join(', ')}], không được phép tạo đề môn [${targetSubject}] khối [${targetGrade}].`,
          refreshedPermissions: profile.functionalPermissions,
          refreshedStatus: profile.status,
        };
      }

      return {
        allowed: true,
        httpStatus: 200,
        reasonCode: 'CREATE_EXAM_IN_SCOPE_ALLOWED',
        message: `CHO PHÉP (200): ${profile.fullName} tạo đề môn [${targetSubject}] khối [${targetGrade}] hợp lệ đúng phân công giảng dạy và phân quyền.`,
        refreshedPermissions: profile.functionalPermissions,
        refreshedStatus: profile.status,
      };
    }

    if (requestedAction === 'APPRAISE_DEPARTMENT_EXAM') {
      const isHod =
        profile.roles.includes('HEAD_OF_DEPARTMENT') &&
        profile.functionalPermissions.includes('APPRAISE_DEPARTMENT_EXAM');
      const sameDept = !targetDepartmentId || profile.departmentId === targetDepartmentId;
      if (!isHod || !sameDept) {
        return {
          allowed: false,
          httpStatus: 403,
          reasonCode: 'DEPARTMENT_APPRAISAL_DENIED',
          message: `TỪ CHỐI TẠI BACKEND (403): Không có quyền thẩm định cấp tổ hoặc khác tổ chuyên môn (${profile.departmentId} != ${targetDepartmentId}).`,
          refreshedPermissions: profile.functionalPermissions,
          refreshedStatus: profile.status,
        };
      }
      return {
        allowed: true,
        httpStatus: 200,
        reasonCode: 'DEPARTMENT_APPRAISAL_ALLOWED',
        message: `CHO PHÉP (200): Tổ trưởng ${profile.fullName} thẩm định đề môn [${targetSubject}] khối [${targetGrade}] thuộc tổ [${profile.departmentName}].`,
        refreshedPermissions: profile.functionalPermissions,
        refreshedStatus: profile.status,
      };
    }

    return {
      allowed: false,
      httpStatus: 403,
      reasonCode: 'DENY_BY_DEFAULT',
      message: 'Từ chối mặc định.',
    };
  }

  function mutateTeacherAccountSync(params: {
    adminActorUid: string;
    adminActorRole: string;
    targetUid: string;
    schoolId: string;
    mutationType:
      | 'UPDATE_FULL_NAME'
      | 'UPDATE_EMAIL_SYNC_AUTH'
      | 'TRANSFER_DEPARTMENT'
      | 'CHANGE_SUBJECTS'
      | 'CHANGE_GRADES'
      | 'ASSIGN_ROLES'
      | 'REVOKE_PERMISSIONS_LIVE'
      | 'LOCK_ACCOUNT_REVOKE_TOKENS'
      | 'UNLOCK_ACCOUNT';
    updates: {
      fullName?: string;
      newEmail?: string;
      departmentId?: string;
      departmentName?: string;
      subjects?: string[];
      grades?: string[];
      roles?: ('TEACHER' | 'HEAD_OF_DEPARTMENT' | 'VICE_PRINCIPAL' | 'PRINCIPAL' | 'SYSTEM_ADMIN')[];
      functionalPermissions?: string[];
      revokedPermissions?: string[];
      reason?: string;
    };
  }) {
    if (params.adminActorRole !== 'SYSTEM_ADMIN' && params.adminActorRole !== 'PRINCIPAL') {
      return {
        ok: false,
        httpStatus: 403,
        message: 'Chỉ Quản trị viên hệ thống hoặc Hiệu trưởng mới có quyền chỉnh sửa tài khoản & phân quyền.',
        authRecord: null,
        firestoreProfile: null,
        auditLogId: null,
        activeSessionsAffected: 0,
      };
    }

    const authRec = stage17AuthStore.get(params.targetUid);
    const profile = stage17FirestoreUsersStore.get(params.targetUid);
    if (!authRec || !profile) {
      return {
        ok: false,
        httpStatus: 404,
        message: 'Không tìm thấy tài khoản giáo viên cần cập nhật.',
        authRecord: null,
        firestoreProfile: null,
        auditLogId: null,
        activeSessionsAffected: 0,
      };
    }

    const nowIso = new Date(Date.now() + 50).toISOString();
    let actionDesc = '';

    switch (params.mutationType) {
      case 'UPDATE_FULL_NAME': {
        const nextName = (params.updates.fullName || profile.fullName).trim();
        authRec.displayName = nextName;
        profile.fullName = nextName;
        actionDesc = `Đồng bộ sửa họ tên thành "${nextName}" trên cả Firebase Auth (displayName) và Firestore (fullName).`;
        break;
      }
      case 'UPDATE_EMAIL_SYNC_AUTH': {
        const nextEmail = (params.updates.newEmail || profile.email).trim().toLowerCase();
        stage17EmailToUidIndex.delete(authRec.email);
        authRec.email = nextEmail;
        authRec.tokensValidAfterTime = nowIso;
        authRec.sessionRevocationEpoch += 1;
        stage17EmailToUidIndex.set(nextEmail, authRec.uid);
        profile.email = nextEmail;
        profile.permissionVersion += 1;
        profile.securityStamp = `sec_stamp_${authRec.uid}_v${profile.permissionVersion}`;
        actionDesc = `Đồng bộ đổi Email đăng nhập sang "${nextEmail}" trên Firebase Authentication + Firestore và làm mới mốc xác thực phiên.`;
        break;
      }
      case 'TRANSFER_DEPARTMENT': {
        profile.departmentId = params.updates.departmentId || profile.departmentId;
        profile.departmentName = params.updates.departmentName || profile.departmentName;
        profile.permissionScope.departmentId = profile.departmentId;
        profile.permissionVersion += 1;
        actionDesc = `Chuyển tổ chuyên môn sang "${profile.departmentName}" (${profile.departmentId}) và cập nhật phạm vi quyền.`;
        break;
      }
      case 'CHANGE_SUBJECTS': {
        const nextSubjects = params.updates.subjects || profile.subjects;
        profile.subjects = nextSubjects;
        profile.permissionScope.allowedSubjects = nextSubjects;
        profile.permissionVersion += 1;
        actionDesc = `Cập nhật môn giảng dạy sang [${nextSubjects.join(', ')}] và đồng bộ phạm vi quyền.`;
        break;
      }
      case 'CHANGE_GRADES': {
        const nextGrades = params.updates.grades || profile.grades;
        profile.grades = nextGrades;
        profile.permissionScope.allowedGrades = nextGrades;
        profile.permissionVersion += 1;
        actionDesc = `Cập nhật khối lớp giảng dạy sang [${nextGrades.join(', ')}] và đồng bộ phạm vi quyền.`;
        break;
      }
      case 'ASSIGN_ROLES': {
        const nextRoles = params.updates.roles || profile.roles;
        profile.roles = nextRoles;
        profile.permissionScope.canReadConfidentialExam =
          nextRoles.includes('PRINCIPAL') || nextRoles.includes('HEAD_OF_DEPARTMENT');
        profile.permissionScope.canApproveFinalExam = nextRoles.includes('PRINCIPAL');
        profile.permissionVersion += 1;
        actionDesc = `Cập nhật vai trò thành [${nextRoles.join(', ')}] (version=${profile.permissionVersion}).`;
        break;
      }
      case 'REVOKE_PERMISSIONS_LIVE': {
        const revoked = params.updates.revokedPermissions || [];
        const remaining = params.updates.functionalPermissions
          ? params.updates.functionalPermissions
          : profile.functionalPermissions.filter((p) => !revoked.includes(p));
        profile.functionalPermissions = remaining;
        profile.permissionVersion += 1;
        profile.securityStamp = `sec_stamp_${authRec.uid}_v${profile.permissionVersion}`;
        stage17PermissionsStore.set(authRec.uid, {
          ...(stage17PermissionsStore.get(authRec.uid) || {}),
          functionalPermissions: remaining,
          permissionVersion: profile.permissionVersion,
          updatedAt: nowIso,
        });
        actionDesc = `Thu hồi tức thì quyền [${revoked.join(', ')}] trên phiên đang hoạt động (permissionVersion tăng lên ${profile.permissionVersion}). Quyền còn lại: [${remaining.join(', ')}].`;
        break;
      }
      case 'LOCK_ACCOUNT_REVOKE_TOKENS': {
        authRec.disabled = true;
        authRec.tokensValidAfterTime = nowIso;
        authRec.sessionRevocationEpoch += 1;
        profile.status = 'LOCKED';
        profile.permissionVersion += 1;
        profile.securityStamp = `sec_stamp_${authRec.uid}_locked_${authRec.sessionRevocationEpoch}`;
        actionDesc = `Đã KHÓA tài khoản ${profile.fullName}: Cập nhật Firestore status=LOCKED, vô hiệu hóa Firebase Auth (disabled=true) và thu hồi toàn bộ Refresh/ID Token cũ (tokensValidAfterTime=${nowIso}).`;
        break;
      }
      case 'UNLOCK_ACCOUNT': {
        authRec.disabled = false;
        profile.status = 'ACTIVE';
        profile.permissionVersion += 1;
        profile.securityStamp = `sec_stamp_${authRec.uid}_unlocked_${profile.permissionVersion}`;
        actionDesc = `Đã MỞ KHÓA tài khoản ${profile.fullName}: Khôi phục Firestore status=ACTIVE và kích hoạt lại Firebase Auth (disabled=false).`;
        break;
      }
    }

    authRec.updatedAt = nowIso;
    profile.updatedAt = nowIso;
    profile.updatedBy = params.adminActorUid;

    const activeSessions = stage17ActiveSessionsStore.get(authRec.uid) || [];
    const auditLogId = `audit_mut_${authRec.uid}_${Date.now()}`;
    stage17AuditLogsStore.unshift({
      logId: auditLogId,
      schoolId: params.schoolId,
      actorUid: params.adminActorUid,
      mutationType: params.mutationType,
      targetUid: authRec.uid,
      description: actionDesc,
      createdAt: nowIso,
    });

    return {
      ok: true,
      httpStatus: 200,
      message: actionDesc,
      authRecord: authRec,
      firestoreProfile: profile,
      auditLogId,
      activeSessionsAffected: activeSessions.length,
    };
  }

