  function verifyDataAdminPermissionBackend(params: {
    actorId: string;
    actorRole: string;
    schoolId: string;
    actionName: string;
  }): {
    allowed: boolean;
    httpStatus: number;
    code: string;
    message: string;
    actorName: string;
  } {
    const role = String(params.actorRole || '').toUpperCase();
    const actorMap: Record<string, string> = {
      'user-admin-sys': 'Quản trị viên Hệ thống (System Admin)',
      'uid_bgh_ht_001': 'Cô Phạm Thu Thủy (Hiệu trưởng)',
      'user-principal-a': 'Cô Phạm Thu Thủy (Hiệu trưởng)',
      'uid_gv_nd_th_001': 'Cô Nguyễn Thị Mai Hương (Giáo viên Tiểu học)',
      'uid_gv_nd_thcs_002': 'Thầy Trần Quốc Tuấn (Giáo viên KHTN)',
      'uid_ttcm_nd_khtn_003': 'Thầy Lê Hoàng Nam (Tổ trưởng KHTN)',
      'user-teacher-a': 'Cô Nguyễn Thị Mai Lan (Giáo viên)',
    };
    const actorName = actorMap[params.actorId] || `Tài khoản (${params.actorId})`;

    // Mục VII: Chỉ người có quyền quản trị dữ liệu (SYSTEM_ADMIN hoặc PRINCIPAL) mới được truy cập và thực thi
    if (role !== 'SYSTEM_ADMIN' && role !== 'PRINCIPAL') {
      appendSanitizedFirebaseSyncLog({
        schoolId: params.schoolId,
        moduleName: 'Trung tâm Quản lý Dữ liệu Firebase',
        operationType: 'AUTH_RBAC_GUARD',
        actorId: params.actorId,
        actorName,
        actorRole: role || 'UNKNOWN',
        status: 'DENIED_RBAC',
        errorCode: 'ERR_403_DATA_ADMIN_REQUIRED',
        relatedRecordId: params.actionName,
        rawSummaryMessage: `Từ chối truy cập (403 FORBIDDEN): Vai trò [${role}] không có quyền quản trị dữ liệu Firebase tại thao tác [${params.actionName}].`,
      });
      return {
        allowed: false,
        httpStatus: 403,
        code: 'ERR_403_DATA_ADMIN_REQUIRED',
        message: `TỪ CHỐI TRUY CẬP (HTTP 403): Tài khoản ${actorName} (Vai trò: ${role}) không có quyền quản trị dữ liệu Firebase. Chỉ Quản trị hệ thống (SYSTEM_ADMIN) hoặc Hiệu trưởng (PRINCIPAL) được cấp quyền mới được phép truy cập.`,
        actorName,
      };
    }

    return {
      allowed: true,
      httpStatus: 200,
      code: 'DATA_ADMIN_AUTHORIZED',
      message: 'Xác thực quyền Quản trị dữ liệu Firebase hợp lệ tại Backend.',
      actorName,
    };
  }

