  function buildLive11DataStatistics(schoolId: string) {
    initializeStage17ProtectedDataAndVersions(schoolId);
    const nowIso = new Date().toISOString();

    const mapping: Array<{
      order: number;
      counterCode:
        | 'USERS'
        | 'DEPARTMENTS'
        | 'TEACHING_ASSIGNMENTS'
        | 'QUESTIONS'
        | 'MATRICES'
        | 'SPECIFICATIONS'
        | 'EXAMS'
        | 'AI_REVIEWS'
        | 'APPRAISAL_DOSSIERS'
        | 'APPROVAL_DOSSIERS'
        | 'EXAM_RESULTS';
      label: string;
      storeKey: string;
      firestoreCollectionPath: string;
    }> = [
      {
        order: 1,
        counterCode: 'USERS',
        label: '1. Số tài khoản',
        storeKey: 'USERS_ACCOUNTS',
        firestoreCollectionPath: `schools/${schoolId}/users`,
      },
      {
        order: 2,
        counterCode: 'DEPARTMENTS',
        label: '2. Số tổ chuyên môn',
        storeKey: 'DEPARTMENTS',
        firestoreCollectionPath: `schools/${schoolId}/departments`,
      },
      {
        order: 3,
        counterCode: 'TEACHING_ASSIGNMENTS',
        label: '3. Số phân công giảng dạy',
        storeKey: 'PERMISSIONS_AND_ASSIGNMENTS',
        firestoreCollectionPath: `schools/${schoolId}/teachingAssignments`,
      },
      {
        order: 4,
        counterCode: 'QUESTIONS',
        label: '4. Số câu hỏi',
        storeKey: 'QUESTION_BANK',
        firestoreCollectionPath: `schools/${schoolId}/questions`,
      },
      {
        order: 5,
        counterCode: 'MATRICES',
        label: '5. Số ma trận',
        storeKey: 'MATRICES',
        firestoreCollectionPath: `schools/${schoolId}/matrices`,
      },
      {
        order: 6,
        counterCode: 'SPECIFICATIONS',
        label: '6. Số bản đặc tả',
        storeKey: 'SPECIFICATIONS',
        firestoreCollectionPath: `schools/${schoolId}/specifications`,
      },
      {
        order: 7,
        counterCode: 'EXAMS',
        label: '7. Số đề kiểm tra',
        storeKey: 'EXAMS',
        firestoreCollectionPath: `schools/${schoolId}/exams`,
      },
      {
        order: 8,
        counterCode: 'AI_REVIEWS',
        label: '8. Số báo cáo AI',
        storeKey: 'AI_REVIEWS',
        firestoreCollectionPath: `schools/${schoolId}/aiReviews`,
      },
      {
        order: 9,
        counterCode: 'APPRAISAL_DOSSIERS',
        label: '9. Số hồ sơ thẩm định',
        storeKey: 'DEPARTMENT_APPRAISALS',
        firestoreCollectionPath: `schools/${schoolId}/examWorkflows`,
      },
      {
        order: 10,
        counterCode: 'APPROVAL_DOSSIERS',
        label: '10. Số hồ sơ phê duyệt',
        storeKey: 'LEADERSHIP_APPROVALS',
        firestoreCollectionPath: `schools/${schoolId}/approvals`,
      },
      {
        order: 11,
        counterCode: 'EXAM_RESULTS',
        label: '11. Số báo cáo kết quả',
        storeKey: 'EXAM_RESULTS',
        firestoreCollectionPath: `schools/${schoolId}/examResults`,
      },
    ];

    return mapping.map((item) => {
      const docs = stage17Live12CollectionsStore.get(item.storeKey) || [];
      const activeDocs = docs.filter((d) => !d.isDeleted);
      const approvedOrLockedCount = activeDocs.filter((d) =>
        ['APPROVED', 'ACTIVE', 'COMPLETED', 'APPRAISED', 'LOCKED'].includes(String(d.status || 'ACTIVE'))
      ).length;
      const draftOrPendingCount = activeDocs.length - approvedOrLockedCount;
      const softDeletedCount = docs.filter((d) => Boolean(d.isDeleted)).length;

      return {
        order: item.order,
        counterCode: item.counterCode,
        label: item.label,
        firestoreCollectionPath: item.firestoreCollectionPath,
        totalActiveCount: activeDocs.length,
        approvedOrLockedCount,
        draftOrPendingCount,
        softDeletedCount,
        sourceType: 'FIRESTORE_LIVE_QUERY_AND_AGGREGATION' as const,
        sha256IntegrityDigest: computeSha256(JSON.stringify(activeDocs)).slice(0, 16),
        lastAggregatedAt: nowIso,
      };
    });
  }

