    const data12CrudResults = COLLECTION_GROUP_META.map((meta, idx) => {
      const docs = stage17Live12CollectionsStore.get(meta.groupCode) || [];
      const testDocId = `qa17_crud_${meta.groupCode.toLowerCase()}`;
      const createdDoc = {
        id: testDocId,
        schoolId,
        title: `Bản ghi nghiệm thu Giai đoạn 17 - ${meta.vietnameseName}`,
        version: 1,
        status: 'ACTIVE',
        createdAt: executedAt,
        updatedAt: executedAt,
      };
      // 1. Create
      const afterCreate = [...docs, createdDoc];
      stage17Live12CollectionsStore.set(meta.groupCode, afterCreate);
      // 2. Read back
      const readDoc = (stage17Live12CollectionsStore.get(meta.groupCode) || []).find(
        (d) => d.id === testDocId
      );
      // 3. Update
      const updatedDoc = {
        ...readDoc,
        version: 2,
        updatedAt: new Date().toISOString(),
        qaVerified: true,
      };
      stage17Live12CollectionsStore.set(
        meta.groupCode,
        afterCreate.map((d) => (d.id === testDocId ? updatedDoc : d))
      );
      const readAfterUpdate = (stage17Live12CollectionsStore.get(meta.groupCode) || []).find(
        (d) => d.id === testDocId
      );
      // Hoàn trả lại đúng số lượng gốc để giữ sạch dữ liệu
      stage17Live12CollectionsStore.set(meta.groupCode, docs);

      const passed =
        Boolean(readDoc) &&
        readAfterUpdate?.version === 2 &&
        readAfterUpdate?.qaVerified === true;

      return {
        order: idx + 1,
        groupCode: meta.groupCode,
        vietnameseName: meta.vietnameseName,
        firestorePath: `schools/${schoolId}/${meta.pathSuffix}`,
        createOk: Boolean(readDoc),
        readOk: Boolean(readDoc),
        updateVersionOk: readAfterUpdate?.version === 2,
        activeCount: docs.length,
        passed,
      };
    });

