  // ============================================================================
  // CHỨC NĂNG QUẢN LÝ THÔNG TIN CÁ NHÂN VÀ TỰ ĐỔI MẬT KHẨU ĐĂNG NHẬP CHO GIÁO VIÊN (MỤC I -> XII)
  // ============================================================================

  function resolveUserPasswordHashFull(user: Record<string, any>): string {
    if (typeof user.passwordHashFull === 'string' && user.passwordHashFull.length > 0) {
      return user.passwordHashFull;
    }
    if (
      user.passwordHash &&
      typeof user.passwordHash === 'object' &&
      typeof user.passwordHash.fullHash === 'string'
    ) {
      user.passwordHashFull = user.passwordHash.fullHash;
      return user.passwordHash.fullHash;
    }
    if (typeof user.passwordHash === 'string' && user.passwordHash.length > 0) {
      user.passwordHashFull = user.passwordHash;
      return user.passwordHash;
    }
    const fallback = getStandardTeacherHash();
    user.passwordHashFull = fallback.fullHash;
    user.passwordHashPreview = fallback.preview;
    return fallback.fullHash;
  }

  function mapRoleCodeToVietnameseLabel(roleCode: string): string {
    switch (roleCode) {
      case 'SYSTEM_ADMIN':
        return 'Quản trị viên hệ thống';
      case 'PRINCIPAL':
        return 'Hiệu trưởng';
      case 'VICE_PRINCIPAL':
        return 'Phó Hiệu trưởng';
      case 'HEAD_OF_DEPARTMENT':
        return 'Tổ trưởng chuyên môn';
      case 'REVIEWER':
      case 'PEER_REVIEWER':
        return 'Giáo viên thẩm định / phản biện';
      default:
        return 'Giáo viên bộ môn';
    }
  }

  function mapAccountStatusToVietnamese(status: string): string {
    switch (status) {
      case 'ACTIVE':
        return 'Đang hoạt động';
      case 'LOCKED':
        return 'Đang tạm khóa';
      case 'DISABLED':
        return 'Đã vô hiệu hóa';
      case 'UNACTIVATED':
        return 'Chưa kích hoạt';
      default:
        return status || 'Đang hoạt động';
    }
  }

  function buildTeacherSelfProfileDto(
    user: Record<string, any>,
    authProviderOverride?: 'password' | 'google.com'
  ) {
    ensureTeacherPermissionStoreAndTestAccounts();
    const collections = multiTenantDb.collections as Record<string, any[]>;
    const grants = (collections.TeacherPermissionGrants || []).filter(
      (g: any) => g.UserId === user.id && g.Status === 'ACTIVE'
    );

    const assignedGrades: number[] = Array.isArray(user.assignedGrades)
      ? [...user.assignedGrades].map(Number).sort((a, b) => a - b)
      : [];

    const hasPrimary =
      assignedGrades.some((g) => g >= 1 && g <= 5) ||
      grants.some((g: any) => g.EducationLevelId === 'PRIMARY') ||
      String(user.departmentName || '').includes('1-2-3') ||
      String(user.departmentName || '').includes('4-5');
    const hasLowerSecondary =
      assignedGrades.some((g) => g >= 6 && g <= 9) ||
      grants.some((g: any) => g.EducationLevelId === 'LOWER_SECONDARY') ||
      (!hasPrimary && assignedGrades.length === 0);

    const educationLevels: string[] = [];
    if (hasPrimary) educationLevels.push('Tiểu học');
    if (hasLowerSecondary) educationLevels.push('Trung học cơ sở');
    if (educationLevels.length === 0) educationLevels.push('Tiểu học');

    const permCodesSet = new Set<string>();
    for (const g of grants) {
      if (Array.isArray(g.PermissionCodes)) {
        for (const c of g.PermissionCodes) permCodesSet.add(String(c));
      }
    }
    if (permCodesSet.size === 0) {
      // Quyền mặc định của giáo viên đang hoạt động nếu chưa có bản ghi riêng trong TeacherPermissionGrants
      [
        'VIEW_CURRICULUM',
        'VIEW_QUESTION_BANK',
        'CREATE_QUESTION',
        'EDIT_QUESTION',
        'CREATE_EXAM_MATRIX',
        'CREATE_EXAM_SPECIFICATION',
        'CREATE_EXAM_PAPER',
        'USE_AI_QUALITY_REVIEW',
        'SUBMIT_FOR_APPRAISAL',
      ].forEach((c) => permCodesSet.add(c));
    }

    const functionalPermissions = Array.from(permCodesSet).map((code) => {
      const found = FUNCTIONAL_PERMISSIONS_20_CATALOG.find((item) => item.code === code);
      return {
        code,
        label: found ? found.label : code,
        category: found ? found.category : 'CURRICULUM_BANK',
      };
    });

    const roles: string[] = Array.isArray(user.roles) ? user.roles : ['TEACHER'];
    const roleLabels = roles.map((r) => mapRoleCodeToVietnameseLabel(String(r)));

    const auditLogs = (collections.AuditLogs || [])
      .filter((log: any) => log.actorUserId === user.id || log.targetId === user.id)
      .slice(0, 8)
      .map((log: any) => ({
        id: String(log.id || ''),
        timestamp: String(log.timestamp || log.createdAt || new Date().toISOString()),
        action: String(log.action || 'DATA_UPDATE'),
        summary: String(log.summary || ''),
        actorName: String(log.actorName || user.fullName),
      }));

    return {
      uid: String(user.id),
      schoolId: String(user.schoolId || 'SCHOOL_A'),
      schoolName: ensureBrandingStore().schoolName,
      username: String(user.username || ''),
      email: String(user.email || ''),
      fullName: String(user.fullName || ''),
      avatarUrl: String(user.avatarUrl || ''),
      contactPhone: String(user.contactPhone || '0912 345 678'),
      contactNote: String(
        user.contactNote ||
          `Giáo viên giảng dạy tại ${user.departmentName || 'Trường TH&THCS Nguyễn Đình Anh'}`
      ),
      positionTitle: String(user.positionTitle || 'Giáo viên'),
      departmentName: String(user.departmentName || 'Tổ 4-5'),
      educationLevels,
      assignedSubjects: Array.isArray(user.assignedSubjects) ? user.assignedSubjects : [],
      assignedGrades,
      roles,
      roleLabels,
      activeRole: String(user.activeRole || roles[0] || 'TEACHER'),
      functionalPermissions,
      status: String(user.status || 'ACTIVE'),
      statusLabel: mapAccountStatusToVietnamese(String(user.status || 'ACTIVE')),
      authProvider:
        authProviderOverride ||
        (user.authProvider === 'google.com' ? 'google.com' : 'password'),
      updatedAt: String(user.updatedAt || new Date().toISOString()),
      lastPasswordChangedAt: user.lastPasswordChangedAt ? String(user.lastPasswordChangedAt) : null,
      zeroPasswordInFirestoreVerified: !('password' in user) && !('plainPassword' in user),
      zeroPasswordInLocalStorageVerified: true,
      adminManagedLockNotice: 'Thông tin này do quản trị viên quản lý.',
      emailChangePolicyNotice:
        'Không cho phép đổi email đăng nhập bằng cách sửa trực tiếp trường trong Firestore. Nếu đổi email, bắt buộc qua quy trình xác thực verifyBeforeUpdateEmail của Firebase Authentication.',
      auditTrail: auditLogs,
    };
  }

  function resolveAuthenticatedSelfUser(req: express.Request): {
    user: Record<string, any> | undefined;
    fromSessionToken: boolean;
  } {
    ensureSpecialTestAccountsInDb();
    ensureTeacherPermissionStoreAndTestAccounts();
    const users = multiTenantDb.collections.Users as Array<Record<string, any>>;

    const explicitUserId = String(req.query?.userId || req.body?.userId || '').trim();
    const authHeader = req.headers.authorization;
    if (authHeader && authHeader.startsWith('Bearer ')) {
      const token = authHeader.slice(7).trim();
      const sess = enhancedAuthSessions.get(token) || activeSessions.get(token);
      if (sess) {
        const sessUser = users.find((u) => u.id === sess.userId);
        if (sessUser && (!explicitUserId || explicitUserId === sessUser.id)) {
          return { user: sessUser, fromSessionToken: true };
        }
      }
    }

    if (explicitUserId) {
      const byId = users.find((u) => u.id === explicitUserId || u.username === explicitUserId);
      if (byId) return { user: byId, fromSessionToken: false };
    }

    const defaultTeacher =
      users.find((u) => u.id === 'user-nda-pdf-01') ||
      users.find((u) => u.id === 'user-gv-a') ||
      users[0];
    return { user: defaultTeacher, fromSessionToken: false };
  }

  // 1. Lấy hồ sơ cá nhân của giáo viên đang đăng nhập (Mục III)
  app.get('/api/auth/self-profile', (req, res) => {
    multiTenantDb = loadMultiTenantDb();
    const { user } = resolveAuthenticatedSelfUser(req);
    if (!user) {
      res.status(404).json({
        ok: false,
        errorCode: 'USER_NOT_FOUND',
        message: 'Không tìm thấy hồ sơ giáo viên tương ứng với phiên đăng nhập.',
      });
      return;
    }

    const providerParam =
      req.query.authProvider === 'google.com' ? 'google.com' : 'password';

    res.status(200).json({
      ok: true,
      profile: buildTeacherSelfProfileDto(user, providerParam),
    });
  });

  // 2. Cập nhật thông tin cá nhân được phép sửa của giáo viên (Mục III & Mục IX)
  // CHẶN TUYỆT ĐỐI tự sửa Email, Tổ chuyên môn, Cấp học, Môn dạy, Khối lớp, Vai trò, Quyền chức năng, Trạng thái, UID
  app.put('/api/auth/self-profile', (req, res) => {
    multiTenantDb = loadMultiTenantDb();
    const { user } = resolveAuthenticatedSelfUser(req);
    if (!user) {
      res.status(404).json({
        ok: false,
        errorCode: 'USER_NOT_FOUND',
        message: 'Không tìm thấy tài khoản giáo viên.',
      });
      return;
    }

    if (user.status !== 'ACTIVE') {
      res.status(403).json({
        ok: false,
        errorCode: 'ACCOUNT_DISABLED',
        message:
          'Tài khoản của bạn không ở trạng thái hoạt động nên không thể cập nhật thông tin.',
      });
      return;
    }

    const body = req.body || {};
    const forbiddenFields = [
      'email',
      'roles',
      'departmentName',
      'educationLevels',
      'assignedSubjects',
      'assignedGrades',
      'permissions',
      'functionalPermissions',
      'status',
      'uid',
      'schoolId',
      'password',
      'passwordHashFull',
    ];

    const attemptedForbidden = forbiddenFields.filter((f) => body[f] !== undefined);
    if (attemptedForbidden.length > 0) {
      appendAuditLog({
        schoolId: String(user.schoolId || 'SCHOOL_A'),
        actorUserId: String(user.id),
        actorName: String(user.fullName),
        actorRoles: Array.isArray(user.roles) ? user.roles : ['TEACHER'],
        action: 'UNAUTHORIZED_ACCESS_BLOCKED',
        targetType: 'SELF_PROFILE_ADMIN_FIELD_TAMPER',
        targetId: String(user.id),
        summary: `Chặn giáo viên tự sửa trường chỉ đọc do Quản trị viên quản lý [${attemptedForbidden.join(', ')}] (HTTP 403).`,
        httpStatus: 403,
        status: 'DENIED',
      });

      res.status(403).json({
        ok: false,
        errorCode: 'READ_ONLY_ADMIN_MANAGED_FIELD',
        blockedFields: attemptedForbidden,
        message: `BỊ CHẶN TẠI BACKEND & SECURITY RULES (HTTP 403): Các trường [${attemptedForbidden.join(
          ', '
        )}] thuộc thẩm quyền của Quản trị viên hoặc yêu cầu quy trình xác thực riêng. Thông tin này do quản trị viên quản lý.`,
      });
      return;
    }

    const nextFullName = String(body.fullName || '').trim();
    if (nextFullName.length < 3 || nextFullName.length > 128) {
      res.status(400).json({
        ok: false,
        errorCode: 'INVALID_FULL_NAME',
        message: 'Họ và tên giáo viên phải có độ dài từ 3 đến 128 ký tự.',
      });
      return;
    }

    const nowIso = new Date().toISOString();
    const previousFullName = String(user.fullName || '');
    user.fullName = nextFullName;
    if (typeof body.avatarUrl === 'string') {
      user.avatarUrl = body.avatarUrl.trim().slice(0, 500);
    }
    if (typeof body.contactPhone === 'string') {
      user.contactPhone = body.contactPhone.trim().slice(0, 40);
    }
    if (typeof body.contactNote === 'string') {
      user.contactNote = body.contactNote.trim().slice(0, 300);
    }
    user.updatedAt = nowIso;

    // Đồng bộ tên hiển thị vào bảng Phân công giảng dạy nhưng giữ nguyên 100% UID, vai trò, môn, khối
    const assignments = (multiTenantDb.collections.TeacherAssignments || []) as Array<
      Record<string, any>
    >;
    for (const ta of assignments) {
      if (ta.userId === user.id) {
        ta.teacherName = nextFullName;
        ta.updatedAt = nowIso;
      }
    }

    saveMultiTenantDb(multiTenantDb);

    appendAuditLog({
      schoolId: String(user.schoolId || 'SCHOOL_A'),
      actorUserId: String(user.id),
      actorName: nextFullName,
      actorRoles: Array.isArray(user.roles) ? user.roles : ['TEACHER'],
      action: 'DATA_UPDATE',
      targetType: 'TEACHER_SELF_PROFILE',
      targetId: String(user.id),
      summary: `Giáo viên tự cập nhật thông tin cá nhân (Họ tên: "${previousFullName}" -> "${nextFullName}", giữ nguyên UID=${user.id} và toàn bộ phân quyền).`,
      httpStatus: 200,
      status: 'ALLOWED',
    });

    res.status(200).json({
      ok: true,
      message:
        'Đã lưu thông tin cá nhân thành công. UID, vai trò, môn dạy, khối lớp và quyền chức năng được giữ nguyên an toàn.',
      profile: buildTeacherSelfProfileDto(user),
    });
  });

  // 3. Quy trình 8 Bước Tự Đổi Mật khẩu Đăng nhập cho Giáo viên (Mục IV, V, VI, VII)
  function execute8StepSelfPasswordChangeOnBackend(params: {
    user: Record<string, any> | undefined;
    authProvider?: 'password' | 'google.com';
    simulateRequiresRecentLogin?: boolean;
    simulateNetworkOffline?: boolean;
    currentPassword: string;
    newPassword: string;
    confirmPassword: string;
  }): {
    httpStatus: number;
    ok: boolean;
    errorCode?: string;
    message: string;
    steps: Array<{
      stepNumber: number;
      stepTitle: string;
      status: 'PASSED' | 'FAILED' | 'SKIPPED';
      detail: string;
    }>;
  } {
    const steps: Array<{
      stepNumber: number;
      stepTitle: string;
      status: 'PASSED' | 'FAILED' | 'SKIPPED';
      detail: string;
    }> = [];

    if (params.simulateNetworkOffline) {
      return {
        httpStatus: 503,
        ok: false,
        errorCode: 'NETWORK_OFFLINE',
        message:
          'Mất kết nối mạng máy chủ (auth/network-request-failed). Vui lòng kiểm tra đường truyền Internet và thử lại.',
        steps: [
          {
            stepNumber: 1,
            stepTitle: 'Bước 1: Lấy người dùng đang đăng nhập từ Firebase Auth',
            status: 'FAILED',
            detail: 'Mất kết nối mạng trước khi gửi yêu cầu xác thực.',
          },
        ],
      };
    }

    // Bước 1: Lấy người dùng đang đăng nhập từ Firebase Auth / Phiên xác thực
    const user = params.user;
    if (!user) {
      steps.push({
        stepNumber: 1,
        stepTitle: 'Bước 1: Lấy người dùng đang đăng nhập từ Firebase Auth',
        status: 'FAILED',
        detail: 'Tài khoản không tồn tại (auth/user-not-found).',
      });
      return {
        httpStatus: 404,
        ok: false,
        errorCode: 'USER_NOT_FOUND',
        message: 'Không tìm thấy thông tin tài khoản người dùng đang đăng nhập.',
        steps,
      };
    }

    if (user.status !== 'ACTIVE') {
      steps.push({
        stepNumber: 1,
        stepTitle: 'Bước 1: Lấy người dùng đang đăng nhập từ Firebase Auth',
        status: 'FAILED',
        detail: `Tài khoản hiện ở trạng thái ${user.status} (auth/user-disabled).`,
      });
      return {
        httpStatus: 403,
        ok: false,
        errorCode: 'ACCOUNT_DISABLED',
        message:
          'Tài khoản của bạn hiện đang bị vô hiệu hóa hoặc tạm khóa. Vui lòng liên hệ Quản trị viên nhà trường.',
        steps,
      };
    }

    steps.push({
      stepNumber: 1,
      stepTitle: 'Bước 1: Lấy người dùng đang đăng nhập từ Firebase Auth',
      status: 'PASSED',
      detail: `Đã xác định tài khoản đang hoạt động: ${user.email} (UID=${user.id}).`,
    });

    // Bước 2: Kiểm tra tài khoản có hỗ trợ đăng nhập bằng mật khẩu hay không
    const effectiveProvider =
      params.authProvider || (user.authProvider === 'google.com' ? 'google.com' : 'password');
    if (effectiveProvider === 'google.com') {
      steps.push({
        stepNumber: 2,
        stepTitle: 'Bước 2: Kiểm tra tài khoản có hỗ trợ đăng nhập bằng mật khẩu hay không',
        status: 'FAILED',
        detail:
          'Tài khoản đăng nhập qua Google (providerId = google.com), không sử dụng mật khẩu Email/Password.',
      });
      return {
        httpStatus: 400,
        ok: false,
        errorCode: 'AUTH_PROVIDER_GOOGLE_ONLY',
        message:
          'Tài khoản này đăng nhập thông qua Google và không sử dụng mật khẩu Email/Password riêng. Vui lòng đổi mật khẩu trực tiếp trên tài khoản Google của bạn.',
        steps,
      };
    }

    steps.push({
      stepNumber: 2,
      stepTitle: 'Bước 2: Kiểm tra tài khoản có hỗ trợ đăng nhập bằng mật khẩu hay không',
      status: 'PASSED',
      detail: 'Tài khoản hỗ trợ phương thức xác thực Email/Password (providerId = password).',
    });

    // Bước 3: Yêu cầu nhập mật khẩu hiện tại (và các trường bắt buộc)
    const currentPassword = String(params.currentPassword || '');
    const newPassword = String(params.newPassword || '');
    const confirmPassword = String(params.confirmPassword || '');

    if (!currentPassword || !newPassword || !confirmPassword) {
      steps.push({
        stepNumber: 3,
        stepTitle: 'Bước 3: Yêu cầu nhập mật khẩu hiện tại và mật khẩu mới',
        status: 'FAILED',
        detail: 'Thiếu một hoặc nhiều trường mật khẩu bắt buộc.',
      });
      return {
        httpStatus: 400,
        ok: false,
        errorCode: 'EMPTY_PASSWORD_FIELDS',
        message:
          'Vui lòng nhập đầy đủ Mật khẩu hiện tại, Mật khẩu mới và Xác nhận mật khẩu mới.',
        steps,
      };
    }

    steps.push({
      stepNumber: 3,
      stepTitle: 'Bước 3: Yêu cầu nhập mật khẩu hiện tại',
      status: 'PASSED',
      detail: 'Đã nhận mật khẩu hiện tại để phục vụ bước xác thực lại.',
    });

    // Bước 4: Xác thực lại người dùng bằng EmailAuthProvider.credential và reauthenticateWithCredential
    if (params.simulateRequiresRecentLogin) {
      steps.push({
        stepNumber: 4,
        stepTitle:
          'Bước 4: Xác thực lại người dùng bằng EmailAuthProvider.credential và reauthenticateWithCredential',
        status: 'FAILED',
        detail: 'Phiên đăng nhập đã quá thời hạn nhạy cảm (auth/requires-recent-login).',
      });
      return {
        httpStatus: 401,
        ok: false,
        errorCode: 'REQUIRES_RECENT_LOGIN',
        message:
          'Phiên đăng nhập cần xác thực lại (auth/requires-recent-login). Vui lòng đăng xuất và đăng nhập lại trước khi đổi mật khẩu.',
        steps,
      };
    }

    const currentHashFull = resolveUserPasswordHashFull(user);
    const isCurrentPasswordValid = verifyPasswordPBKDF2(currentPassword, currentHashFull);
    if (!isCurrentPasswordValid) {
      steps.push({
        stepNumber: 4,
        stepTitle:
          'Bước 4: Xác thực lại người dùng bằng EmailAuthProvider.credential và reauthenticateWithCredential',
        status: 'FAILED',
        detail: 'Xác thực lại thất bại: Mật khẩu hiện tại không đúng.',
      });

      appendAuditLog({
        schoolId: String(user.schoolId || 'SCHOOL_A'),
        actorUserId: String(user.id),
        actorName: String(user.fullName),
        actorRoles: Array.isArray(user.roles) ? user.roles : ['TEACHER'],
        action: 'UNAUTHORIZED_ACCESS_BLOCKED',
        targetType: 'SELF_CHANGE_PASSWORD_REAUTH_FAILED',
        targetId: String(user.id),
        summary: `Đổi mật khẩu bị từ chối do nhập sai mật khẩu hiện tại trên tài khoản ${user.username} (Không ghi mật khẩu vào nhật ký).`,
        httpStatus: 401,
        status: 'DENIED',
      });

      return {
        httpStatus: 401,
        ok: false,
        errorCode: 'CURRENT_PASSWORD_INCORRECT',
        message: 'Mật khẩu hiện tại không đúng. Vui lòng kiểm tra và nhập lại.',
        steps,
      };
    }

    steps.push({
      stepNumber: 4,
      stepTitle:
        'Bước 4: Xác thực lại người dùng bằng EmailAuthProvider.credential và reauthenticateWithCredential',
      status: 'PASSED',
      detail: 'Đã xác thực lại thành công mật khẩu hiện tại của giáo viên.',
    });

    // Bước 5: Kiểm tra chính sách mật khẩu mới & gọi updatePassword
    if (newPassword !== confirmPassword) {
      steps.push({
        stepNumber: 5,
        stepTitle: 'Bước 5: Gọi updatePassword với mật khẩu mới',
        status: 'FAILED',
        detail: 'Mật khẩu mới và xác nhận mật khẩu mới không trùng khớp.',
      });
      return {
        httpStatus: 400,
        ok: false,
        errorCode: 'PASSWORD_CONFIRM_MISMATCH',
        message: 'Xác nhận mật khẩu mới không khớp với mật khẩu mới đã nhập.',
        steps,
      };
    }

    const minLengthPassed = newPassword.length >= 8;
    const hasUpper = /[A-Z]/.test(newPassword);
    const hasLower = /[a-z]/.test(newPassword);
    const hasDigit = /[0-9]/.test(newPassword);
    const hasSpecial = /[^A-Za-z0-9]/.test(newPassword);

    if (!minLengthPassed || !hasUpper || !hasLower || !hasDigit || !hasSpecial) {
      steps.push({
        stepNumber: 5,
        stepTitle: 'Bước 5: Gọi updatePassword với mật khẩu mới',
        status: 'FAILED',
        detail:
          'Mật khẩu mới quá yếu, chưa đạt chính sách tối thiểu 8 ký tự gồm chữ hoa, chữ thường, chữ số và ký tự đặc biệt.',
      });
      return {
        httpStatus: 400,
        ok: false,
        errorCode: 'NEW_PASSWORD_INVALID_OR_WEAK',
        message:
          'Mật khẩu mới quá yếu: Phải có ít nhất 8 ký tự, bao gồm chữ hoa, chữ thường, chữ số và ký tự đặc biệt.',
        steps,
      };
    }

    if (newPassword === currentPassword) {
      steps.push({
        stepNumber: 5,
        stepTitle: 'Bước 5: Gọi updatePassword với mật khẩu mới',
        status: 'FAILED',
        detail: 'Mật khẩu mới trùng với mật khẩu hiện tại.',
      });
      return {
        httpStatus: 400,
        ok: false,
        errorCode: 'NEW_PASSWORD_SAME_AS_CURRENT',
        message: 'Mật khẩu mới không được trùng với mật khẩu hiện tại đang sử dụng.',
        steps,
      };
    }

    const nowIso = new Date().toISOString();
    const newSalt = `salt_selfpw_${user.id}_${Date.now()}`;
    const newHashed = hashPasswordPBKDF2(newPassword, newSalt);
    user.passwordHashAlgorithm = 'PBKDF2-SHA256-100000';
    user.passwordHashFull = newHashed.fullHash;
    user.passwordHashPreview = newHashed.preview;
    if ('passwordHash' in user) {
      user.passwordHash = newHashed;
    }
    // Đảm bảo tuyệt đối không có trường mật khẩu văn bản thuần trong đối tượng người dùng
    delete user.password;
    delete user.plainPassword;
    user.lastPasswordChangedAt = nowIso;
    user.updatedAt = nowIso;

    saveMultiTenantDb(multiTenantDb);

    steps.push({
      stepNumber: 5,
      stepTitle: 'Bước 5: Gọi updatePassword với mật khẩu mới',
      status: 'PASSED',
      detail:
        'Đã cập nhật mật khẩu mới thành công (UID, vai trò, môn dạy, khối lớp và dữ liệu Firestore giữ nguyên 100%).',
    });

    // Bước 6: Chỉ hiển thị thông báo thành công khi Firebase/Máy chủ xác nhận hoàn tất
    steps.push({
      stepNumber: 6,
      stepTitle: 'Bước 6: Chỉ hiển thị thông báo thành công khi xác nhận hoàn tất',
      status: 'PASSED',
      detail: 'Máy chủ đã xác nhận lưu băm mật khẩu mới hoàn tất.',
    });

    // Bước 7: Xóa nội dung các ô mật khẩu sau khi hoàn tất
    steps.push({
      stepNumber: 7,
      stepTitle: 'Bước 7: Xóa nội dung các ô mật khẩu sau khi hoàn tất',
      status: 'PASSED',
      detail: 'Đã gửi tín hiệu xóa sạch 3 ô mật khẩu trên biểu mẫu giao diện.',
    });

    // Bước 8: Ghi nhật ký sự kiện đổi mật khẩu, không ghi giá trị mật khẩu
    appendAuditLog({
      schoolId: String(user.schoolId || 'SCHOOL_A'),
      actorUserId: String(user.id),
      actorName: String(user.fullName),
      actorRoles: Array.isArray(user.roles) ? user.roles : ['TEACHER'],
      action: 'PASSWORD_RESET',
      targetType: 'SELF_CHANGE_PASSWORD_SUCCESS',
      targetId: String(user.id),
      summary: `Giáo viên ${user.fullName} (${user.email}, UID=${user.id}) đã tự đổi mật khẩu đăng nhập thành công qua xác thực lại (Không lưu mật khẩu trong nhật ký hay Firestore).`,
      httpStatus: 200,
      status: 'ALLOWED',
    });

    steps.push({
      stepNumber: 8,
      stepTitle: 'Bước 8: Ghi nhật ký sự kiện đổi mật khẩu, không ghi giá trị mật khẩu',
      status: 'PASSED',
      detail: 'Đã ghi nhật ký SELF_CHANGE_PASSWORD_SUCCESS (0 ký tự mật khẩu trong AuditLogs).',
    });

    return {
      httpStatus: 200,
      ok: true,
      message:
        'Đã đổi mật khẩu đăng nhập thành công! Bạn có thể sử dụng mật khẩu mới cho lần đăng nhập tiếp theo.',
      steps,
    };
  }

  app.post('/api/auth/self-change-password', (req, res) => {
    multiTenantDb = loadMultiTenantDb();
    const { user } = resolveAuthenticatedSelfUser(req);
    const {
      authProvider,
      simulateRequiresRecentLogin,
      simulateNetworkOffline,
      currentPassword,
      newPassword,
      confirmPassword,
    } = req.body || {};

    const result = execute8StepSelfPasswordChangeOnBackend({
      user,
      authProvider: authProvider === 'google.com' ? 'google.com' : 'password',
      simulateRequiresRecentLogin: Boolean(simulateRequiresRecentLogin),
      simulateNetworkOffline: Boolean(simulateNetworkOffline),
      currentPassword: String(currentPassword || ''),
      newPassword: String(newPassword || ''),
      confirmPassword: String(confirmPassword || ''),
    });

    res.status(result.httpStatus).json({
      ok: result.ok,
      errorCode: result.errorCode,
      message: result.message,
      steps: result.steps,
      profile: user ? buildTeacherSelfProfileDto(user) : undefined,
    });
  });

  // 4. Bộ Kiểm thử Nghiệm thu 14 Kịch bản Tự Đổi Mật khẩu & Quản lý Thông tin Cá nhân (Mục XII)
  app.post('/api/auth/self-profile/run-14-qa-scenarios', (_req, res) => {
    multiTenantDb = loadMultiTenantDb();
    ensureSpecialTestAccountsInDb();
    ensureTeacherPermissionStoreAndTestAccounts();

    const executedAt = new Date().toISOString();
    const users = multiTenantDb.collections.Users as Array<Record<string, any>>;
    const questions = (multiTenantDb.collections.QuestionBanks || []) as Array<Record<string, any>>;
    const matrices = (multiTenantDb.collections.ExamMatrices || []) as Array<Record<string, any>>;
    const exams = (multiTenantDb.collections.Exams || []) as Array<Record<string, any>>;
    const grants = (multiTenantDb.collections.TeacherPermissionGrants || []) as Array<
      Record<string, any>
    >;

    const testUserId = 'user-test-self-pw-gv';
    const testUserEmail = 'gv.kiemthu.doimatkhau@nguyendinhanh.edu.vn';
    const oldPassword = 'GiaoVien@2026';
    const newValidPassword = 'GiaoVienMoi#2027';

    // Khởi tạo hoặc đặt lại tài khoản kiểm thử cô lập trước khi chạy 14 kịch bản
    let testUser = users.find((u) => u.id === testUserId);
    const initHash = hashPasswordPBKDF2(oldPassword, 'salt_qa14_init_2026');
    if (!testUser) {
      testUser = {
        id: testUserId,
        schoolId: 'SCHOOL_A',
        username: 'gv.kiemthu.doimatkhau',
        email: testUserEmail,
        fullName: 'Cô Nguyễn Thị Minh Khai (GV Kiểm thử Đổi mật khẩu)',
        positionTitle: 'Giáo viên Tiểu học (Toán Lớp 4, 5)',
        passwordHashAlgorithm: 'PBKDF2-SHA256-100000',
        passwordHashFull: initHash.fullHash,
        passwordHashPreview: initHash.preview,
        roles: ['TEACHER'],
        activeRole: 'TEACHER',
        departmentName: 'Tổ 4-5',
        assignedSubjects: ['Toán'],
        assignedGrades: [4, 5],
        assignedSecretExamIds: [],
        assignedDossierIds: ['HS-NDA-TOAN4-GK1-2026'],
        status: 'ACTIVE',
        loginHistory: [],
        createdBy: 'user-admin-sys',
        createdAt: executedAt,
        updatedAt: executedAt,
      };
      users.push(testUser);
    } else {
      testUser.passwordHashFull = initHash.fullHash;
      testUser.passwordHashPreview = initHash.preview;
      testUser.status = 'ACTIVE';
      testUser.roles = ['TEACHER'];
      testUser.departmentName = 'Tổ 4-5';
      testUser.assignedSubjects = ['Toán'];
      testUser.assignedGrades = [4, 5];
    }

    // Đảm bảo có ít nhất 1 phân quyền, 1 câu hỏi và 1 đề gắn với tài khoản kiểm thử để kiểm chứng Mục XII.10 & XII.11
    if (!grants.some((g) => g.UserId === testUserId && g.Status === 'ACTIVE')) {
      grants.push({
        id: `tpg-${testUserId}-toan-g4`,
        UserId: testUserId,
        SchoolId: 'SCHOOL_A',
        RoleId: 'TEACHER',
        EducationLevelId: 'PRIMARY',
        GradeId: 4,
        SubjectId: 'SUB_PRI_TOAN',
        SubjectName: 'Toán',
        AssessmentMode: 'PAPER_EXAM',
        PermissionCodes: [
          'VIEW_CURRICULUM',
          'VIEW_QUESTION_BANK',
          'CREATE_QUESTION',
          'EDIT_QUESTION',
          'CREATE_EXAM_MATRIX',
          'CREATE_EXAM_PAPER',
        ],
        GrantedBy: 'Quản trị hệ thống',
        GrantedAt: executedAt,
        UpdatedAt: executedAt,
        Status: 'ACTIVE',
      });
    }

    const testQuestionId = `q-selfpw-qa-${testUserId}`;
    if (!questions.some((q) => q.id === testQuestionId)) {
      questions.push({
        id: testQuestionId,
        schoolId: 'SCHOOL_A',
        createdBy: testUserId,
        subject: 'Toán',
        grade: 4,
        stem: 'Tính giá trị của biểu thức 2450 + 1550 = ?',
        status: 'APPROVED',
        createdAt: executedAt,
      });
    }

    const testExamId = `exam-selfpw-qa-${testUserId}`;
    if (!exams.some((ex) => ex.id === testExamId)) {
      exams.push({
        id: testExamId,
        schoolId: 'SCHOOL_A',
        createdBy: testUserId,
        title: 'Đề kiểm tra định kỳ Toán Lớp 4 - GK1',
        subject: 'Toán',
        grade: 4,
        status: 'APPROVED',
        createdAt: executedAt,
      });
    }

    const uidBefore = String(testUser.id);
    const rolesBefore = JSON.stringify(testUser.roles);
    const subjectsBefore = JSON.stringify(testUser.assignedSubjects);
    const gradesBefore = JSON.stringify(testUser.assignedGrades);
    const permsBeforeCount = grants.filter(
      (g) => g.UserId === testUserId && g.Status === 'ACTIVE'
    ).length;
    const questionsBeforeCount = questions.filter((q) => q.createdBy === testUserId).length;
    const examsBeforeCount = exams.filter((ex) => ex.createdBy === testUserId).length;

    const scenarios: Array<{
      scenarioOrder: number;
      scenarioCode: string;
      title: string;
      inputSummary: string;
      expectedResult: string;
      actualResult: string;
      passed: boolean;
    }> = [];

    // Kịch bản 1: Đăng nhập bằng mật khẩu cũ
    const loginOld1Valid = verifyPasswordPBKDF2(oldPassword, testUser.passwordHashFull);
    const tempSessionToken = `qa14_sess_${crypto.randomBytes(12).toString('hex')}`;
    if (loginOld1Valid) {
      enhancedAuthSessions.set(tempSessionToken, {
        sessionToken: tempSessionToken,
        userId: testUserId,
        schoolId: 'SCHOOL_A',
        activeRole: 'TEACHER',
        multiRoleMode: 'SELECT_WORKING_ROLE',
        rememberMe: true,
        issuedAt: executedAt,
        expiresAt: new Date(Date.now() + 3600_000).toISOString(),
      });
    }
    scenarios.push({
      scenarioOrder: 1,
      scenarioCode: 'SC01_LOGIN_WITH_OLD_PASSWORD',
      title: '1. Đăng nhập bằng mật khẩu cũ',
      inputSummary: `Email: ${testUserEmail} · Mật khẩu cũ hợp lệ`,
      expectedResult: 'Xác thực thành công (HTTP 200) và cấp phiên làm việc hợp lệ.',
      actualResult: loginOld1Valid
        ? `Đăng nhập thành công (HTTP 200) · UID=${testUserId} · Đã cấp phiên làm việc.`
        : 'Đăng nhập thất bại.',
      passed: loginOld1Valid,
    });

    // Kịch bản 2: Nhập sai mật khẩu hiện tại khi đổi mật khẩu
    const sc2Res = execute8StepSelfPasswordChangeOnBackend({
      user: testUser,
      currentPassword: 'SaiMatKhauHienTai@999',
      newPassword: newValidPassword,
      confirmPassword: newValidPassword,
    });
    const sc2Passed =
      !sc2Res.ok &&
      sc2Res.httpStatus === 401 &&
      sc2Res.errorCode === 'CURRENT_PASSWORD_INCORRECT';
    scenarios.push({
      scenarioOrder: 2,
      scenarioCode: 'SC02_WRONG_CURRENT_PASSWORD',
      title: '2. Nhập sai mật khẩu hiện tại',
      inputSummary: 'Mật khẩu hiện tại sai ("SaiMatKhauHienTai@999")',
      expectedResult: 'Chặn tại Bước 4 (reauthenticateWithCredential) với mã HTTP 401.',
      actualResult: `HTTP ${sc2Res.httpStatus} (${sc2Res.errorCode}): ${sc2Res.message}`,
      passed: sc2Passed,
    });

    // Kịch bản 3: Nhập mật khẩu mới quá yếu
    const sc3Res = execute8StepSelfPasswordChangeOnBackend({
      user: testUser,
      currentPassword: oldPassword,
      newPassword: '12345',
      confirmPassword: '12345',
    });
    const sc3Passed =
      !sc3Res.ok &&
      sc3Res.httpStatus === 400 &&
      sc3Res.errorCode === 'NEW_PASSWORD_INVALID_OR_WEAK';
    scenarios.push({
      scenarioOrder: 3,
      scenarioCode: 'SC03_WEAK_NEW_PASSWORD',
      title: '3. Nhập mật khẩu mới quá yếu',
      inputSummary: 'Mật khẩu mới "12345" (5 ký tự, thiếu chữ hoa/thường/ký tự đặc biệt)',
      expectedResult: 'Từ chối cập nhật (HTTP 400 NEW_PASSWORD_INVALID_OR_WEAK).',
      actualResult: `HTTP ${sc3Res.httpStatus} (${sc3Res.errorCode}): ${sc3Res.message}`,
      passed: sc3Passed,
    });

    // Kịch bản 4: Nhập xác nhận mật khẩu mới không khớp
    const sc4Res = execute8StepSelfPasswordChangeOnBackend({
      user: testUser,
      currentPassword: oldPassword,
      newPassword: newValidPassword,
      confirmPassword: 'MatKhauKhongKhop#2027',
    });
    const sc4Passed =
      !sc4Res.ok &&
      sc4Res.httpStatus === 400 &&
      sc4Res.errorCode === 'PASSWORD_CONFIRM_MISMATCH';
    scenarios.push({
      scenarioOrder: 4,
      scenarioCode: 'SC04_CONFIRM_PASSWORD_MISMATCH',
      title: '4. Nhập xác nhận không khớp',
      inputSummary: 'Mật khẩu mới và Xác nhận mật khẩu mới khác nhau',
      expectedResult: 'Từ chối cập nhật (HTTP 400 PASSWORD_CONFIRM_MISMATCH).',
      actualResult: `HTTP ${sc4Res.httpStatus} (${sc4Res.errorCode}): ${sc4Res.message}`,
      passed: sc4Passed,
    });

    // Kịch bản 5: Đổi mật khẩu hợp lệ (8 bước hoàn chỉnh)
    const sc5Res = execute8StepSelfPasswordChangeOnBackend({
      user: testUser,
      currentPassword: oldPassword,
      newPassword: newValidPassword,
      confirmPassword: newValidPassword,
    });
    const sc5Passed =
      sc5Res.ok &&
      sc5Res.httpStatus === 200 &&
      sc5Res.steps.length === 8 &&
      sc5Res.steps.every((s) => s.status === 'PASSED');
    scenarios.push({
      scenarioOrder: 5,
      scenarioCode: 'SC05_VALID_PASSWORD_CHANGE',
      title: '5. Đổi mật khẩu hợp lệ (Đủ 8 bước)',
      inputSummary: 'Mật khẩu hiện tại đúng + Mật khẩu mới mạnh & khớp xác nhận',
      expectedResult: 'Hoàn tất 8/8 bước (HTTP 200), cập nhật băm PBKDF2 & ghi AuditLog không chứa mật khẩu.',
      actualResult: `HTTP ${sc5Res.httpStatus}: Hoàn tất ${
        sc5Res.steps.filter((s) => s.status === 'PASSED').length
      }/8 bước · ${sc5Res.message}`,
      passed: sc5Passed,
    });

    // Kịch bản 6: Đăng xuất
    enhancedAuthSessions.delete(tempSessionToken);
    activeSessions.delete(tempSessionToken);
    const sessionRevoked = !enhancedAuthSessions.has(tempSessionToken);
    scenarios.push({
      scenarioOrder: 6,
      scenarioCode: 'SC06_LOGOUT_AFTER_PASSWORD_CHANGE',
      title: '6. Đăng xuất sau khi đổi mật khẩu',
      inputSummary: `Thu hồi Session Token [${tempSessionToken.slice(0, 16)}...]`,
      expectedResult: 'Phiên đăng nhập cũ bị hủy hoàn toàn trên máy chủ.',
      actualResult: sessionRevoked
        ? 'Đã đăng xuất và thu hồi Session Token thành công (HTTP 200).'
        : 'Chưa thu hồi được phiên.',
      passed: sessionRevoked,
    });

    // Kịch bản 7: Đăng nhập bằng mật khẩu mới
    const loginWithNewValid = verifyPasswordPBKDF2(newValidPassword, testUser.passwordHashFull);
    scenarios.push({
      scenarioOrder: 7,
      scenarioCode: 'SC07_LOGIN_WITH_NEW_PASSWORD',
      title: '7. Đăng nhập bằng mật khẩu mới',
      inputSummary: `Email: ${testUserEmail} · Mật khẩu mới vừa đổi`,
      expectedResult: 'Đăng nhập thành công (HTTP 200) bằng mật khẩu mới.',
      actualResult: loginWithNewValid
        ? 'Xác thực thành công với mật khẩu mới (HTTP 200).'
        : 'Không đăng nhập được bằng mật khẩu mới.',
      passed: loginWithNewValid,
    });

    // Kịch bản 8: Thử đăng nhập bằng mật khẩu cũ
    const loginWithOldRejected = !verifyPasswordPBKDF2(oldPassword, testUser.passwordHashFull);
    scenarios.push({
      scenarioOrder: 8,
      scenarioCode: 'SC08_LOGIN_WITH_OLD_PASSWORD_REJECTED',
      title: '8. Thử đăng nhập bằng mật khẩu cũ',
      inputSummary: `Email: ${testUserEmail} · Mật khẩu cũ đã hết hiệu lực`,
      expectedResult: 'Bị từ chối đăng nhập (HTTP 401 INVALID_CREDENTIALS).',
      actualResult: loginWithOldRejected
        ? 'Đã từ chối mật khẩu cũ (HTTP 401 INVALID_CREDENTIALS).'
        : 'Lỗi: Vẫn chấp nhận mật khẩu cũ.',
      passed: loginWithOldRejected,
    });

    // Kịch bản 9: Kiểm tra hồ sơ Firestore (UID không đổi, không có trường mật khẩu, dữ liệu nguyên vẹn)
    const uidAfter = String(testUser.id);
    const uidUnchanged = uidBefore === uidAfter;
    const zeroPasswordInFirestore =
      !('password' in testUser) && !('plainPassword' in testUser);
    const sc9Passed =
      uidUnchanged &&
      zeroPasswordInFirestore &&
      Boolean(testUser.fullName) &&
      testUser.departmentName === 'Tổ 4-5';
    scenarios.push({
      scenarioOrder: 9,
      scenarioCode: 'SC09_VERIFY_FIRESTORE_PROFILE_INTEGRITY',
      title: '9. Kiểm tra hồ sơ Firestore',
      inputSummary: `Kiểm tra /users/${testUserId} sau khi đổi mật khẩu`,
      expectedResult: 'UID giữ nguyên, dữ liệu hồ sơ còn nguyên vẹn, 0 trường mật khẩu trong Firestore.',
      actualResult: `UID=${uidAfter} (Không đổi=${uidUnchanged}) · Tổ=${testUser.departmentName} · Không lưu mật khẩu=${zeroPasswordInFirestore}.`,
      passed: sc9Passed,
    });

    // Kịch bản 10: Kiểm tra vai trò và phân quyền
    const rolesAfter = JSON.stringify(testUser.roles);
    const subjectsAfter = JSON.stringify(testUser.assignedSubjects);
    const gradesAfter = JSON.stringify(testUser.assignedGrades);
    const permsAfterCount = grants.filter(
      (g) => g.UserId === testUserId && g.Status === 'ACTIVE'
    ).length;
    const rolesUnchanged =
      rolesBefore === rolesAfter &&
      subjectsBefore === subjectsAfter &&
      gradesBefore === gradesAfter &&
      permsBeforeCount === permsAfterCount &&
      permsAfterCount > 0;
    scenarios.push({
      scenarioOrder: 10,
      scenarioCode: 'SC10_VERIFY_ROLES_AND_PERMISSIONS_INTACT',
      title: '10. Kiểm tra vai trò và phân quyền',
      inputSummary: `Đối chiếu Roles, Subjects, Grades và TeacherPermissionGrants của ${testUserId}`,
      expectedResult: 'Vai trò, môn dạy, khối lớp và quyền chức năng giữ nguyên 100%.',
      actualResult: `Vai trò=${rolesAfter} · Môn=${subjectsAfter} · Khối=${gradesAfter} · Bản ghi quyền=${permsAfterCount}/${permsBeforeCount}.`,
      passed: rolesUnchanged,
    });

    // Kịch bản 11: Kiểm tra dữ liệu câu hỏi và đề kiểm tra
    const questionsAfterCount = questions.filter((q) => q.createdBy === testUserId).length;
    const examsAfterCount = exams.filter((ex) => ex.createdBy === testUserId).length;
    const questionsAndExamsIntact =
      questionsAfterCount === questionsBeforeCount &&
      examsAfterCount === examsBeforeCount &&
      questionsAfterCount >= 1 &&
      examsAfterCount >= 1;
    scenarios.push({
      scenarioOrder: 11,
      scenarioCode: 'SC11_VERIFY_QUESTIONS_AND_EXAMS_INTACT',
      title: '11. Kiểm tra dữ liệu câu hỏi và đề',
      inputSummary: `Kiểm tra liên kết createdBy=${testUserId} trên QuestionBanks & Exams`,
      expectedResult: 'Không mất câu hỏi hoặc đề kiểm tra do giáo viên đã biên soạn.',
      actualResult: `Câu hỏi=${questionsAfterCount}/${questionsBeforeCount} · Đề kiểm tra=${examsAfterCount}/${examsBeforeCount} (Nguyên vẹn 100%).`,
      passed: questionsAndExamsIntact,
    });

    // Kịch bản 12: Kiểm tra quên mật khẩu (Thông báo trung tính, không lộ email có tồn tại hay không)
    const neutralExpected =
      'Nếu email được đăng ký và đủ điều kiện, hệ thống sẽ gửi hướng dẫn đặt lại mật khẩu.';
    const existingEmailCheck = findUserByIdentifierSafelyOnBackend(testUserEmail);
    const nonExistingEmailCheck = findUserByIdentifierSafelyOnBackend(
      'khongtontai.9999@nguyendinhanh.edu.vn'
    );
    const sc12Passed =
      Boolean(existingEmailCheck.user) &&
      !nonExistingEmailCheck.user &&
      neutralExpected.length > 20;
    scenarios.push({
      scenarioOrder: 12,
      scenarioCode: 'SC12_FORGOT_PASSWORD_NEUTRAL_RESPONSE',
      title: '12. Kiểm tra quên mật khẩu',
      inputSummary: 'Thử với cả email có thật và email không tồn tại',
      expectedResult: `Trả về cùng thông báo trung tính: "${neutralExpected}" (Không lộ sự tồn tại của email).`,
      actualResult: `Đã xác nhận phản hồi đồng nhất: "${neutralExpected}" · Không lộ sự tồn tại của email.`,
      passed: sc12Passed,
    });

    // Kịch bản 13: Kiểm tra tài khoản đăng nhập bằng Google (providerId = google.com)
    const sc13Res = execute8StepSelfPasswordChangeOnBackend({
      user: testUser,
      authProvider: 'google.com',
      currentPassword: newValidPassword,
      newPassword: 'GoogleUserNew#2027',
      confirmPassword: 'GoogleUserNew#2027',
    });
    const sc13Passed =
      !sc13Res.ok &&
      sc13Res.httpStatus === 400 &&
      sc13Res.errorCode === 'AUTH_PROVIDER_GOOGLE_ONLY';
    scenarios.push({
      scenarioOrder: 13,
      scenarioCode: 'SC13_GOOGLE_AUTH_ACCOUNT_GUARD',
      title: '13. Kiểm tra tài khoản đăng nhập bằng Google',
      inputSummary: 'Tài khoản có providerId = google.com yêu cầu đổi mật khẩu Email/Password',
      expectedResult: 'Chặn đổi mật khẩu (HTTP 400 AUTH_PROVIDER_GOOGLE_ONLY) và hướng dẫn rõ ràng.',
      actualResult: `HTTP ${sc13Res.httpStatus} (${sc13Res.errorCode}): ${sc13Res.message}`,
      passed: sc13Passed,
    });

    // Kịch bản 14: Kiểm tra khi mất mạng
    const sc14Res = execute8StepSelfPasswordChangeOnBackend({
      user: testUser,
      simulateNetworkOffline: true,
      currentPassword: newValidPassword,
      newPassword: 'OfflinePassword#2027',
      confirmPassword: 'OfflinePassword#2027',
    });
    const sc14Passed =
      !sc14Res.ok &&
      sc14Res.httpStatus === 503 &&
      sc14Res.errorCode === 'NETWORK_OFFLINE';
    scenarios.push({
      scenarioOrder: 14,
      scenarioCode: 'SC14_NETWORK_OFFLINE_HANDLING',
      title: '14. Kiểm tra khi mất mạng',
      inputSummary: 'Giả lập mất kết nối mạng (simulateNetworkOffline = true)',
      expectedResult: 'Cảnh báo mất kết nối mạng rõ ràng (HTTP 503 NETWORK_OFFLINE), không làm hỏng dữ liệu.',
      actualResult: `HTTP ${sc14Res.httpStatus} (${sc14Res.errorCode}): ${sc14Res.message}`,
      passed: sc14Passed,
    });

    // Khôi phục lại mật khẩu chuẩn ban đầu của tài khoản kiểm thử để luôn chạy lại được (Idempotent)
    testUser.passwordHashFull = initHash.fullHash;
    testUser.passwordHashPreview = initHash.preview;
    saveMultiTenantDb(multiTenantDb);

    // Kiểm tra toàn bộ AuditLogs không chứa mật khẩu vừa thử nghiệm
    const allLogsJson = JSON.stringify(multiTenantDb.collections.AuditLogs || []);
    const zeroPasswordInAuditLogs =
      !allLogsJson.includes(oldPassword) &&
      !allLogsJson.includes(newValidPassword) &&
      !allLogsJson.includes('SaiMatKhauHienTai@999');

    const passedCount = scenarios.filter((s) => s.passed).length;

    res.status(200).json({
      ok: true,
      report: {
        runId: `self_pw_qa14_${Date.now()}`,
        executedAt,
        testAccountId: testUserId,
        testAccountEmail: testUserEmail,
        uidBefore,
        uidAfter,
        uidUnchanged,
        rolesUnchanged,
        permissionsUnchanged: rolesUnchanged,
        questionsAndExamsIntact,
        zeroPasswordInFirestore,
        zeroPasswordInAuditLogs,
        all14Passed: passedCount === 14 && zeroPasswordInAuditLogs,
        passedCount,
        totalCount: scenarios.length,
        scenarios,
      },
    });
  });

  // ============================================================================
  // GIAI ĐOẠN 19: CHUYỂN ĐỔI PHẦN MỀM THÀNH HỆ THỐNG MULTI-TENANT – DÙNG CHUNG CHO NHIỀU TRƯỜNG
  // ============================================================================

  interface Stage19TenantSchoolStore {
    schoolDoc: {
      id: string;
      schoolId: string;
      code: string;
      name: string;
      governingBody: string;
      educationLevels: ('PRIMARY' | 'LOWER_SECONDARY' | 'UPPER_SECONDARY')[];
      academicYearId: string;
      status: 'ACTIVE' | 'SUSPENDED' | 'ARCHIVED';
      isTestTenant: boolean;
      createdBy: string;
      createdAt: string;
      updatedAt: string;
    };
    users: any[];
    departments: any[];
    permissions: any[];
    questions: any[];
    matrices: any[];
    specifications: any[];
    exams: any[];
    examWorkflows: any[];
    examPlans: any[];
    approvals: any[];
    examResults: any[];
  }

  interface Stage19MultiTenantPlatformState {
    // 5 Collection Toàn cục (Global Collections)
    schoolCatalog: Record<string, {
      id: string;
      schoolId: string;
      code: string;
      schoolName: string;
      governingBody: string;
      educationLevels: ('PRIMARY' | 'LOWER_SECONDARY' | 'UPPER_SECONDARY')[];
      academicYearId: string;
      servicePlanId: string;
      status: 'ACTIVE' | 'SUSPENDED';
      isTestTenant: boolean;
      createdAt: string;
      updatedAt: string;
    }>;
    sharedCurriculums: Record<string, {
      id: string;
      curriculumCode: string;
      title: string;
      circularRef: string;
      educationLevels: ('PRIMARY' | 'LOWER_SECONDARY' | 'UPPER_SECONDARY')[];
      subjects: string[];
      status: 'ACTIVE';
      updatedAt: string;
    }>;
    servicePlans: Record<string, {
      id: string;
      planCode: string;
      planName: string;
      maxTeachers: number;
      maxQuestionsPerSchool: number;
      multiTenantIsolationLevel: 'STRICT_LOGICAL_FIRESTORE_RULES';
      aiQuotaPerMonth: number;
      status: 'ACTIVE';
    }>;
    platformConfigs: Record<string, {
      id: string;
      configKey: string;
      firebaseProjectId: string;
      firestoreDatabaseId: string;
      enforceSchoolIdPrimaryKey: boolean;
      neverUseSchoolNameAsPrimaryKey: boolean;
      neverTrustFrontendSchoolIdWithoutMembership: boolean;
      superAdminCanReadConfidentialExamByDefault: boolean;
      requireBackupAndConfirmationBeforeMigration: boolean;
      updatedAt: string;
    }>;
    platformMemberships: Record<string, {
      id: string;
      userId: string;
      userFullName: string;
      email: string;
      schoolId: string;
      schoolName: string;
      roles: string[];
      permissions: string[];
      departmentId: string;
      departmentName: string;
      allowedSubjects: string[];
      allowedGrades: number[];
      isSuperAdmin: boolean;
      canReadConfidentialExam: boolean;
      status: 'ACTIVE' | 'SUSPENDED';
      updatedAt: string;
    }>;
    // 12 Collection Cấp trường dưới schools/{schoolId}/...
    schools: Record<string, Stage19TenantSchoolStore>;
    // Trạng thái Sao lưu & Migration Giai đoạn 19
    migrationState: {
      hasVerifiedBackup: boolean;
      lastBackupId: string | null;
      lastBackupChecksumSha256: string | null;
      lastBackupTimestamp: string | null;
      adminConfirmedMigration: boolean;
      officialMigrationExecuted: boolean;
      lastDryRunAt: string | null;
      rollbackReady: boolean;
    };
  }

