  function buildSchoolPickerCardsForAccount(account: MultiSchoolAuthAccount) {
    // Mục III & V: Mỗi trường chỉ hiển thị Logo, Tên trường, Cấp học, Vai trò của người dùng, Trạng thái.
    // Tuyệt đối KHÔNG hiển thị đề mật trong danh sách chọn trường.
    return account.memberships.map((m) => {
      const schoolInfo = MULTI_SCHOOL_DIRECTORY[m.schoolId];
      const isSelectable = m.membershipStatus === 'ACTIVE' && schoolInfo?.schoolStatus === 'ACTIVE';
      return {
        schoolId: m.schoolId,
        logoText: schoolInfo?.logoText || 'EDU',
        logoBgClass: schoolInfo?.logoBgClass || 'bg-slate-700',
        schoolName: schoolInfo?.schoolName || m.schoolId,
        educationLevels: schoolInfo?.educationLevels || ['PRIMARY'],
        educationLevelLabel: schoolInfo?.educationLevelLabel || 'Phổ thông',
        academicYearId: schoolInfo?.academicYearId || '2026-2027',
        userRoles: m.roles,
        userRoleLabel: m.roleDisplayLabel,
        departmentName: m.departmentName,
        membershipStatus: m.membershipStatus,
        schoolStatus: schoolInfo?.schoolStatus || 'SUSPENDED',
        statusDisplayLabel:
          m.membershipStatus !== 'ACTIVE'
            ? 'Đã thu hồi quyền thành viên'
            : schoolInfo?.schoolStatus !== 'ACTIVE'
            ? 'Trường đang tạm ngừng'
            : 'Đang hoạt động',
        isSelectable,
        allowedSubjects: m.allowedSubjects,
        allowedGrades: m.allowedGrades,
        permissions: m.permissions,
        menuSummary: m.menuSummary,
        confidentialExamsExposedInPicker: 0, // Mục V: Không hiển thị đề mật trong danh sách chọn trường
      };
    });
  }

  function resolveMultiSchoolLogin(params: {
    emailOrScenarioKey: string;
    password?: string;
    untrustedUrlSchoolId?: string;
  }) {
    const query = params.emailOrScenarioKey.trim().toLowerCase();
    const account = MULTI_SCHOOL_AUTH_TEST_ACCOUNTS.find(
      (a) => a.email.toLowerCase() === query || a.scenarioKey.toLowerCase() === query || a.uid.toLowerCase() === query
    );

    if (!account) {
      return {
        ok: false,
        httpStatus: 401,
        errorCode: 'INVALID_CREDENTIALS',
        message: 'Email đăng nhập hoặc mật khẩu không chính xác.',
      };
    }

    const cards = buildSchoolPickerCardsForAccount(account);
    const activeSelectableCards = cards.filter((c) => c.isSelectable);

    // Mục V: Không tin tưởng schoolId từ URL nếu người dùng không có membership ACTIVE tại trường đó
    let urlSpoofWarning: string | null = null;
    if (params.untrustedUrlSchoolId) {
      const validUrlTarget = activeSelectableCards.find(
        (c) => c.schoolId === params.untrustedUrlSchoolId
      );
      if (!validUrlTarget) {
        urlSpoofWarning = `Đã chặn tham số URL ?schoolId=${params.untrustedUrlSchoolId} do tài khoản "${account.email}" không có membership ACTIVE tại trường này (Mục V).`;
      }
    }

    // Trường hợp 1: Không thuộc trường nào (hoặc tất cả membership đều không hợp lệ)
    if (cards.length === 0 || activeSelectableCards.length === 0) {
      return {
        ok: true,
        httpStatus: 200,
        resolution: 'NO_VALID_SCHOOL_MEMBERSHIP' as const,
        message:
          'Tài khoản đã xác thực Firebase UID thành công nhưng chưa được phân quyền sử dụng tại bất kỳ trường học nào đang hoạt động.',
        urlSpoofWarning,
        user: {
          uid: account.uid,
          email: account.email,
          fullName: account.fullName,
          scenarioKey: account.scenarioKey,
        },
        schoolCards: cards,
        activeSchoolContext: null,
      };
    }

    // Trường hợp 2: Chỉ có đúng 1 membership trong danh sách và membership đó ACTIVE -> Tự động vào thẳng trường đó
    if (cards.length === 1 && activeSelectableCards.length === 1) {
      const targetCard = activeSelectableCards[0];
      const schoolInfo = MULTI_SCHOOL_DIRECTORY[targetCard.schoolId];
      return {
        ok: true,
        httpStatus: 200,
        resolution: 'AUTO_ENTER_SINGLE_SCHOOL' as const,
        message: `Tài khoản thuộc một trường duy nhất ("${targetCard.schoolName}"). Hệ thống tự động mở không gian làm việc của trường.`,
        urlSpoofWarning,
        user: {
          uid: account.uid,
          email: account.email,
          fullName: account.fullName,
          scenarioKey: account.scenarioKey,
        },
        schoolCards: cards,
        activeSchoolContext: {
          schoolId: targetCard.schoolId,
          schoolName: targetCard.schoolName,
          logoText: targetCard.logoText,
          educationLevels: targetCard.educationLevels,
          educationLevelLabel: targetCard.educationLevelLabel,
          academicYearId: targetCard.academicYearId,
          activeRole: targetCard.userRoles[0],
          userRoles: targetCard.userRoles,
          userRoleLabel: targetCard.userRoleLabel,
          departmentName: targetCard.departmentName,
          allowedSubjects: targetCard.allowedSubjects,
          allowedGrades: targetCard.allowedGrades,
          permissions: targetCard.permissions,
          menuSummary: targetCard.menuSummary,
          scopedQuestions: schoolInfo?.sampleQuestions || [],
          scopedVisibleExams: (schoolInfo?.sampleExams || []).filter((e) => !e.isConfidential),
        },
      };
    }

    // Trường hợp 3: Có từ 2 bản ghi membership trở lên -> Hiển thị Màn hình chọn trường để người dùng thấy rõ trạng thái từng trường và chọn trường hợp lệ
    return {
      ok: true,
      httpStatus: 200,
      resolution: 'REQUIRE_SCHOOL_SELECTION' as const,
      message: `Tài khoản có liên kết với ${cards.length} trường học (${activeSelectableCards.length} trường đang hoạt động). Vui lòng chọn trường làm việc.`,
      urlSpoofWarning,
      user: {
        uid: account.uid,
        email: account.email,
        fullName: account.fullName,
        scenarioKey: account.scenarioKey,
      },
      schoolCards: cards,
      activeSchoolContext: null,
    };
  }

  function executeBackendSchoolSelectionOrSwitch(params: {
    uidOrEmail: string;
    targetSchoolId: string;
    previousSchoolId?: string;
    unsavedChangesChecked?: boolean;
  }) {
    const query = params.uidOrEmail.trim().toLowerCase();
    const account = MULTI_SCHOOL_AUTH_TEST_ACCOUNTS.find(
      (a) =>
        a.uid.toLowerCase() === query ||
        a.email.toLowerCase() === query ||
        a.scenarioKey.toLowerCase() === query
    );

    if (!account) {
      return {
        ok: false,
        httpStatus: 401,
        errorCode: 'UNAUTHENTICATED_USER',
        message: 'Phiên đăng nhập không hợp lệ.',
      };
    }

    const membership = account.memberships.find((m) => m.schoolId === params.targetSchoolId);
    if (!membership) {
      return {
        ok: false,
        httpStatus: 403,
        errorCode: 'MEMBERSHIP_NOT_FOUND',
        message: `Từ chối truy cập (Mục V): Tài khoản "${account.fullName}" không phải là thành viên của trường "${params.targetSchoolId}".`,
      };
    }

    if (membership.membershipStatus !== 'ACTIVE') {
      return {
        ok: false,
        httpStatus: 403,
        errorCode: 'MEMBERSHIP_REVOKED_OR_SUSPENDED',
        message: `Từ chối truy cập (Mục V): Tư cách thành viên của "${account.fullName}" tại trường "${params.targetSchoolId}" đã bị thu hồi (${membership.membershipStatus}).`,
      };
    }

    const schoolInfo = MULTI_SCHOOL_DIRECTORY[params.targetSchoolId];
    if (!schoolInfo || schoolInfo.schoolStatus !== 'ACTIVE') {
      return {
        ok: false,
        httpStatus: 403,
        errorCode: 'SCHOOL_NOT_ACTIVE',
        message: `Từ chối truy cập: Trường "${params.targetSchoolId}" hiện không ở trạng thái hoạt động.`,
      };
    }

    const transitionSteps7 = [
      `1. Kiểm tra nội dung chưa lưu: ${params.unsavedChangesChecked !== false ? 'Đã kiểm tra an toàn' : 'Cảnh báo'}`,
      `2. Xác nhận chuyển trường: Người dùng đã xác nhận chuyển sang "${schoolInfo.schoolName}".`,
      `3. Hủy subscription dữ liệu trường cũ (${params.previousSchoolId || 'none'}): Đã ngắt toàn bộ listener cũ.`,
      `4. Xóa dữ liệu trường cũ khỏi state hiển thị: Đã làm sạch bộ nhớ hiển thị (0 bản ghi trường cũ còn tồn tại).`,
      `5. Tải quyền trường mới (${schoolInfo.schoolId}): Vai trò [${membership.roleDisplayLabel}] · Môn [${membership.allowedSubjects.join(', ')}] · Khối [${membership.allowedGrades.join(', ')}].`,
      `6. Tải dữ liệu trường mới: Đã nạp ${(schoolInfo.sampleQuestions || []).length} câu hỏi mẫu của "${schoolInfo.schoolName}".`,
      `7. Cập nhật menu theo trường mới: Đã nạp ${membership.menuSummary.length} mục menu độc lập (Không tự chuyển quyền giữa hai trường).`,
    ];

    return {
      ok: true,
      httpStatus: 200,
      message: `Đã vào không gian làm việc của "${schoolInfo.schoolName}" với vai trò "${membership.roleDisplayLabel}".`,
      transitionSteps7,
      activeSchoolContext: {
        schoolId: schoolInfo.schoolId,
        schoolName: schoolInfo.schoolName,
        logoText: schoolInfo.logoText,
        educationLevels: schoolInfo.educationLevels,
        educationLevelLabel: schoolInfo.educationLevelLabel,
        academicYearId: schoolInfo.academicYearId,
        activeRole: membership.roles[0],
        userRoles: membership.roles,
        userRoleLabel: membership.roleDisplayLabel,
        departmentName: membership.departmentName,
        allowedSubjects: membership.allowedSubjects,
        allowedGrades: membership.allowedGrades,
        permissions: membership.permissions,
        menuSummary: membership.menuSummary,
        scopedQuestions: schoolInfo.sampleQuestions,
        scopedVisibleExams: schoolInfo.sampleExams.filter((e) => !e.isConfidential),
      },
    };
  }

  app.get('/api/multi-school-auth/accounts', (_req, res) => {
    res.status(200).json({
      ok: true,
      accounts: MULTI_SCHOOL_AUTH_TEST_ACCOUNTS.map((a) => ({
        scenarioKey: a.scenarioKey,
        uid: a.uid,
        email: a.email,
        passwordPlainForDemo: a.passwordPlainForDemo,
        fullName: a.fullName,
        scenarioTitle: a.scenarioTitle,
        membershipsCount: a.memberships.length,
        activeMembershipsCount: a.memberships.filter((m) => m.membershipStatus === 'ACTIVE').length,
      })),
    });
  });

  app.post('/api/multi-school-auth/login', (req, res) => {
    const emailOrScenarioKey = String(req.body?.emailOrScenarioKey || req.body?.email || '').trim();
    const password = String(req.body?.password || '').trim();
    const untrustedUrlSchoolId = req.body?.untrustedUrlSchoolId
      ? String(req.body.untrustedUrlSchoolId).trim()
      : undefined;

    const result = resolveMultiSchoolLogin({
      emailOrScenarioKey,
      password,
      untrustedUrlSchoolId,
    });

    res.status(result.httpStatus).json(result);
  });

  app.post('/api/multi-school-auth/select-or-switch-school', (req, res) => {
    const uidOrEmail = String(req.body?.uidOrEmail || '').trim();
    const targetSchoolId = String(req.body?.targetSchoolId || '').trim();
    const previousSchoolId = req.body?.previousSchoolId
      ? String(req.body.previousSchoolId).trim()
      : undefined;
    const unsavedChangesChecked = req.body?.unsavedChangesChecked !== false;

    const result = executeBackendSchoolSelectionOrSwitch({
      uidOrEmail,
      targetSchoolId,
      previousSchoolId,
      unsavedChangesChecked,
    });

    res.status(result.httpStatus).json(result);
  });

  app.post('/api/multi-school-auth/run-verification-suite', (_req, res) => {
    const executedAt = new Date().toISOString();

    // Kịch bản 1: Giáo viên chỉ thuộc Trường A -> Tự động vào thẳng Trường A
    const t1 = resolveMultiSchoolLogin({
      emailOrScenarioKey: 'gv.truonga@edutest.edu.vn',
    });
    const t1Passed =
      t1.ok &&
      t1.resolution === 'AUTO_ENTER_SINGLE_SCHOOL' &&
      t1.activeSchoolContext?.schoolId === 'sch-tieu-hoc-a';

    // Kịch bản 2: Giáo viên thuộc Trường A và Trường B -> Mở màn hình chọn trường -> Chọn A -> Chuyển sang B
    const t2Login = resolveMultiSchoolLogin({
      emailOrScenarioKey: 'gv.ab@edutest.edu.vn',
    });
    const t2SelectA = executeBackendSchoolSelectionOrSwitch({
      uidOrEmail: 'gv.ab@edutest.edu.vn',
      targetSchoolId: 'sch-tieu-hoc-a',
    });
    const t2SwitchToB = executeBackendSchoolSelectionOrSwitch({
      uidOrEmail: 'gv.ab@edutest.edu.vn',
      previousSchoolId: 'sch-tieu-hoc-a',
      targetSchoolId: 'sch-thcs-b',
      unsavedChangesChecked: true,
    });
    const t2NoPermissionCarryOver =
      t2SelectA.activeSchoolContext?.permissions.includes('APPRAISE_DEPARTMENT_EXAM') === true &&
      t2SwitchToB.activeSchoolContext?.permissions.includes('APPRAISE_DEPARTMENT_EXAM') === false &&
      t2SwitchToB.activeSchoolContext?.allowedSubjects[0] === 'Khoa học tự nhiên' &&
      t2SwitchToB.activeSchoolContext?.scopedQuestions.every((q) => q.id.startsWith('q-thcsb-'));
    const t2Passed =
      t2Login.ok &&
      t2Login.resolution === 'REQUIRE_SCHOOL_SELECTION' &&
      t2SelectA.ok &&
      t2SwitchToB.ok &&
      Boolean(t2NoPermissionCarryOver);

    // Kịch bản 3: Giáo viên bị thu hồi quyền tại Trường B -> Cố tình chọn Trường B bị Backend từ chối 403
    const t3Login = resolveMultiSchoolLogin({
      emailOrScenarioKey: 'gv.revoked.b@edutest.edu.vn',
    });
    const t3TrySelectRevokedB = executeBackendSchoolSelectionOrSwitch({
      uidOrEmail: 'gv.revoked.b@edutest.edu.vn',
      targetSchoolId: 'sch-thcs-b',
    });
    const t3SelectValidA = executeBackendSchoolSelectionOrSwitch({
      uidOrEmail: 'gv.revoked.b@edutest.edu.vn',
      targetSchoolId: 'sch-tieu-hoc-a',
    });
    const t3Passed =
      t3Login.ok &&
      !t3TrySelectRevokedB.ok &&
      t3TrySelectRevokedB.httpStatus === 403 &&
      t3TrySelectRevokedB.errorCode === 'MEMBERSHIP_REVOKED_OR_SUSPENDED' &&
      t3SelectValidA.ok;

    // Kịch bản 4: Tài khoản chưa thuộc trường nào -> Thông báo chưa được phân quyền sử dụng
    const t4 = resolveMultiSchoolLogin({
      emailOrScenarioKey: 'gv.noschool@edutest.edu.vn',
    });
    const t4Passed =
      t4.ok &&
      t4.resolution === 'NO_VALID_SCHOOL_MEMBERSHIP' &&
      t4.activeSchoolContext === null;

    // Kịch bản 5: Bảo mật URL schoolId giả mạo & Không lộ đề mật ở màn hình chọn trường
    const t5SpoofUrl = resolveMultiSchoolLogin({
      emailOrScenarioKey: 'gv.truonga@edutest.edu.vn',
      untrustedUrlSchoolId: 'sch-thcs-b',
    });
    const t5TrySwitchForeign = executeBackendSchoolSelectionOrSwitch({
      uidOrEmail: 'gv.truonga@edutest.edu.vn',
      targetSchoolId: 'sch-thcs-b',
    });
    const noSecretExamInPicker = (t2Login.schoolCards || []).every(
      (c) => c.confidentialExamsExposedInPicker === 0
    );
    const t5Passed =
      Boolean(t5SpoofUrl.urlSpoofWarning) &&
      !t5TrySwitchForeign.ok &&
      t5TrySwitchForeign.httpStatus === 403 &&
      noSecretExamInPicker;

    const testCases = [
      {
        order: 1,
        code: 'MS-AUTH-01',
        title: '1. Giáo viên chỉ thuộc Trường A (gv.truonga@edutest.edu.vn)',
        account: 'Cô Phạm Thu Hà (uid_ms_auth_teacher_a)',
        expected: 'Xác thực UID -> Phát hiện đúng 1 trường ACTIVE -> Tự động mở thẳng Trường A (sch-tieu-hoc-a)',
        actual: `${t1.resolution} · Tự động vào "${t1.activeSchoolContext?.schoolName}" với vai trò "${t1.activeSchoolContext?.userRoleLabel}"`,
        passed: t1Passed,
      },
      {
        order: 2,
        code: 'MS-AUTH-02',
        title: '2. Giáo viên thuộc Trường A và Trường B (gv.ab@edutest.edu.vn) & Chuyển trường 7 bước',
        account: 'Cô Lê Thị Lan Hương (uid_ms_auth_teacher_ab)',
        expected:
          'Hiển thị màn hình chọn trường (2 trường) -> Chọn Trường A (Tổ trưởng CM, Toán 5, 7 menu) -> Chuyển sang Trường B (GV, KHTN 6, 4 menu, xóa sạch câu hỏi Trường A, không tự chuyển quyền)',
        actual: `Mở màn hình chọn trường (${t2Login.schoolCards?.length} trường). Tại Trường A: ${t2SelectA.activeSchoolContext?.userRoleLabel} (${t2SelectA.activeSchoolContext?.menuSummary.length} menu). Sau khi chuyển sang Trường B: ${t2SwitchToB.activeSchoolContext?.userRoleLabel} (${t2SwitchToB.activeSchoolContext?.menuSummary.length} menu, 0 dữ liệu cũ Trường A).`,
        passed: t2Passed,
      },
      {
        order: 3,
        code: 'MS-AUTH-03',
        title: '3. Giáo viên bị thu hồi quyền tại Trường B (gv.revoked.b@edutest.edu.vn)',
        account: 'Thầy Ngô Văn Bình (uid_ms_auth_revoked_b)',
        expected:
          'Được vào Trường A (ACTIVE); khi chọn hoặc gửi request vào Trường B (REVOKED) bị Backend chặn 403 PERMISSION_DENIED',
        actual: `Vào Trường A: ALLOW (200) · Chọn Trường B (REVOKED): DENY (HTTP ${t3TrySelectRevokedB.httpStatus} · ${t3TrySelectRevokedB.errorCode})`,
        passed: t3Passed,
      },
      {
        order: 4,
        code: 'MS-AUTH-04',
        title: '4. Tài khoản chưa thuộc trường nào (gv.noschool@edutest.edu.vn)',
        account: 'Cô Trần Mai Anh (uid_ms_auth_no_school)',
        expected:
          'Xác thực Firebase UID thành công nhưng không có membership -> Hiển thị thông báo chưa được phân quyền sử dụng',
        actual: `${t4.resolution}: "${t4.message}"`,
        passed: t4Passed,
      },
      {
        order: 5,
        code: 'MS-AUTH-05',
        title: '5. Bảo mật: Chặn giả mạo schoolId từ URL & Không hiển thị đề mật ở màn hình chọn trường',
        account: 'Cô Phạm Thu Hà (?schoolId=sch-thcs-b)',
        expected:
          'Phớt lờ/cảnh báo schoolId giả mạo trên URL; chặn 403 khi gọi API chọn trường không có membership; 0 đề mật xuất hiện trên thẻ chọn trường',
        actual: `${t5SpoofUrl.urlSpoofWarning} · API chọn trường lạ: HTTP ${t5TrySwitchForeign.httpStatus} (${t5TrySwitchForeign.errorCode}) · Đề mật lộ trên thẻ trường: 0`,
        passed: t5Passed,
      },
    ];

    res.status(200).json({
      ok: true,
      report: {
        executedAt,
        totalCount: testCases.length,
        passedCount: testCases.filter((tc) => tc.passed).length,
        allPassed: testCases.every((tc) => tc.passed),
        testCases,
      },
    });
  });

  // ============================================================================
  // MODULE "CẤU HÌNH TRƯỜNG HỌC" DÀNH CHO SCHOOL ADMIN (MỤC I -> VI)
  // ============================================================================
  interface SchoolSpecificConfiguration {
    schoolId: string;
    firestorePath: string;
    version: number;
    updatedAt: string;
    updatedBy: string;

    // I. THÔNG TIN TRƯỜNG
    schoolInfo: {
      schoolName: string;
      governingBody: string;
      address: string;
      logoUrl: string;
      contactEmail: string;
      phoneNumber: string;
      website: string;
      educationLevels: ('PRIMARY' | 'LOWER_SECONDARY')[];
      academicYear: string;
    };

    // II. CẤU HÌNH CHUYÊN MÔN
    academicConfig: {
      grades: number[];
      subjects: string[];
      departments: { id: string; name: string; gradesManaged: number[] }[];
      matrixTemplateCode: string;
      specificationTemplateCode: string;
      examPaperTemplateCode: string;
      appraisalWorkflowRule: 'MANDATORY_DEPARTMENT_REVIEW' | 'DUAL_PEER_AND_HOD_REVIEW';
      approvalWorkflowRule: 'MANDATORY_PRINCIPAL_APPROVAL' | 'VICE_AND_PRINCIPAL_TWO_STEP';
      dossierExportRule: 'REQUIRE_APPROVED_STATUS_AND_FULL_4_PARTS';
    };

    // III. CẤU HÌNH HỒ SƠ
    dossierFormatConfig: {
      dossierLogoUrl: string;
      examHeaderTitle: string;
      examPeriodNames: string[];
      wordExportFormat: 'DOCX_GDPT2018_STANDARD' | 'DOCX_TWO_COLUMN_COMPACT';
      paperSize: 'A4' | 'LETTER';
      fontFamily: 'Times New Roman' | 'Arial';
      fontSizePt: 13 | 14;
      signatureLayout: {
        leftSignerTitle: string;
        centerSignerTitle: string;
        rightSignerTitle: string;
      };
    };

    // IV. CẤU HÌNH AI (Không hiển thị API Key cho School Admin)
    aiGovernanceConfig: {
      aiAllowedSubjects: string[];
      aiAllowedRoles: ('TEACHER' | 'HEAD_OF_DEPARTMENT' | 'VICE_PRINCIPAL' | 'PRINCIPAL')[];
      aiDailyQuotaPerTeacher: number;
      approvedPromptTemplates: { id: string; code: string; title: string; levelScope: string }[];
      apiKeyManagedByPlatformServer: boolean;
    };
  }

  function normalizeConfigSchoolId(rawSchoolId: string): string {
    const trimmed = String(rawSchoolId || '').trim();
    if (trimmed === 'SCHOOL_B' || trimmed === 'sch-tieu-hoc-a') return 'sch-tieu-hoc-a';
    if (trimmed === 'SCHOOL_C' || trimmed === 'sch-thcs-b') return 'sch-thcs-b';
    if (
      trimmed === 'SCHOOL_A' ||
      trimmed === 'SCH-DAN-DIEN-NDA' ||
      trimmed === 'sch-th-thcs-nguyen-du'
    ) {
      return 'sch-th-thcs-nguyen-du';
    }
    return trimmed || 'sch-th-thcs-nguyen-du';
  }

