  function sanitizeConfidentialExamForAiLog(rawPromptOrTopic: string, subject = 'Toán', grade = 5): {
    sanitizedPromptSummary: string;
    confidentialExamContentRedacted: boolean;
    containsFullConfidentialExamContent: false;
    contentSha256Fingerprint: string;
  } {
    const raw = String(rawPromptOrTopic || '').trim();
    const digest = crypto
      .createHash('sha256')
      .update(raw || `${subject}-${grade}`)
      .digest('hex')
      .slice(0, 16);
    // Luôn cắt bỏ nội dung câu hỏi chi tiết / đáp án đề mật, chỉ giữ chủ đề khái quát <= 90 ký tự
    const stripped = raw
      .replace(/Câu\s*\d+[\s\S]*/gi, '[ĐÃ_ẨN_NỘI_DUNG_CÂU_HỎI_ĐỀ_MẬT]')
      .replace(/Đáp\s*án[\s\S]*/gi, '[ĐÃ_ẨN_ĐÁP_ÁN_MẬT]')
      .slice(0, 88);
    return {
      sanitizedPromptSummary: `[REDACTED_EXAM_BODY] Môn ${subject} Khối ${grade} · ${stripped || 'Tác vụ chuyên môn'} (SHA256:${digest})`,
      confidentialExamContentRedacted: true,
      containsFullConfidentialExamContent: false,
      contentSha256Fingerprint: digest,
    };
  }

  function calculateEstimatedCostUsd(
    modelId: GeminiSupportedModelId,
    inputTokens: number,
    outputTokens: number
  ): number {
    const spec = AI_MODEL_PRICING_CATALOG[modelId] || AI_MODEL_PRICING_CATALOG['gemini-3.8-flash'];
    const cost =
      (Math.max(0, inputTokens) / 1_000_000) * spec.inputCostPer1MUsd +
      (Math.max(0, outputTokens) / 1_000_000) * spec.outputCostPer1MUsd;
    return Number(cost.toFixed(6));
  }

