  let isRunningIsolatedAiQaSuite = false;

  function ensureCounterCycleFresh(counter: SchoolAiUsageRuntimeCounter): SchoolAiUsageRuntimeCounter {
    const now = new Date();
    const todayKey = now.toISOString().slice(0, 10);
    const monthKey = now.toISOString().slice(0, 7);
    if (counter.currentDayKey !== todayKey) {
      counter.currentDayKey = todayKey;
      counter.usedDailyRequests = 0;
      counter.perUserDailyUsed = {};
      counter.recentWindowRequestsCount = 0;
    }
    if (counter.currentMonthKey !== monthKey) {
      counter.currentMonthKey = monthKey;
      counter.usedMonthlyRequests = 0;
      counter.usedMonthlyInputTokens = 0;
      counter.usedMonthlyOutputTokens = 0;
      counter.usedMonthlyTotalTokens = 0;
      counter.usedMonthlyCostUsd = 0;
      counter.perUserMonthlyUsed = {};
      counter.perFunctionMonthlyUsed = {
        AI_QUESTION_GENERATOR: 0,
        AI_QUALITY_REVIEW: 0,
        AI_SMART_EXAM_IMPORT: 0,
        AI_MATRIX_SUGGESTION: 0,
      };
    }
    return counter;
  }

  function persistOfficialAiOperationalStore() {
    if (isRunningIsolatedAiQaSuite) return;
    multiTenantDb = loadMultiTenantDb();
    if (!multiTenantDb.collections) {
      (multiTenantDb as any).collections = {};
    }
    const cleanPolicies: Record<string, SchoolAiQuotaPolicy> = {};
    Object.entries(aiSchoolQuotaPoliciesStore).forEach(([k, v]) => {
      if (!DEMO_AI_SCHOOL_IDS.has(k) && v) {
        cleanPolicies[k] = v;
      }
    });
    const cleanCounters: Record<string, SchoolAiUsageRuntimeCounter> = {};
    Object.entries(aiSchoolUsageCountersStore).forEach(([k, v]) => {
      if (!DEMO_AI_SCHOOL_IDS.has(k) && v) {
        cleanCounters[k] = { ...v, inFlightReservedRequests: 0 };
      }
    });
    const cleanLogs = aiUsageTelemetryLogsStore
      .filter(
        (l) =>
          l &&
          !DEMO_AI_SCHOOL_IDS.has(l.schoolId) &&
          !String(l.userId || '').startsWith('uid_gv_')
      )
      .slice(0, 300);
    const cleanAlerts = aiUsageAlertsStore
      .filter((a) => a && !DEMO_AI_SCHOOL_IDS.has(a.schoolId))
      .slice(0, 100);

    (multiTenantDb.collections as any).OfficialAiOperationalState = {
      updatedAt: new Date().toISOString(),
      policies: cleanPolicies,
      counters: cleanCounters,
      logs: cleanLogs,
      alerts: cleanAlerts,
    };
    saveMultiTenantDb(multiTenantDb);
  }

  function syncOfficialSchoolsAiOperationalStore() {
    if (isRunningIsolatedAiQaSuite) return;
    multiTenantDb = loadMultiTenantDb();
    ensureSpecialTestAccountsInDb();
    const registry = ensureSuperAdminSchoolRegistry();
    const persisted = ((multiTenantDb.collections as any)?.OfficialAiOperationalState || {}) as {
      policies?: Record<string, SchoolAiQuotaPolicy>;
      counters?: Record<string, SchoolAiUsageRuntimeCounter>;
      logs?: AiUsageTelemetryLogEntry[];
      alerts?: AiUsageAlertItem[];
    };

    const nextPolicies: Record<string, SchoolAiQuotaPolicy> = {};
    const nextCounters: Record<string, SchoolAiUsageRuntimeCounter> = {};

    for (const rec of Object.values(registry.records)) {
      const canonicalId = normalizeOfficialAiSchoolId(rec.schoolId);
      if (DEMO_AI_SCHOOL_IDS.has(canonicalId)) continue;
      const defaultPolicy = buildDefaultOfficialSchoolQuotaPolicy({
        schoolId: canonicalId,
        schoolName: rec.schoolName,
        schoolType: rec.schoolType,
        servicePlanId: rec.servicePlanId,
      });
      const existingPolicy =
        aiSchoolQuotaPoliciesStore[canonicalId] || persisted.policies?.[canonicalId];
      nextPolicies[canonicalId] = existingPolicy
        ? {
            ...defaultPolicy,
            ...existingPolicy,
            schoolId: canonicalId,
            schoolName: rec.schoolName || existingPolicy.schoolName,
            educationLevelLabel: defaultPolicy.educationLevelLabel,
            firestorePath: `/schools/${canonicalId}/aiQuotaConfig/main`,
          }
        : defaultPolicy;

      const existingCounter =
        aiSchoolUsageCountersStore[canonicalId] || persisted.counters?.[canonicalId];
      nextCounters[canonicalId] = ensureCounterCycleFresh(
        existingCounter
          ? {
              ...createEmptyUsageCounter(canonicalId),
              ...existingCounter,
              schoolId: canonicalId,
            }
          : createEmptyUsageCounter(canonicalId)
      );
    }

    aiSchoolQuotaPoliciesStore = nextPolicies;
    aiSchoolUsageCountersStore = nextCounters;

    const baseLogs =
      aiUsageTelemetryLogsStore.length > 0 ? aiUsageTelemetryLogsStore : persisted.logs || [];
    aiUsageTelemetryLogsStore = baseLogs.filter(
      (l) =>
        l &&
        Boolean(nextPolicies[l.schoolId]) &&
        !DEMO_AI_SCHOOL_IDS.has(l.schoolId) &&
        !String(l.userId || '').startsWith('uid_gv_')
    );

    const baseAlerts =
      aiUsageAlertsStore.length > 0 ? aiUsageAlertsStore : persisted.alerts || [];
    aiUsageAlertsStore = baseAlerts.filter(
      (a) => a && Boolean(nextPolicies[a.schoolId]) && !DEMO_AI_SCHOOL_IDS.has(a.schoolId)
    );
  }

  // Khởi tạo đồng bộ ngay khi máy chủ khởi động
  syncOfficialSchoolsAiOperationalStore();

  // Khóa nguyên tử (Per-School Async Mutex Queue) để xử lý đồng thời (Mục IV)
  const schoolQuotaMutexQueues: Record<string, Promise<void>> = {};

  async function runWithSchoolQuotaMutex<T>(schoolId: string, task: () => Promise<T>): Promise<T> {
    const previous = schoolQuotaMutexQueues[schoolId] || Promise.resolve();
    let releaseLock!: () => void;
    const currentLock = new Promise<void>((resolve) => {
      releaseLock = resolve;
    });
    schoolQuotaMutexQueues[schoolId] = previous.then(() => currentLock);
    await previous;
    try {
      return await task();
    } finally {
      releaseLock();
    }
  }

  function pushOrUpdateSchoolAlert(
    schoolId: string,
    alertType: AiUsageAlertItem['alertType'],
    severity: AiUsageAlertItem['severity'],
    title: string,
    message: string,
    metricSnapshot: string
  ) {
    const policy = aiSchoolQuotaPoliciesStore[schoolId];
    const schoolName = policy?.schoolName || schoolId;
    const existingIdx = aiUsageAlertsStore.findIndex(
      (a) => a.schoolId === schoolId && a.alertType === alertType && !a.resolved
    );
    const entry: AiUsageAlertItem = {
      alertId:
        existingIdx >= 0
          ? aiUsageAlertsStore[existingIdx].alertId
          : `alrt-${schoolId}-${alertType.toLowerCase()}-${Date.now()}`,
      schoolId,
      schoolName,
      alertType,
      severity,
      title,
      message,
      metricSnapshot,
      createdAt: new Date().toISOString(),
      resolved: false,
    };
    if (existingIdx >= 0) {
      aiUsageAlertsStore[existingIdx] = entry;
    } else {
      aiUsageAlertsStore.unshift(entry);
    }
  }

  function mapRouteToAiFunctionCode(urlPath: string): AiFunctionCode {
    if (urlPath.includes('quality-review') || urlPath.includes('analyze-question')) {
      return 'AI_QUALITY_REVIEW';
    }
    if (
      urlPath.includes('smart-import') ||
      urlPath.includes('ocr-textbook') ||
      urlPath.includes('analyze-documents')
    ) {
      return 'AI_SMART_EXAM_IMPORT';
    }
    if (urlPath.includes('matrix')) {
      return 'AI_MATRIX_SUGGESTION';
    }
    return 'AI_QUESTION_GENERATOR';
  }

  function normalizeGeminiPricingModelId(rawModel?: string): GeminiSupportedModelId {
    const m = String(rawModel || '').toLowerCase();
    if (m.includes('lite')) return 'gemini-3.1-flash-lite';
    if (m.includes('pro') || m.includes('argon')) return 'gemini-4-argon';
    return 'gemini-3.8-flash';
  }

  function resolveOperationalActorFromRequest(req: express.Request): {
    schoolId: string;
    userId: string;
    userFullName: string;
    userRole: string;
  } {
    const actor = resolveActor(req);
    const rawSchool =
      req.body?.schoolId ||
      req.query?.schoolId ||
      (actor?.schoolId && actor.schoolId !== 'PLATFORM' ? actor.schoolId : 'SCHOOL_A');
    const schoolId = normalizeOfficialAiSchoolId(String(rawSchool || 'SCHOOL_A'));
    const userId = String(
      req.body?.userId ||
        req.body?.actorUserId ||
        (actor?.id && actor.id !== 'user-admin-sys' ? actor.id : 'gv-chinh-thuc')
    );
    const userFullName = String(
      req.body?.userFullName ||
        req.body?.actorFullName ||
        (actor?.fullName && actor.id !== 'user-admin-sys' ? actor.fullName : 'Giáo viên bộ môn')
    );
    const userRole = String(actor?.roles?.[0] || 'TEACHER');
    return { schoolId, userId, userFullName, userRole };
  }

  checkLiveAiQuotaPrecheckHook = async (req: express.Request) => {
    syncOfficialSchoolsAiOperationalStore();
    const { schoolId, userId } = resolveOperationalActorFromRequest(req);
    const policy = aiSchoolQuotaPoliciesStore[schoolId];
    const counter = aiSchoolUsageCountersStore[schoolId];
    if (!policy || !counter) return { allowed: true };

    const aiFunction = mapRouteToAiFunctionCode(req.originalUrl || req.path || '');
    if (counter.usedDailyRequests >= policy.dailyRequestLimit) {
      pushOrUpdateSchoolAlert(
        schoolId,
        'QUOTA_EXHAUSTED',
        'CRITICAL',
        `Đã hết hạn mức AI theo ngày (${policy.schoolName})`,
        `Đơn vị ${policy.schoolName} đã sử dụng hết ${counter.usedDailyRequests}/${policy.dailyRequestLimit} lượt gọi AI trong ngày.`,
        `${counter.usedDailyRequests}/${policy.dailyRequestLimit} lượt/ngày (100%)`
      );
      const sanitized = sanitizeConfidentialExamForAiLog(
        String(req.body?.topicTitle || req.body?.dossierTitle || 'Tác vụ chuyên môn'),
        String(req.body?.subject || 'Chuyên môn'),
        Number(req.body?.grade || 6)
      );
      aiUsageTelemetryLogsStore.unshift({
        logId: `ai-log-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
        firestorePath: `/schools/${schoolId}/aiUsageLogs/ai-log-${Date.now()}`,
        schoolId,
        schoolName: policy.schoolName,
        userId,
        userFullName: resolveOperationalActorFromRequest(req).userFullName,
        userRole: resolveOperationalActorFromRequest(req).userRole,
        aiFunction,
        aiFunctionLabel: AI_FUNCTION_LABELS[aiFunction],
        modelUsed: 'gemini-3.8-flash',
        timestamp: new Date().toISOString(),
        inputTokens: 0,
        outputTokens: 0,
        totalTokens: 0,
        requestStatus: 'BLOCKED_QUOTA_EXCEEDED',
        failureOrBlockReason: `QUOTA_EXCEEDED_SCHOOL_DAILY: Đã hết hạn mức ngày (${counter.usedDailyRequests}/${policy.dailyRequestLimit})`,
        estimatedCostUsd: 0,
        estimatedCostVnd: 0,
        ...sanitized,
      });
      persistOfficialAiOperationalStore();
      return {
        allowed: false,
        httpStatus: 429,
        errorCode: 'QUOTA_EXCEEDED_SCHOOL_DAILY',
        message: `Đơn vị ${policy.schoolName} đã sử dụng hết hạn mức AI trong ngày (${counter.usedDailyRequests}/${policy.dailyRequestLimit} lượt).`,
      };
    }

    const monthlyCap = Math.min(policy.monthlyRequestLimit, policy.schoolTotalMonthlyQuota);
    if (counter.usedMonthlyRequests >= monthlyCap) {
      pushOrUpdateSchoolAlert(
        schoolId,
        'QUOTA_EXHAUSTED',
        'CRITICAL',
        `Đã hết hạn mức AI theo tháng (${policy.schoolName})`,
        `Đơn vị ${policy.schoolName} đã đạt trần ${counter.usedMonthlyRequests}/${monthlyCap} lượt gọi AI trong tháng.`,
        `${counter.usedMonthlyRequests}/${monthlyCap} lượt/tháng`
      );
      persistOfficialAiOperationalStore();
      return {
        allowed: false,
        httpStatus: 429,
        errorCode: 'QUOTA_EXCEEDED_SCHOOL_MONTHLY',
        message: `Đơn vị ${policy.schoolName} đã sử dụng hết hạn mức AI trong tháng (${counter.usedMonthlyRequests}/${monthlyCap} lượt).`,
      };
    }

    if ((counter.perUserDailyUsed[userId] || 0) >= policy.perUserDailyLimit) {
      return {
        allowed: false,
        httpStatus: 429,
        errorCode: 'QUOTA_EXCEEDED_USER_DAILY',
        message: `Tài khoản đã đạt hạn mức sử dụng AI cá nhân trong ngày (${policy.perUserDailyLimit} lượt/ngày).`,
      };
    }

    return { allowed: true };
  };

  recordLiveAiTelemetryHook = async (
    req: express.Request,
    statusCode: number,
    ctx: LiveGeminiCallExecutionContext
  ) => {
    syncOfficialSchoolsAiOperationalStore();
    const { schoolId, userId, userFullName, userRole } = resolveOperationalActorFromRequest(req);
    const policy = aiSchoolQuotaPoliciesStore[schoolId];
    if (!policy) return;
    if (!aiSchoolUsageCountersStore[schoolId]) {
      aiSchoolUsageCountersStore[schoolId] = createEmptyUsageCounter(schoolId);
    }

    const aiFunction = mapRouteToAiFunctionCode(req.originalUrl || req.path || '');
    const modelUsed = normalizeGeminiPricingModelId(ctx.modelUsed);
    const subject = String(req.body?.subject || req.body?.draft?.subject || 'Chuyên môn');
    const grade = Number(req.body?.grade || req.body?.draft?.grade || 6);
    const topicHint = String(
      req.body?.topicTitle ||
        req.body?.lessonTitle ||
        req.body?.dossierTitle ||
        req.body?.draft?.learningOutcomeCode ||
        'Tác vụ chuyên môn'
    );
    const sanitized = sanitizeConfidentialExamForAiLog(topicHint, subject, grade);

    await runWithSchoolQuotaMutex(schoolId, async () => {
      const counter = aiSchoolUsageCountersStore[schoolId];
      counter.lastRequestAt = new Date().toISOString();

      if (statusCode >= 500) {
        counter.consecutiveFailuresCount += 1;
        if (counter.consecutiveFailuresCount >= 3) {
          pushOrUpdateSchoolAlert(
            schoolId,
            'CONSECUTIVE_FAILURES',
            'CRITICAL',
            `Nhiều yêu cầu gọi AI lỗi liên tiếp (${policy.schoolName})`,
            `Ghi nhận ${counter.consecutiveFailuresCount} yêu cầu gặp lỗi dịch vụ liên tiếp tại ${policy.schoolName}.`,
            `${counter.consecutiveFailuresCount} lỗi liên tiếp`
          );
        }
        aiUsageTelemetryLogsStore.unshift({
          logId: `ai-log-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
          firestorePath: `/schools/${schoolId}/aiUsageLogs/ai-log-${Date.now()}`,
          schoolId,
          schoolName: policy.schoolName,
          userId,
          userFullName,
          userRole,
          aiFunction,
          aiFunctionLabel: AI_FUNCTION_LABELS[aiFunction],
          modelUsed,
          timestamp: new Date().toISOString(),
          inputTokens: ctx.inputTokens,
          outputTokens: 0,
          totalTokens: ctx.inputTokens,
          requestStatus: 'FAILED_MODEL_ERROR',
          failureOrBlockReason: `HTTP_${statusCode}_UPSTREAM_ERROR`,
          estimatedCostUsd: 0,
          estimatedCostVnd: 0,
          ...sanitized,
        });
        persistOfficialAiOperationalStore();
        return;
      }

      if (statusCode >= 200 && statusCode < 300 && ctx.invoked) {
        const inTokens = Math.max(1, ctx.inputTokens || 850);
        const outTokens = Math.max(1, ctx.outputTokens || 520);
        const totalTokens = inTokens + outTokens;
        const estCostUsd = calculateEstimatedCostUsd(modelUsed, inTokens, outTokens);

        counter.consecutiveFailuresCount = 0;
        counter.usedDailyRequests += 1;
        counter.usedMonthlyRequests += 1;
        counter.usedMonthlyInputTokens += inTokens;
        counter.usedMonthlyOutputTokens += outTokens;
        counter.usedMonthlyTotalTokens += totalTokens;
        counter.usedMonthlyCostUsd = Number((counter.usedMonthlyCostUsd + estCostUsd).toFixed(6));
        counter.perUserDailyUsed[userId] = (counter.perUserDailyUsed[userId] || 0) + 1;
        counter.perUserMonthlyUsed[userId] = (counter.perUserMonthlyUsed[userId] || 0) + 1;
        counter.perFunctionMonthlyUsed[aiFunction] =
          (counter.perFunctionMonthlyUsed[aiFunction] || 0) + 1;

        const dailyUsagePct = Math.round(
          (counter.usedDailyRequests / Math.max(1, policy.dailyRequestLimit)) * 100
        );
        if (
          dailyUsagePct >= policy.warningThresholdPercent &&
          counter.usedDailyRequests < policy.dailyRequestLimit
        ) {
          pushOrUpdateSchoolAlert(
            schoolId,
            'NEAR_QUOTA_LIMIT',
            'WARNING',
            `Gần hết hạn mức AI ngày (${policy.schoolName})`,
            `Đơn vị ${policy.schoolName} đã sử dụng ${counter.usedDailyRequests}/${policy.dailyRequestLimit} lượt gọi AI trong ngày (${dailyUsagePct}%).`,
            `${counter.usedDailyRequests}/${policy.dailyRequestLimit} lượt (${dailyUsagePct}%)`
          );
        } else if (counter.usedDailyRequests >= policy.dailyRequestLimit) {
          pushOrUpdateSchoolAlert(
            schoolId,
            'QUOTA_EXHAUSTED',
            'CRITICAL',
            `Chạm trần 100% hạn mức AI ngày (${policy.schoolName})`,
            `Đơn vị ${policy.schoolName} vừa dùng lượt cuối cùng trong ngày (${counter.usedDailyRequests}/${policy.dailyRequestLimit}).`,
            `${counter.usedDailyRequests}/${policy.dailyRequestLimit} lượt (100%)`
          );
        }

        aiUsageTelemetryLogsStore.unshift({
          logId: `ai-log-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
          firestorePath: `/schools/${schoolId}/aiUsageLogs/ai-log-${Date.now()}`,
          schoolId,
          schoolName: policy.schoolName,
          userId,
          userFullName,
          userRole,
          aiFunction,
          aiFunctionLabel: AI_FUNCTION_LABELS[aiFunction],
          modelUsed,
          timestamp: new Date().toISOString(),
          inputTokens: inTokens,
          outputTokens: outTokens,
          totalTokens,
          requestStatus: 'SUCCESS',
          failureOrBlockReason: null,
          estimatedCostUsd: estCostUsd,
          estimatedCostVnd: Math.round(estCostUsd * 25400),
          ...sanitized,
        });
        persistOfficialAiOperationalStore();
      }
    });
  };

  // Hàm thực thi yêu cầu AI có kiểm soát hạn mức nguyên tử tại Backend (Mục II, III, IV, VI)
  async function executeBackendTrackedAiRequest(params: {
    schoolId: string;
    userId: string;
    userFullName?: string;
    userRole?: string;
    aiFunction: AiFunctionCode;
    modelUsed?: GeminiSupportedModelId;
    promptSummaryOrTopic?: string;
    subject?: string;
    grade?: number;
    simulatedInputTokens?: number;
    simulatedOutputTokens?: number;
    simulateModelFailure?: boolean;
  }): Promise<{
    httpStatus: number;
    allowed: boolean;
    errorCode: string | null;
    message: string;
    logEntry: AiUsageTelemetryLogEntry;
    remainingDailyQuota: number;
    remainingMonthlyQuota: number;
  }> {
    const rawSchoolId = String(params.schoolId || '').trim();
    const schoolId = isRunningIsolatedAiQaSuite
      ? rawSchoolId
      : normalizeOfficialAiSchoolId(rawSchoolId);
    const policy = aiSchoolQuotaPoliciesStore[schoolId];
    if (!policy) {
      throw new Error(`Không tìm thấy cấu hình hạn mức cho trường: ${schoolId}`);
    }
    if (!aiSchoolUsageCountersStore[schoolId]) {
      aiSchoolUsageCountersStore[schoolId] = createEmptyUsageCounter(schoolId);
    }

    const userId = String(params.userId || 'gv-chinh-thuc').trim();
    const userFullName = params.userFullName || 'Giáo viên Bộ môn';
    const userRole = params.userRole || 'SUBJECT_TEACHER';
    const aiFunction: AiFunctionCode = params.aiFunction || 'AI_QUESTION_GENERATOR';
    const modelUsed: GeminiSupportedModelId = params.modelUsed || 'gemini-3.8-flash';
    const subject = params.subject || 'Toán';
    const grade = Number(params.grade || 5);

    const sanitized = sanitizeConfidentialExamForAiLog(
      params.promptSummaryOrTopic || `Tác vụ chuyên môn ${subject} lớp ${grade}`,
      subject,
      grade
    );

    const estInputTokens = Number(params.simulatedInputTokens ?? 1450);
    const estOutputTokens = Number(params.simulatedOutputTokens ?? 920);
    const estTotalTokens = estInputTokens + estOutputTokens;
    const estCostUsd = calculateEstimatedCostUsd(modelUsed, estInputTokens, estOutputTokens);

    const reservation = await runWithSchoolQuotaMutex(schoolId, async () => {
      const counter = aiSchoolUsageCountersStore[schoolId];
      counter.recentWindowRequestsCount += 1;

      const effectiveDailyUsed = counter.usedDailyRequests + counter.inFlightReservedRequests;
      const effectiveMonthlyUsed = counter.usedMonthlyRequests + counter.inFlightReservedRequests;
      const userDailyUsed = counter.perUserDailyUsed[userId] || 0;
      const userMonthlyUsed = counter.perUserMonthlyUsed[userId] || 0;
      const funcMonthlyUsed = counter.perFunctionMonthlyUsed[aiFunction] || 0;

      if (counter.recentWindowRequestsCount >= 6) {
        pushOrUpdateSchoolAlert(
          schoolId,
          'TRAFFIC_SPIKE_DETECTED',
          'WARNING',
          `Tăng đột biến số lượt gọi AI tại ${policy.schoolName}`,
          `Phát hiện ${counter.recentWindowRequestsCount} yêu cầu liên tiếp trong cửa sổ ngắn tại trường ${policy.schoolName}. Hệ thống khóa đồng thời đang kích hoạt bảo vệ hạn mức.`,
          `${counter.recentWindowRequestsCount} yêu cầu/cửa sổ`
        );
      }

      if (effectiveDailyUsed >= policy.dailyRequestLimit) {
        pushOrUpdateSchoolAlert(
          schoolId,
          'QUOTA_EXHAUSTED',
          'CRITICAL',
          `Đã hết hạn mức AI theo ngày (${policy.schoolName})`,
          `Trường ${policy.schoolName} đã sử dụng hết ${counter.usedDailyRequests}/${policy.dailyRequestLimit} lượt gọi AI trong ngày.`,
          `${counter.usedDailyRequests}/${policy.dailyRequestLimit} lượt/ngày (100%)`
        );
        return {
          allowed: false,
          errorCode: 'QUOTA_EXCEEDED_SCHOOL_DAILY',
          reason: `Đã vượt hạn mức AI theo ngày của trường (${counter.usedDailyRequests}/${policy.dailyRequestLimit} lượt/ngày).`,
        };
      }

      if (
        effectiveMonthlyUsed >= policy.monthlyRequestLimit ||
        effectiveMonthlyUsed >= policy.schoolTotalMonthlyQuota
      ) {
        const cap = Math.min(policy.monthlyRequestLimit, policy.schoolTotalMonthlyQuota);
        pushOrUpdateSchoolAlert(
          schoolId,
          'QUOTA_EXHAUSTED',
          'CRITICAL',
          `Đã hết hạn mức AI theo tháng (${policy.schoolName})`,
          `Trường ${policy.schoolName} đã đạt giới hạn ${counter.usedMonthlyRequests}/${cap} lượt gọi AI trong tháng.`,
          `${counter.usedMonthlyRequests}/${cap} lượt/tháng`
        );
        return {
          allowed: false,
          errorCode: 'QUOTA_EXCEEDED_SCHOOL_MONTHLY',
          reason: `Đã vượt hạn mức AI theo tháng của trường (${counter.usedMonthlyRequests}/${cap} lượt/tháng).`,
        };
      }

      if (userDailyUsed >= policy.perUserDailyLimit) {
        return {
          allowed: false,
          errorCode: 'QUOTA_EXCEEDED_USER_DAILY',
          reason: `Tài khoản ${userId} đã đạt trần hạn mức cá nhân (${userDailyUsed}/${policy.perUserDailyLimit} lượt/ngày).`,
        };
      }
      if (userMonthlyUsed >= policy.perUserMonthlyLimit) {
        return {
          allowed: false,
          errorCode: 'QUOTA_EXCEEDED_USER_MONTHLY',
          reason: `Tài khoản ${userId} đã đạt trần hạn mức cá nhân trong tháng (${userMonthlyUsed}/${policy.perUserMonthlyLimit} lượt/tháng).`,
        };
      }

      const funcLimit = policy.perFunctionMonthlyLimits[aiFunction] ?? 100;
      if (funcMonthlyUsed >= funcLimit) {
        return {
          allowed: false,
          errorCode: 'QUOTA_EXCEEDED_FUNCTION_LIMIT',
          reason: `Chức năng ${AI_FUNCTION_LABELS[aiFunction]} đã hết hạn mức tháng (${funcMonthlyUsed}/${funcLimit} lượt).`,
        };
      }

      if (counter.usedMonthlyTotalTokens + estTotalTokens > policy.monthlyTokenLimit) {
        pushOrUpdateSchoolAlert(
          schoolId,
          'QUOTA_EXHAUSTED',
          'CRITICAL',
          `Đã chạm trần hạn mức Token tháng (${policy.schoolName})`,
          `Lượng token tích lũy (${counter.usedMonthlyTotalTokens.toLocaleString()} tokens) vượt ngưỡng cho phép (${policy.monthlyTokenLimit.toLocaleString()} tokens).`,
          `${counter.usedMonthlyTotalTokens}/${policy.monthlyTokenLimit} tokens`
        );
        return {
          allowed: false,
          errorCode: 'QUOTA_EXCEEDED_TOKEN_LIMIT',
          reason: `Vượt hạn mức Token tháng của trường (${counter.usedMonthlyTotalTokens}/${policy.monthlyTokenLimit} tokens).`,
        };
      }

      if (counter.usedMonthlyCostUsd + estCostUsd > policy.monthlyBudgetUsdLimit) {
        pushOrUpdateSchoolAlert(
          schoolId,
          'QUOTA_EXHAUSTED',
          'CRITICAL',
          `Đã chạm trần ngân sách chi phí AI tháng (${policy.schoolName})`,
          `Chi phí ước tính ($${counter.usedMonthlyCostUsd.toFixed(4)}) vượt hạn mức ngân sách ($${policy.monthlyBudgetUsdLimit.toFixed(2)}).`,
          `$${counter.usedMonthlyCostUsd.toFixed(4)} / $${policy.monthlyBudgetUsdLimit.toFixed(2)}`
        );
        return {
          allowed: false,
          errorCode: 'QUOTA_EXCEEDED_BUDGET_USD',
          reason: `Vượt hạn mức ngân sách chi phí AI tháng ($${counter.usedMonthlyCostUsd.toFixed(4)}/$${policy.monthlyBudgetUsdLimit.toFixed(2)}).`,
        };
      }

      counter.inFlightReservedRequests += 1;
      return {
        allowed: true,
        errorCode: null,
        reason: null,
      };
    });

    if (!reservation.allowed) {
      const counter = aiSchoolUsageCountersStore[schoolId];
      const blockedLog: AiUsageTelemetryLogEntry = {
        logId: `ai-log-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
        firestorePath: `/schools/${schoolId}/aiUsageLogs/ai-log-${Date.now()}`,
        schoolId,
        schoolName: policy.schoolName,
        userId,
        userFullName,
        userRole,
        aiFunction,
        aiFunctionLabel: AI_FUNCTION_LABELS[aiFunction],
        modelUsed,
        timestamp: new Date().toISOString(),
        inputTokens: 0,
        outputTokens: 0,
        totalTokens: 0,
        requestStatus: 'BLOCKED_QUOTA_EXCEEDED',
        failureOrBlockReason: `${reservation.errorCode}: ${reservation.reason}`,
        estimatedCostUsd: 0,
        estimatedCostVnd: 0,
        ...sanitized,
      };
      aiUsageTelemetryLogsStore.unshift(blockedLog);
      persistOfficialAiOperationalStore();
      return {
        httpStatus: 429,
        allowed: false,
        errorCode: reservation.errorCode,
        message: reservation.reason || 'Vượt hạn mức AI.',
        logEntry: blockedLog,
        remainingDailyQuota: Math.max(0, policy.dailyRequestLimit - counter.usedDailyRequests),
        remainingMonthlyQuota: Math.max(
          0,
          policy.monthlyRequestLimit - counter.usedMonthlyRequests
        ),
      };
    }

    return await runWithSchoolQuotaMutex(schoolId, async () => {
      const counter = aiSchoolUsageCountersStore[schoolId];
      counter.inFlightReservedRequests = Math.max(0, counter.inFlightReservedRequests - 1);
      counter.lastRequestAt = new Date().toISOString();

      if (params.simulateModelFailure) {
        counter.consecutiveFailuresCount += 1;
        if (counter.consecutiveFailuresCount >= 3) {
          pushOrUpdateSchoolAlert(
            schoolId,
            'CONSECUTIVE_FAILURES',
            'CRITICAL',
            `Nhiều yêu cầu gọi AI lỗi liên tiếp (${policy.schoolName})`,
            `Ghi nhận ${counter.consecutiveFailuresCount} yêu cầu lỗi liên tiếp khi gọi model ${modelUsed} tại ${policy.schoolName}.`,
            `${counter.consecutiveFailuresCount} lỗi liên tiếp`
          );
        }

        const failedLog: AiUsageTelemetryLogEntry = {
          logId: `ai-log-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
          firestorePath: `/schools/${schoolId}/aiUsageLogs/ai-log-${Date.now()}`,
          schoolId,
          schoolName: policy.schoolName,
          userId,
          userFullName,
          userRole,
          aiFunction,
          aiFunctionLabel: AI_FUNCTION_LABELS[aiFunction],
          modelUsed,
          timestamp: new Date().toISOString(),
          inputTokens: estInputTokens,
          outputTokens: 0,
          totalTokens: estInputTokens,
          requestStatus: 'FAILED_MODEL_ERROR',
          failureOrBlockReason: 'GEMINI_UPSTREAM_TIMEOUT_OR_SCHEMA_ERROR',
          estimatedCostUsd: 0,
          estimatedCostVnd: 0,
          ...sanitized,
        };
        aiUsageTelemetryLogsStore.unshift(failedLog);
        persistOfficialAiOperationalStore();
        return {
          httpStatus: 502,
          allowed: false,
          errorCode: 'GEMINI_MODEL_EXECUTION_FAILED',
          message: 'Yêu cầu gọi Gemini gặp lỗi thực thi (đã hoàn trả slot hạn mức).',
          logEntry: failedLog,
          remainingDailyQuota: Math.max(0, policy.dailyRequestLimit - counter.usedDailyRequests),
          remainingMonthlyQuota: Math.max(
            0,
            policy.monthlyRequestLimit - counter.usedMonthlyRequests
          ),
        };
      }

      counter.consecutiveFailuresCount = 0;
      counter.usedDailyRequests += 1;
      counter.usedMonthlyRequests += 1;
      counter.usedMonthlyInputTokens += estInputTokens;
      counter.usedMonthlyOutputTokens += estOutputTokens;
      counter.usedMonthlyTotalTokens += estTotalTokens;
      counter.usedMonthlyCostUsd = Number((counter.usedMonthlyCostUsd + estCostUsd).toFixed(6));
      counter.perUserDailyUsed[userId] = (counter.perUserDailyUsed[userId] || 0) + 1;
      counter.perUserMonthlyUsed[userId] = (counter.perUserMonthlyUsed[userId] || 0) + 1;
      counter.perFunctionMonthlyUsed[aiFunction] =
        (counter.perFunctionMonthlyUsed[aiFunction] || 0) + 1;

      const dailyUsagePct = Math.round(
        (counter.usedDailyRequests / Math.max(1, policy.dailyRequestLimit)) * 100
      );
      if (
        dailyUsagePct >= policy.warningThresholdPercent &&
        counter.usedDailyRequests < policy.dailyRequestLimit
      ) {
        pushOrUpdateSchoolAlert(
          schoolId,
          'NEAR_QUOTA_LIMIT',
          'WARNING',
          `Gần hết hạn mức AI ngày (${policy.schoolName})`,
          `Trường ${policy.schoolName} đã sử dụng ${counter.usedDailyRequests}/${policy.dailyRequestLimit} lượt gọi AI trong ngày (${dailyUsagePct}%).`,
          `${counter.usedDailyRequests}/${policy.dailyRequestLimit} lượt (${dailyUsagePct}%)`
        );
      } else if (counter.usedDailyRequests >= policy.dailyRequestLimit) {
        pushOrUpdateSchoolAlert(
          schoolId,
          'QUOTA_EXHAUSTED',
          'CRITICAL',
          `Chạm trần 100% hạn mức AI ngày (${policy.schoolName})`,
          `Trường ${policy.schoolName} vừa dùng lượt cuối cùng trong ngày (${counter.usedDailyRequests}/${policy.dailyRequestLimit}). Các yêu cầu tiếp theo sẽ bị chặn tự động.`,
          `${counter.usedDailyRequests}/${policy.dailyRequestLimit} lượt (100%)`
        );
      }

      const successLog: AiUsageTelemetryLogEntry = {
        logId: `ai-log-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
        firestorePath: `/schools/${schoolId}/aiUsageLogs/ai-log-${Date.now()}`,
        schoolId,
        schoolName: policy.schoolName,
        userId,
        userFullName,
        userRole,
        aiFunction,
        aiFunctionLabel: AI_FUNCTION_LABELS[aiFunction],
        modelUsed,
        timestamp: new Date().toISOString(),
        inputTokens: estInputTokens,
        outputTokens: estOutputTokens,
        totalTokens: estTotalTokens,
        requestStatus: 'SUCCESS',
        failureOrBlockReason: null,
        estimatedCostUsd: estCostUsd,
        estimatedCostVnd: Math.round(estCostUsd * 25400),
        ...sanitized,
      };
      aiUsageTelemetryLogsStore.unshift(successLog);
      persistOfficialAiOperationalStore();

      return {
        httpStatus: 200,
        allowed: true,
        errorCode: null,
        message: `Gọi Gemini (${modelUsed}) thành công và đã ghi nhận hạn mức cho ${policy.schoolName}.`,
        logEntry: successLog,
        remainingDailyQuota: Math.max(0, policy.dailyRequestLimit - counter.usedDailyRequests),
        remainingMonthlyQuota: Math.max(
          0,
          policy.monthlyRequestLimit - counter.usedMonthlyRequests
        ),
      };
    });
  }

  function buildAiUsageDashboardSummary() {
    if (!isRunningIsolatedAiQaSuite) {
      syncOfficialSchoolsAiOperationalStore();
    }

    const totalCalls = aiUsageTelemetryLogsStore.length;
    const successCalls = aiUsageTelemetryLogsStore.filter(
      (l) => l.requestStatus === 'SUCCESS'
    ).length;
    const failedModelCalls = aiUsageTelemetryLogsStore.filter(
      (l) => l.requestStatus === 'FAILED_MODEL_ERROR'
    ).length;
    const blockedQuotaCalls = aiUsageTelemetryLogsStore.filter(
      (l) =>
        l.requestStatus === 'BLOCKED_QUOTA_EXCEEDED' ||
        l.requestStatus === 'BLOCKED_CONCURRENCY_GUARD'
    ).length;

    const totalInputTokens = aiUsageTelemetryLogsStore.reduce((acc, l) => acc + l.inputTokens, 0);
    const totalOutputTokens = aiUsageTelemetryLogsStore.reduce((acc, l) => acc + l.outputTokens, 0);
    const totalTokens = totalInputTokens + totalOutputTokens;
    const totalEstimatedCostUsd = Number(
      aiUsageTelemetryLogsStore.reduce((acc, l) => acc + l.estimatedCostUsd, 0).toFixed(6)
    );
    const totalEstimatedCostVnd = Math.round(totalEstimatedCostUsd * 25400);

    const operationalSchoolMap = new Map<
      string,
      {
        internalCode: string;
        province: string;
        academicYear: string;
        status: 'ACTIVE' | 'SUSPENDED';
        schoolAdminName: string;
        schoolAdminEmail: string;
        departmentCount: number;
        accountCount: number;
        teacherCount: number;
        questionCount: number;
        matrixCount: number;
        examCount: number;
        storageUsedMb: number;
      }
    >();

    let superAdminAccountsCount = 1;
    if (!isRunningIsolatedAiQaSuite) {
      const registry = ensureSuperAdminSchoolRegistry();
      for (const rec of Object.values(registry.records)) {
        const agg = buildAggregatedSchoolWithMetrics(rec);
        const canonicalId = normalizeOfficialAiSchoolId(agg.schoolId);
        operationalSchoolMap.set(canonicalId, {
          internalCode: agg.internalCode,
          province: agg.address || `${agg.communeWard}, ${agg.provinceCity}`,
          academicYear: agg.currentAcademicYear || '2026-2027',
          status: agg.lifecycleStatus === 'DANG_HOAT_DONG' ? 'ACTIVE' : 'SUSPENDED',
          schoolAdminName: agg.assignedSchoolAdmin?.fullName || 'Chưa phân công',
          schoolAdminEmail: agg.assignedSchoolAdmin?.email || '',
          departmentCount: agg.usageMetrics.departmentCount,
          accountCount: agg.usageMetrics.accountCount,
          teacherCount:
            typeof (agg.usageMetrics as any).teacherCount === 'number'
              ? (agg.usageMetrics as any).teacherCount
              : Math.max(0, agg.usageMetrics.accountCount - 1),
          questionCount: agg.usageMetrics.questionCount,
          matrixCount: agg.usageMetrics.matrixCount,
          examCount: agg.usageMetrics.examDossierCount,
          storageUsedMb: Number((agg.usageMetrics.storageUsedMb || 0).toFixed(2)),
        });
      }
      superAdminAccountsCount = ((multiTenantDb.collections?.Users || []) as any[]).filter(
        (u: any) =>
          u &&
          u.schoolId === 'PLATFORM' &&
          u.id !== 'user-admin-sys' &&
          !isPurgedTestUserId(u.id)
      ).length;
    }

    const schoolOrderWeight: Record<string, number> = {
      SCHOOL_A: 1,
      SCHOOL_B: 2,
      SCHOOL_C: 3,
    };

    const schoolsRanking = Object.values(aiSchoolQuotaPoliciesStore)
      .map((policy) => {
        const counter =
          aiSchoolUsageCountersStore[policy.schoolId] || createEmptyUsageCounter(policy.schoolId);
        const schoolLogs = aiUsageTelemetryLogsStore.filter((l) => l.schoolId === policy.schoolId);
        const schoolBlocked = schoolLogs.filter(
          (l) => l.requestStatus === 'BLOCKED_QUOTA_EXCEEDED'
        ).length;
        const schoolFailed = schoolLogs.filter(
          (l) => l.requestStatus === 'FAILED_MODEL_ERROR'
        ).length;
        const remainingDaily = Math.max(0, policy.dailyRequestLimit - counter.usedDailyRequests);
        const remainingMonthly = Math.max(
          0,
          policy.monthlyRequestLimit - counter.usedMonthlyRequests
        );
        const remainingTokens = Math.max(
          0,
          policy.monthlyTokenLimit - counter.usedMonthlyTotalTokens
        );
        const remainingBudgetUsd = Number(
          Math.max(0, policy.monthlyBudgetUsdLimit - counter.usedMonthlyCostUsd).toFixed(4)
        );
        const dailyUtilizationPct = Math.min(
          100,
          Math.round((counter.usedDailyRequests / Math.max(1, policy.dailyRequestLimit)) * 100)
        );
        const monthlyUtilizationPct = Math.min(
          100,
          Math.round((counter.usedMonthlyRequests / Math.max(1, policy.monthlyRequestLimit)) * 100)
        );

        const opInfo = operationalSchoolMap.get(policy.schoolId) || {
          internalCode: policy.schoolId,
          province: '',
          academicYear: '2026-2027',
          status: 'ACTIVE' as const,
          schoolAdminName: 'Quản trị viên trường',
          schoolAdminEmail: '',
          departmentCount: 0,
          accountCount: 0,
          teacherCount: 0,
          questionCount: 0,
          matrixCount: 0,
          examCount: 0,
          storageUsedMb: 0,
        };

        return {
          policy,
          counter,
          schoolOperational: opInfo,
          metrics: {
            totalLoggedCalls: schoolLogs.length,
            successfulCalls: counter.usedMonthlyRequests,
            blockedQuotaCalls: schoolBlocked,
            failedModelCalls: schoolFailed,
            remainingDaily,
            remainingMonthly,
            remainingTokens,
            remainingBudgetUsd,
            dailyUtilizationPct,
            monthlyUtilizationPct,
          },
        };
      })
      .sort((a, b) => {
        if (b.counter.usedMonthlyTotalTokens !== a.counter.usedMonthlyTotalTokens) {
          return b.counter.usedMonthlyTotalTokens - a.counter.usedMonthlyTotalTokens;
        }
        return (
          (schoolOrderWeight[a.policy.schoolId] || 99) -
          (schoolOrderWeight[b.policy.schoolId] || 99)
        );
      });

    const totalSchools = schoolsRanking.length;
    const activeSchools = schoolsRanking.filter(
      (s) => s.schoolOperational.status === 'ACTIVE'
    ).length;
    const suspendedSchools = Math.max(0, totalSchools - activeSchools);
    const totalSchoolAccounts = schoolsRanking.reduce(
      (sum, s) => sum + s.schoolOperational.accountCount,
      0
    );
    const totalTeachersAndStaff = schoolsRanking.reduce(
      (sum, s) => sum + s.schoolOperational.teacherCount,
      0
    );
    const totalSchoolAdmins = Math.max(0, totalSchoolAccounts - totalTeachersAndStaff);
    const totalAccounts = superAdminAccountsCount + totalSchoolAccounts;
    const totalDepartmentsCount = schoolsRanking.reduce(
      (sum, s) => sum + s.schoolOperational.departmentCount,
      0
    );
    const totalQuestionsCount = schoolsRanking.reduce(
      (sum, s) => sum + s.schoolOperational.questionCount,
      0
    );
    const totalMatricesCount = schoolsRanking.reduce(
      (sum, s) => sum + s.schoolOperational.matrixCount,
      0
    );
    const totalExamsCount = schoolsRanking.reduce(
      (sum, s) => sum + s.schoolOperational.examCount,
      0
    );
    const totalStorageUsedMb = Number(
      schoolsRanking
        .reduce((sum, s) => sum + (s.schoolOperational.storageUsedMb || 0), 0)
        .toFixed(2)
    );

    return {
      overview: {
        totalCalls,
        successCalls,
        failedCalls: failedModelCalls + blockedQuotaCalls,
        failedModelCalls,
        blockedQuotaCalls,
        totalInputTokens,
        totalOutputTokens,
        totalTokens,
        totalEstimatedCostUsd,
        totalEstimatedCostVnd,
        confidentialRedactionCompliancePct: 100,
      },
      platformOperations: {
        totalSchools,
        activeSchools,
        suspendedSchools,
        totalAccounts,
        superAdminAccountsCount,
        totalSchoolAdmins,
        totalTeachersAndStaff,
        totalDepartmentsCount,
        totalQuestionsCount,
        totalMatricesCount,
        totalExamsCount,
        totalStorageUsedMb,
        isProductionClean: true,
      },
      schoolsRanking,
      pricingCatalog: Object.values(AI_MODEL_PRICING_CATALOG),
      alerts: aiUsageAlertsStore,
      recentLogs: aiUsageTelemetryLogsStore.slice(0, 60),
    };
  }

  // 1. GET /api/ai-usage/dashboard
  app.get('/api/ai-usage/dashboard', async (_req, res) => {
    res.status(200).json({
      ok: true,
      ...buildAiUsageDashboardSummary(),
    });
  });

  // 2. PUT /api/ai-usage/quotas/:schoolId (Super Admin cấu hình hạn mức Mục III)
  app.put('/api/ai-usage/quotas/:schoolId', async (req, res) => {
    syncOfficialSchoolsAiOperationalStore();
    const schoolId = normalizeOfficialAiSchoolId(req.params.schoolId);
    const actor = resolveActor(req);
    const actorRoles = ((actor?.roles as string[]) || []).map((r) => String(r).toUpperCase());
    const actorUserId = String(
      req.body?.actorUserId || actor?.id || 'user-super-admin-platform'
    ).trim();
    const actorRole = String(req.body?.actorRole || '').trim().toUpperCase();

    const isSuperAdmin =
      actorRole === 'SUPER_ADMIN' ||
      actorRoles.includes('SUPER_ADMIN') ||
      actorRoles.includes('SYSTEM_ADMIN') ||
      actorUserId === 'usr-super-admin-root' ||
      actorUserId === 'user-super-admin-platform';

    if (!isSuperAdmin) {
      res.status(403).json({
        ok: false,
        errorCode: 'SUPER_ADMIN_REQUIRED_FOR_QUOTA_CONFIG',
        message:
          'Từ chối truy cập: Chỉ Quản trị viên nền tảng (Super Admin) mới có thẩm quyền cấu hình hạn mức AI của trường học.',
      });
      return;
    }

    const existing = aiSchoolQuotaPoliciesStore[schoolId];
    if (!existing) {
      res.status(404).json({
        ok: false,
        errorCode: 'SCHOOL_QUOTA_NOT_FOUND',
        message: `Không tìm thấy cấu hình hạn mức cho đơn vị ${schoolId}.`,
      });
      return;
    }

    const incoming = req.body?.quotaUpdate || req.body || {};
    const updated: SchoolAiQuotaPolicy = {
      ...existing,
      dailyRequestLimit: Math.max(
        1,
        Number(incoming.dailyRequestLimit ?? existing.dailyRequestLimit)
      ),
      monthlyRequestLimit: Math.max(
        1,
        Number(incoming.monthlyRequestLimit ?? existing.monthlyRequestLimit)
      ),
      schoolTotalMonthlyQuota: Math.max(
        1,
        Number(incoming.schoolTotalMonthlyQuota ?? existing.schoolTotalMonthlyQuota)
      ),
      perUserDailyLimit: Math.max(
        1,
        Number(incoming.perUserDailyLimit ?? existing.perUserDailyLimit)
      ),
      perUserMonthlyLimit: Math.max(
        1,
        Number(incoming.perUserMonthlyLimit ?? existing.perUserMonthlyLimit)
      ),
      perFunctionMonthlyLimits: {
        ...existing.perFunctionMonthlyLimits,
        ...(incoming.perFunctionMonthlyLimits || {}),
      },
      monthlyTokenLimit: Math.max(
        1000,
        Number(incoming.monthlyTokenLimit ?? existing.monthlyTokenLimit)
      ),
      monthlyBudgetUsdLimit: Math.max(
        0.05,
        Number(incoming.monthlyBudgetUsdLimit ?? existing.monthlyBudgetUsdLimit)
      ),
      warningThresholdPercent: Math.min(
        99,
        Math.max(50, Number(incoming.warningThresholdPercent ?? existing.warningThresholdPercent))
      ),
      updatedAt: new Date().toISOString(),
      updatedBy: actorUserId,
    };

    aiSchoolQuotaPoliciesStore[schoolId] = updated;
    persistOfficialAiOperationalStore();
    res.status(200).json({
      ok: true,
      message: `Đã lưu cấu hình hạn mức AI chính thức cho ${updated.schoolName}.`,
      policy: updated,
      dashboard: buildAiUsageDashboardSummary(),
    });
  });

  // 3. POST /api/ai-usage/execute-request (Kiểm tra hạn mức tại Backend trước khi gọi Gemini)
  app.post('/api/ai-usage/execute-request', async (req, res) => {
    syncOfficialSchoolsAiOperationalStore();
    try {
      const targetSchoolId = normalizeOfficialAiSchoolId(req.body?.schoolId || 'SCHOOL_A');
      const result = await executeBackendTrackedAiRequest({
        schoolId: targetSchoolId,
        userId: req.body?.userId || 'gv-chinh-thuc',
        userFullName: req.body?.userFullName || 'Giáo viên bộ môn',
        userRole: req.body?.userRole || 'SUBJECT_TEACHER',
        aiFunction: req.body?.aiFunction || 'AI_QUESTION_GENERATOR',
        modelUsed: req.body?.modelUsed || 'gemini-3.8-flash',
        promptSummaryOrTopic: req.body?.promptSummaryOrTopic,
        subject: req.body?.subject || 'Toán',
        grade: Number(req.body?.grade || 5),
        simulatedInputTokens: req.body?.simulatedInputTokens,
        simulatedOutputTokens: req.body?.simulatedOutputTokens,
        simulateModelFailure: Boolean(req.body?.simulateModelFailure),
      });

      res.status(result.httpStatus).json({
        ok: result.allowed,
        ...result,
        dashboard: buildAiUsageDashboardSummary(),
      });
    } catch (err: any) {
      res.status(400).json({
        ok: false,
        message: err?.message || 'Lỗi khi thực thi yêu cầu AI.',
      });
    }
  });

  // 4. POST /api/ai-usage/simulate-concurrent (Kiểm thử nhiều yêu cầu đồng thời - Concurrency Guard)
  app.post('/api/ai-usage/simulate-concurrent', async (req, res) => {
    syncOfficialSchoolsAiOperationalStore();
    const schoolId = normalizeOfficialAiSchoolId(req.body?.schoolId || 'SCHOOL_B');
    const concurrentCount = Math.min(20, Math.max(2, Number(req.body?.concurrentCount || 6)));
    const aiFunction: AiFunctionCode = req.body?.aiFunction || 'AI_QUESTION_GENERATOR';
    const modelUsed: GeminiSupportedModelId = req.body?.modelUsed || 'gemini-3.8-flash';

    const policyBefore = aiSchoolQuotaPoliciesStore[schoolId];
    const counterBefore = aiSchoolUsageCountersStore[schoolId];
    const usedDailyBefore = counterBefore?.usedDailyRequests || 0;
    const remainingBefore = Math.max(0, (policyBefore?.dailyRequestLimit || 0) - usedDailyBefore);

    const concurrentPromises = Array.from({ length: concurrentCount }).map((_, idx) =>
      executeBackendTrackedAiRequest({
        schoolId,
        userId: `gv_concurrent_${(idx % 3) + 1}`,
        userFullName: `Giáo viên #${idx + 1}`,
        userRole: 'SUBJECT_TEACHER',
        aiFunction,
        modelUsed,
        subject: 'Khoa học tự nhiên',
        grade: 8,
        promptSummaryOrTopic: `Tác vụ kiểm tra đồng thời #${idx + 1}`,
        simulatedInputTokens: 1200,
        simulatedOutputTokens: 800,
      })
    );

    const results = await Promise.all(concurrentPromises);
    const allowedCount = results.filter((r) => r.allowed).length;
    const blockedCount = results.filter((r) => !r.allowed).length;
    const counterAfter = aiSchoolUsageCountersStore[schoolId];

    res.status(200).json({
      ok: true,
      concurrencyReport: {
        schoolId,
        schoolName: policyBefore?.schoolName || schoolId,
        dailyLimit: policyBefore?.dailyRequestLimit || 0,
        usedDailyBefore,
        remainingBefore,
        concurrentBurstFired: concurrentCount,
        allowedCount,
        blockedCount,
        usedDailyAfter: counterAfter?.usedDailyRequests || 0,
        zeroOverrunGuaranteed:
          (counterAfter?.usedDailyRequests || 0) <= (policyBefore?.dailyRequestLimit || 0),
      },
      dashboard: buildAiUsageDashboardSummary(),
    });
  });

  // 5. POST /api/ai-usage/reset-cycle/:schoolId (Reset hạn mức theo chu kỳ Ngày / Tháng)
  app.post('/api/ai-usage/reset-cycle/:schoolId', async (req, res) => {
    syncOfficialSchoolsAiOperationalStore();
    const schoolId = normalizeOfficialAiSchoolId(req.params.schoolId);
    const cycleType: 'DAILY' | 'MONTHLY' =
      req.body?.cycleType === 'MONTHLY' ? 'MONTHLY' : 'DAILY';

    const counter = aiSchoolUsageCountersStore[schoolId];
    const policy = aiSchoolQuotaPoliciesStore[schoolId];
    if (!counter || !policy) {
      res.status(404).json({
        ok: false,
        message: `Không tìm thấy bộ đếm hạn mức của trường ${schoolId}.`,
      });
      return;
    }

    await runWithSchoolQuotaMutex(schoolId, async () => {
      counter.usedDailyRequests = 0;
      counter.perUserDailyUsed = {};
      counter.recentWindowRequestsCount = 0;
      counter.consecutiveFailuresCount = 0;
      if (cycleType === 'MONTHLY') {
        counter.usedMonthlyRequests = 0;
        counter.usedMonthlyInputTokens = 0;
        counter.usedMonthlyOutputTokens = 0;
        counter.usedMonthlyTotalTokens = 0;
        counter.usedMonthlyCostUsd = 0;
        counter.perUserMonthlyUsed = {};
        counter.perFunctionMonthlyUsed = {
          AI_QUESTION_GENERATOR: 0,
          AI_QUALITY_REVIEW: 0,
          AI_SMART_EXAM_IMPORT: 0,
          AI_MATRIX_SUGGESTION: 0,
        };
      }
      counter.lastCycleResetAt = new Date().toISOString();
      aiUsageAlertsStore = aiUsageAlertsStore.map((a) =>
        a.schoolId === schoolId ? { ...a, resolved: true } : a
      );
    });

    persistOfficialAiOperationalStore();

    res.status(200).json({
      ok: true,
      message: `Đã đặt lại bộ đếm chu kỳ ${cycleType === 'MONTHLY' ? 'Tháng & Ngày' : 'Ngày'} cho ${policy.schoolName}.`,
      dashboard: buildAiUsageDashboardSummary(),
    });
  });

  // 5b. POST /api/ai-usage/alerts/:alertId/resolve (Đánh dấu đã xử lý cảnh báo vận hành)
  app.post('/api/ai-usage/alerts/:alertId/resolve', (req, res) => {
    syncOfficialSchoolsAiOperationalStore();
    const alertId = String(req.params.alertId || '').trim();
    aiUsageAlertsStore = aiUsageAlertsStore.map((a) =>
      a.alertId === alertId ? { ...a, resolved: true } : a
    );
    persistOfficialAiOperationalStore();
    return res.status(200).json({
      ok: true,
      message: 'Đã xác nhận xử lý cảnh báo vận hành.',
      dashboard: buildAiUsageDashboardSummary(),
    });
  });

  // 5c. POST /api/ai-usage/clean-official (Rà soát & Làm sạch dữ liệu vận hành để sử dụng chính thức)
  app.post('/api/ai-usage/clean-official', (req, res) => {
    const actor = resolveActor(req);
    const actorRoles = ((actor?.roles as string[]) || []).map((r) => String(r).toUpperCase());
    const bodyRole = String(req.body?.actorRole || '').toUpperCase();
    const isAllowed =
      actorRoles.includes('SUPER_ADMIN') ||
      actorRoles.includes('SYSTEM_ADMIN') ||
      bodyRole === 'SUPER_ADMIN';
    if (!isAllowed) {
      return res.status(403).json({
        ok: false,
        message:
          'Chỉ Quản trị viên nền tảng (Super Admin) mới có quyền làm sạch dữ liệu thống kê vận hành.',
      });
    }

    syncOfficialSchoolsAiOperationalStore();
    const removedLogsCount = aiUsageTelemetryLogsStore.length;
    const removedAlertsCount = aiUsageAlertsStore.length;

    // Làm sạch toàn bộ nhật ký kiểm thử, cảnh báo cũ và đưa bộ đếm vận hành về trạng thái sạch ban đầu (giữ nguyên cấu hình hạn mức các trường chính thức)
    aiUsageTelemetryLogsStore = [];
    aiUsageAlertsStore = [];
    Object.keys(aiSchoolQuotaPoliciesStore).forEach((sid) => {
      aiSchoolUsageCountersStore[sid] = createEmptyUsageCounter(sid);
    });

    const registry = ensureSuperAdminSchoolRegistry();
    Object.values(registry.records).forEach((rec: any) => {
      rec.aiRequestsThisMonth = 0;
    });

    persistOfficialAiOperationalStore();

    return res.status(200).json({
      ok: true,
      removedLogsCount,
      removedAlertsCount,
      message:
        'Đã hoàn tất rà soát chức năng và làm sạch toàn bộ dữ liệu thống kê vận hành, sẵn sàng đưa vào sử dụng chính thức.',
      dashboard: buildAiUsageDashboardSummary(),
    });
  });

  // 6. POST /api/ai-usage/run-qa-suite (Chạy cô lập trong bộ nhớ tạm, tuyệt đối không ghi đè dữ liệu vận hành chính thức)
  app.post('/api/ai-usage/run-qa-suite', async (_req, res) => {
    const savedPolicies = { ...aiSchoolQuotaPoliciesStore };
    const savedCounters = JSON.parse(JSON.stringify(aiSchoolUsageCountersStore));
    const savedLogs = [...aiUsageTelemetryLogsStore];
    const savedAlerts = [...aiUsageAlertsStore];

    isRunningIsolatedAiQaSuite = true;
    try {
      aiSchoolQuotaPoliciesStore = createInitialThreeSchoolsQuotas();
      aiSchoolUsageCountersStore = {
        'sch-tieu-hoc-a': createEmptyUsageCounter('sch-tieu-hoc-a'),
        'sch-thcs-b': createEmptyUsageCounter('sch-thcs-b'),
        'sch-lien-cap-c': createEmptyUsageCounter('sch-lien-cap-c'),
      };
      aiUsageTelemetryLogsStore = [];
      aiUsageAlertsStore = [];

      const inQuotaA = await executeBackendTrackedAiRequest({
        schoolId: 'sch-tieu-hoc-a',
        userId: 'uid_gv_tha_01',
        userFullName: 'Cô Phạm Thu Hà (GV Toán Tiểu học)',
        userRole: 'SUBJECT_TEACHER',
        aiFunction: 'AI_QUESTION_GENERATOR',
        modelUsed: 'gemini-3.8-flash',
        subject: 'Toán',
        grade: 5,
        promptSummaryOrTopic:
          'Đề chính thức cuối kỳ 1 Toán 5 - Câu 1: Tính diện tích hình thang... Đáp án mật: 45cm2',
        simulatedInputTokens: 1500,
        simulatedOutputTokens: 900,
      });
      const inQuotaB = await executeBackendTrackedAiRequest({
        schoolId: 'sch-thcs-b',
        userId: 'uid_gv_thcsb_01',
        userFullName: 'Thầy Hoàng Minh Đức (GV KHTN)',
        userRole: 'SUBJECT_TEACHER',
        aiFunction: 'AI_QUALITY_REVIEW',
        modelUsed: 'gemini-3.8-flash',
        subject: 'Khoa học tự nhiên',
        grade: 8,
        promptSummaryOrTopic: 'Thẩm định đề mật KHTN 8 - Câu 1: Điện trở dây dẫn... Đáp án: B',
        simulatedInputTokens: 1800,
        simulatedOutputTokens: 1100,
      });
      const inQuotaC = await executeBackendTrackedAiRequest({
        schoolId: 'sch-lien-cap-c',
        userId: 'uid_gv_lcc_01',
        userFullName: 'Cô Nguyễn Lan Anh (GV Toán 9)',
        userRole: 'SUBJECT_TEACHER',
        aiFunction: 'AI_MATRIX_SUGGESTION',
        modelUsed: 'gemini-4-argon',
        subject: 'Toán',
        grade: 9,
        promptSummaryOrTopic: 'Ma trận đề thi học sinh giỏi Toán 9 cấp trường',
        simulatedInputTokens: 2200,
        simulatedOutputTokens: 1400,
      });

      const tc1Passed =
        inQuotaA.httpStatus === 200 &&
        inQuotaB.httpStatus === 200 &&
        inQuotaC.httpStatus === 200 &&
        inQuotaA.logEntry.confidentialExamContentRedacted === true &&
        inQuotaA.logEntry.containsFullConfidentialExamContent === false &&
        !inQuotaA.logEntry.sanitizedPromptSummary.includes('45cm2');

      const concurrentBurst = await Promise.all(
        Array.from({ length: 6 }).map((_, idx) =>
          executeBackendTrackedAiRequest({
            schoolId: 'sch-thcs-b',
            userId: `uid_gv_thcsb_0${(idx % 2) + 1}`,
            userFullName: `Giáo viên THCS Chu Văn An #${idx + 1}`,
            userRole: 'SUBJECT_TEACHER',
            aiFunction: 'AI_QUESTION_GENERATOR',
            modelUsed: 'gemini-3.8-flash',
            subject: 'Toán',
            grade: 8,
            promptSummaryOrTopic: `Yêu cầu đồng thời #${idx + 1} tại THCS Chu Văn An`,
            simulatedInputTokens: 1200,
            simulatedOutputTokens: 800,
          })
        )
      );
      const burstAllowed = concurrentBurst.filter((r) => r.allowed).length;
      const burstBlocked = concurrentBurst.filter((r) => !r.allowed && r.httpStatus === 429).length;
      const usedAfterBurst = aiSchoolUsageCountersStore['sch-thcs-b'].usedDailyRequests;
      const tc2Passed = burstAllowed === 2 && burstBlocked === 4 && usedAfterBurst === 3;

      const overQuotaCallB = await executeBackendTrackedAiRequest({
        schoolId: 'sch-thcs-b',
        userId: 'uid_gv_thcsb_01',
        userFullName: 'Thầy Hoàng Minh Đức',
        userRole: 'SUBJECT_TEACHER',
        aiFunction: 'AI_QUESTION_GENERATOR',
        modelUsed: 'gemini-3.8-flash',
        subject: 'Toán',
        grade: 8,
        promptSummaryOrTopic: 'Yêu cầu thứ 4 vượt hạn mức ngày của THCS Chu Văn An',
      });
      const tc3Passed =
        overQuotaCallB.allowed === false &&
        overQuotaCallB.httpStatus === 429 &&
        overQuotaCallB.errorCode === 'QUOTA_EXCEEDED_SCHOOL_DAILY';

      aiSchoolUsageCountersStore['sch-thcs-b'].usedDailyRequests = 0;
      aiSchoolUsageCountersStore['sch-thcs-b'].perUserDailyUsed = {};
      aiSchoolUsageCountersStore['sch-thcs-b'].lastCycleResetAt = new Date().toISOString();
      const afterResetCallB = await executeBackendTrackedAiRequest({
        schoolId: 'sch-thcs-b',
        userId: 'uid_gv_thcsb_01',
        userFullName: 'Thầy Hoàng Minh Đức',
        userRole: 'SUBJECT_TEACHER',
        aiFunction: 'AI_QUESTION_GENERATOR',
        modelUsed: 'gemini-3.8-flash',
        subject: 'Khoa học tự nhiên',
        grade: 8,
        promptSummaryOrTopic: 'Gọi AI sau khi Reset chu kỳ hạn mức ngày',
      });
      const tc4Passed =
        afterResetCallB.allowed === true &&
        afterResetCallB.httpStatus === 200 &&
        aiSchoolUsageCountersStore['sch-thcs-b'].usedDailyRequests === 1;

      aiSchoolQuotaPoliciesStore['sch-thcs-b'] = {
        ...aiSchoolQuotaPoliciesStore['sch-thcs-b'],
        dailyRequestLimit: 12,
        monthlyRequestLimit: 120,
        perUserDailyLimit: 6,
        updatedAt: new Date().toISOString(),
        updatedBy: 'usr-super-admin-root',
      };
      const updatedLimitB = aiSchoolQuotaPoliciesStore['sch-thcs-b'].dailyRequestLimit;
      const tc5Passed = updatedLimitB === 12;

      for (let i = 2; i <= 8; i++) {
        await executeBackendTrackedAiRequest({
          schoolId: 'sch-tieu-hoc-a',
          userId: i <= 5 ? 'uid_gv_tha_01' : 'uid_gv_tha_02',
          userFullName: i <= 5 ? 'Cô Phạm Thu Hà' : 'Thầy Lê Văn Hùng',
          userRole: 'SUBJECT_TEACHER',
          aiFunction: i % 2 === 0 ? 'AI_QUESTION_GENERATOR' : 'AI_QUALITY_REVIEW',
          modelUsed: 'gemini-3.8-flash',
          subject: 'Toán',
          grade: 5,
          simulatedInputTokens: 1500,
          simulatedOutputTokens: 950,
        });
      }
      for (let f = 1; f <= 3; f++) {
        await executeBackendTrackedAiRequest({
          schoolId: 'sch-lien-cap-c',
          userId: 'uid_gv_lcc_02',
          userFullName: 'Thầy Trần Quốc Tuấn',
          userRole: 'SUBJECT_TEACHER',
          aiFunction: 'AI_SMART_EXAM_IMPORT',
          modelUsed: 'gemini-3.1-flash-lite',
          subject: 'Tiếng Anh',
          grade: 7,
          simulateModelFailure: true,
        });
      }

      const summary = buildAiUsageDashboardSummary();
      const alertTypesPresent = new Set(summary.alerts.map((a) => a.alertType));
      const tc6Passed =
        alertTypesPresent.has('NEAR_QUOTA_LIMIT') &&
        alertTypesPresent.has('QUOTA_EXHAUSTED') &&
        alertTypesPresent.has('TRAFFIC_SPIKE_DETECTED') &&
        alertTypesPresent.has('CONSECUTIVE_FAILURES') &&
        summary.overview.totalTokens > 0 &&
        summary.overview.totalEstimatedCostUsd > 0;

      const testCases = [
        {
          order: 1,
          code: 'AI-QUOTA-01',
          title: '1. Gọi AI trong hạn mức tại 3 trường & Ẩn nội dung đề mật trong nhật ký (Mục II)',
          expected:
            'Cả 3 trường gọi thành công (HTTP 200), ghi đầy đủ schoolId/userId/model/tokens/chi phí, tự động cắt bỏ nội dung câu hỏi & đáp án đề mật (confidentialExamContentRedacted = true)',
          actual: `Trường A, B, C: HTTP 200 ALLOW · Tokens: ${inQuotaA.logEntry.totalTokens}/${inQuotaB.logEntry.totalTokens}/${inQuotaC.logEntry.totalTokens} · Ẩn đề mật: ${inQuotaA.logEntry.confidentialExamContentRedacted} (SHA256:${inQuotaA.logEntry.contentSha256Fingerprint})`,
          passed: tc1Passed,
        },
        {
          order: 2,
          code: 'AI-QUOTA-02',
          title: '2. Kiểm soát đồng thời (Concurrency Race Test): 6 yêu cầu cùng lúc khi chỉ còn 2 lượt (Mục IV)',
          expected:
            'Bắn 6 request đồng thời (Promise.all) vào Trường B khi còn 2/3 lượt ngày: Đúng 2 request ALLOW (đạt 3/3), 4 request bị chặn ngay HTTP 429, không vượt hạn mức',
          actual: `Bắn 6 request song song -> Thành công: ${burstAllowed} lượt · Bị chặn 429: ${burstBlocked} lượt · Bộ đếm sau burst: ${usedAfterBurst}/3 (Không vượt trần)`,
          passed: tc2Passed,
        },
        {
          order: 3,
          code: 'AI-QUOTA-03',
          title: '3. Gọi AI vượt hạn mức bị chặn tại Backend trước khi gọi Gemini (Mục IV)',
          expected:
            'Gọi tiếp AI tại Trường B khi đã hết hạn mức (3/3) -> Backend trả về HTTP 429 QUOTA_EXCEEDED_SCHOOL_DAILY và kích hoạt cảnh báo QUOTA_EXHAUSTED',
          actual: `HTTP ${overQuotaCallB.httpStatus} · Mã lỗi: ${overQuotaCallB.errorCode} · Token tiêu tốn: 0`,
          passed: tc3Passed,
        },
        {
          order: 4,
          code: 'AI-QUOTA-04',
          title: '4. Reset hạn mức theo chu kỳ Ngày / Tháng (Mục VII.4)',
          expected:
            'Sau khi Reset chu kỳ ngày cho Trường B, bộ đếm usedDailyRequests về 0 và giáo viên gọi AI thành công trở lại (HTTP 200)',
          actual: `Reset chu kỳ DAILY -> Gọi lại AI: HTTP ${afterResetCallB.httpStatus} ALLOW · Bộ đếm mới: ${aiSchoolUsageCountersStore['sch-thcs-b'].usedDailyRequests}/${aiSchoolQuotaPoliciesStore['sch-thcs-b'].dailyRequestLimit}`,
          passed: tc4Passed,
        },
        {
          order: 5,
          code: 'AI-QUOTA-05',
          title: '5. Super Admin thay đổi hạn mức động theo trường, người dùng, chức năng (Mục III & VII.5)',
          expected:
            'Super Admin nâng hạn mức ngày của Trường B từ 3 lên 12 lượt/ngày và 120 lượt/tháng có hiệu lực tức thì tại Backend',
          actual: `Trường B (sch-thcs-b) cập nhật hạn mức ngày: 3 -> ${updatedLimitB} lượt/ngày · Hạn mức tháng: 120 lượt/tháng`,
          passed: tc5Passed,
        },
        {
          order: 6,
          code: 'AI-QUOTA-06',
          title: '6. Kiểm tra Thống kê Dashboard & Đầy đủ 4 loại Cảnh báo thông minh (Mục V & VI)',
          expected:
            'Tổng hợp chính xác lượt gọi, thành công, thất bại, tổng token, chi phí USD/VNĐ và phát sinh đủ 4 cảnh báo: NEAR_QUOTA_LIMIT, QUOTA_EXHAUSTED, TRAFFIC_SPIKE_DETECTED, CONSECUTIVE_FAILURES',
          actual: `Tổng gọi: ${summary.overview.totalCalls} (Thành công: ${summary.overview.successCalls}, Chặn/Lỗi: ${summary.overview.failedCalls}) · Tokens: ${summary.overview.totalTokens.toLocaleString()} · Chi phí: $${summary.overview.totalEstimatedCostUsd.toFixed(4)} · Cảnh báo: ${Array.from(alertTypesPresent).join(', ')}`,
          passed: tc6Passed,
        },
      ];

      res.status(200).json({
        ok: true,
        report: {
          executedAt: new Date().toISOString(),
          totalCount: testCases.length,
          passedCount: testCases.filter((t) => t.passed).length,
          allPassed: testCases.every((t) => t.passed),
          testCases,
        },
        dashboard: summary,
      });
    } finally {
      aiSchoolQuotaPoliciesStore = savedPolicies;
      aiSchoolUsageCountersStore = savedCounters;
      aiUsageTelemetryLogsStore = savedLogs;
      aiUsageAlertsStore = savedAlerts;
      isRunningIsolatedAiQaSuite = false;
    }
  });

  // ============================================================================
  // GIAI ĐOẠN 19 (TIẾP THEO): MODULE QUẢN LÝ GÓI SỬ DỤNG CHO TRƯỜNG HỌC
  // (SCHOOL SUBSCRIPTION & RESOURCE PLAN MANAGEMENT)
  // ============================================================================

