  interface SchoolSubscriptionPlanDefinition {
    planId: string;
    tierCode: 'BASIC' | 'ADVANCED' | 'UNLIMITED_ADMIN' | 'CUSTOM';
    planName: string;
    description: string;
    maxTeacherAccounts: number;
    maxQuestionsCount: number;
    maxStorageMb: number;
    monthlyAiQuota: number;
    dailyAiQuota: number;
    enabledFeatures: PlanFeatureCode[];
    durationMonths: number;
    status: 'ACTIVE' | 'INACTIVE';
    isUnlimitedAdminConfig: boolean;
    firestorePath: string;
    updatedAt: string;
    updatedBy: string;
  }

  interface SchoolSubscriptionAssignment {
    schoolId: string;
    schoolName: string;
    educationLevelLabel: string;
    planId: string;
    planNameSnapshot: string;
    assignmentStatus: 'ACTIVE' | 'EXPIRED' | 'SUSPENDED';
    assignedAt: string;
    expiresAt: string;
    assignedBy: string;
    // Số liệu sử dụng thực tế của trường (không bao giờ bị xóa khi hết hạn hoặc đổi gói)
    currentUsage: {
      teacherAccountsCount: number;
      questionsCount: number;
      storageUsedMb: number;
      monthlyAiUsed: number;
      archivedInspectionDossiersCount: number;
    };
    mandatoryArchiveAccessPreserved: true;
    dataDeletedOnExpiry: false;
    paymentGatewayIntegrated: false;
    firestorePath: string;
  }

  interface SchoolSubscriptionHistoryItem {
    historyId: string;
    schoolId: string;
    schoolName: string;
    actionType:
      | 'ASSIGN_PLAN'
      | 'CHANGE_PLAN'
      | 'RENEW_PLAN'
      | 'SUSPEND_PLAN'
      | 'REACTIVATE_PLAN'
      | 'EDIT_PLAN_DEFINITION';
    previousPlanId: string | null;
    previousPlanName: string | null;
    newPlanId: string;
    newPlanName: string;
    previousExpiresAt: string | null;
    newExpiresAt: string;
    actorUserId: string;
    actorRole: string;
    note: string;
    warningsAcknowledged: string[];
    dataPreservedSnapshot: {
      questionsCount: number;
      archivedInspectionDossiersCount: number;
      zeroDataDeleted: true;
      mandatoryArchiveReadEnabled: true;
    };
    timestamp: string;
  }

