  // GIAI ĐOẠN 21 · NGÂN HÀNG CÂU HỎI & TRÌNH SOẠN THẢO ĐỀ (FIRESTORE ACK & QA)
  // ============================================================================
  const stage21FirestoreQuestionsStore = new Map<
    string,
    {
      questionId: string;
      schoolId: string;
      version: number;
      updatedAt: string;
      payload: Record<string, unknown>;
    }
  >();

  app.post('/api/stage21-question-bank/firestore-upsert', (req, res) => {
    const body = req.body || {};
    const schoolId = String(body.schoolId || 'SCHOOL_A');
    const question = (body.question || {}) as Record<string, unknown>;
    const questionId = String(question.id || body.questionId || `q-${Date.now()}`);
    const expectedBaseVersion =
      typeof body.expectedBaseVersion === 'number' ? body.expectedBaseVersion : undefined;
    const simulateConflict = Boolean(body.simulateConflict);
    const simulateFailure = Boolean(body.simulateFailure);

    if (simulateFailure) {
      res.status(503).json({
        ok: false,
        firestoreConfirmed: false,
        saveStatus: 'SAVE_FAILED',
        errorCode: 'FIRESTORE_UNAVAILABLE',
        message:
          'Không nhận được xác nhận ghi từ Firestore (FIRESTORE_UNAVAILABLE). Hệ thống giữ trạng thái "Lưu thất bại", tuyệt đối không báo lưu thành công giả.',
      });
      return;
    }

    const docKey = `${schoolId}::${questionId}`;
    const existing = stage21FirestoreQuestionsStore.get(docKey);

    if (
      simulateConflict ||
      (existing &&
        expectedBaseVersion !== undefined &&
        existing.version > expectedBaseVersion)
    ) {
      const remoteVer = existing ? existing.version : (expectedBaseVersion || 1) + 1;
      res.status(409).json({
        ok: false,
        firestoreConfirmed: false,
        saveStatus: 'CONFLICT_DETECTED',
        errorCode: 'VERSION_CONFLICT',
        remoteVersion: remoteVer,
        expectedBaseVersion: expectedBaseVersion || 1,
        message: `Phát hiện xung đột dữ liệu trên Firestore: Bản ghi trên máy chủ đang ở phiên bản v${remoteVer} (lớn hơn bản đang mở v${expectedBaseVersion || 1}). Vui lòng chọn hợp nhất hoặc tạo phiên bản mới.`,
      });
      return;
    }

    const nextVersion = existing ? existing.version + 1 : Number(question.version || 1);
    const nowIso = new Date().toISOString();
    const savedDoc = {
      questionId,
      schoolId,
      version: nextVersion,
      updatedAt: nowIso,
      payload: {
        ...question,
        id: questionId,
        version: nextVersion,
        updatedAt: nowIso,
      },
    };
    stage21FirestoreQuestionsStore.set(docKey, savedDoc);

    res.status(200).json({
      ok: true,
      firestoreConfirmed: true,
      saveStatus: 'SAVED',
      docPath: `schools/${schoolId}/questions/${questionId}`,
      commitId: `FS-ACK-${Date.now()}`,
      version: nextVersion,
      savedAt: nowIso,
      question: savedDoc.payload,
    });
  });

  app.get('/api/stage21-question-bank/firestore-reload', (req, res) => {
    const schoolId = String(req.query.schoolId || 'SCHOOL_A');
    const questionId = req.query.questionId ? String(req.query.questionId) : '';
    if (questionId) {
      const docKey = `${schoolId}::${questionId}`;
      const record = stage21FirestoreQuestionsStore.get(docKey);
      res.status(200).json({
        ok: true,
        firestoreConfirmed: true,
        found: Boolean(record),
        record: record || null,
      });
      return;
    }

    const list: Array<Record<string, unknown>> = [];
    stage21FirestoreQuestionsStore.forEach((val) => {
      if (val.schoolId === schoolId) {
        list.push(val.payload);
      }
    });
    res.status(200).json({
      ok: true,
      firestoreConfirmed: true,
      schoolId,
      count: list.length,
      questions: list,
    });
  });

