  app.post('/api/stage22/auth/context', (req, res) => {
    ensureSpecialTestAccountsInDb();
    const { email, username, userId } = req.body || {};
    const identifier = String(email || username || userId || '').trim();
    const { user } = findUserByIdentifierSafelyOnBackend(identifier);

    if (!user) {
      return res.status(404).json({
        ok: false,
        code: 'USER_NOT_FOUND',
        message: 'Không tìm thấy tài khoản trong hệ thống.',
        memberships: [],
      });
    }

    if (user.status !== 'ACTIVE') {
      return res.status(403).json({
        ok: false,
        code: 'ACCOUNT_LOCKED',
        message: 'Tài khoản hiện đang bị khóa hoặc tạm ngừng kích hoạt.',
        memberships: [],
      });
    }

    // Nếu tài khoản không có vai trò hoặc không thuộc trường nào
    if (!user.roles || user.roles.length === 0 || !user.schoolId) {
      return res.status(200).json({
        ok: true,
        accountStatus: user.status,
        memberships: [],
      });
    }

    if (user.schoolId && user.schoolId !== 'PLATFORM') {
      currentActiveSessionSchoolId = user.schoolId;
    }

    const emailLower = user.email.toLowerCase();
    const primaryRole = emailLower.includes('superadmin')
      ? 'SUPER_ADMIN'
      : emailLower === 'minhld@hue.edu.vn' ||
        emailLower === 'admin_sia@hue.edu.vn' ||
        emailLower === 'admin_ddung@hue.edu.vn' ||
        emailLower.includes('schooladmin') ||
        (Array.isArray(user.roles) && user.roles.includes('SCHOOL_ADMIN'))
      ? 'SCHOOL_ADMIN'
      : user.roles[0] || 'TEACHER';

    // Nếu là giáo viên liên trường (lanhuong.gv@edutest.vn) -> trả về 2 trường để chọn
    if (emailLower === 'lanhuong.gv@edutest.vn') {
      return res.status(200).json({
        ok: true,
        accountStatus: user.status,
        primaryRole: 'TEACHER',
        memberships: [
          {
            schoolId: 'SCHOOL_A',
            schoolCode: 'TH-THCS-NDA',
            schoolName: 'Trường TH&THCS Nguyễn Đình Anh',
            levelLabel: 'Tiểu học & THCS',
            role: 'TEACHER',
            roleLabel: 'Giáo viên bộ môn',
            departmentName: user.departmentName,
            status: 'ACTIVE',
            academicYear: '2026 - 2027',
          },
          {
            schoolId: 'SCHOOL_B',
            schoolCode: 'TH-SIA',
            schoolName: 'Trường Tiểu học Sịa',
            levelLabel: 'Tiểu học',
            role: 'TEACHER',
            roleLabel: 'Giáo viên thỉnh giảng',
            departmentName: 'Tổ 4-5',
            status: 'ACTIVE',
            academicYear: '2026 - 2027',
          },
        ],
        menus: STAGE22_ROLE_MENUS.TEACHER,
      });
    }

    const memberships =
      primaryRole === 'SUPER_ADMIN'
        ? [
            {
              schoolId: 'PLATFORM',
              schoolCode: 'EDUTEST-PLATFORM',
              schoolName: 'Nền tảng Đa trường EDU TEST AI',
              levelLabel: 'Toàn hệ thống',
              role: 'SUPER_ADMIN',
              roleLabel: 'Super Admin (Quản trị nền tảng)',
              departmentName: 'Ban Quản trị Nền tảng',
              status: 'ACTIVE',
              academicYear: '2026 - 2027',
            },
          ]
        : user.schoolId === 'SCHOOL_B' || emailLower === 'admin_sia@hue.edu.vn'
        ? [
            {
              schoolId: 'SCHOOL_B',
              schoolCode: 'TH-SIA',
              schoolName: 'Trường Tiểu học Sịa',
              levelLabel: 'Tiểu học',
              role: primaryRole,
              roleLabel: user.positionTitle || primaryRole,
              departmentName: user.departmentName,
              status: 'ACTIVE',
              academicYear: '2026 - 2027',
            },
          ]
        : user.schoolId === 'SCHOOL_C' || emailLower === 'admin_ddung@hue.edu.vn'
        ? [
            {
              schoolId: 'SCHOOL_C',
              schoolCode: 'THCS-DANGDUNG',
              schoolName: 'Trường THCS Đặng Dung',
              levelLabel: 'THCS',
              role: primaryRole,
              roleLabel: user.positionTitle || primaryRole,
              departmentName: user.departmentName,
              status: 'ACTIVE',
              academicYear: '2026 - 2027',
            },
          ]
        : [
            {
              schoolId: user.schoolId || 'SCHOOL_A',
              schoolCode: 'TH-THCS-NDA',
              schoolName: 'Trường TH&THCS Nguyễn Đình Anh',
              levelLabel: 'Tiểu học & THCS',
              role: primaryRole,
              roleLabel: user.positionTitle || primaryRole,
              departmentName: user.departmentName,
              status: 'ACTIVE',
              academicYear: '2026 - 2027',
            },
          ];

    return res.status(200).json({
      ok: true,
      accountStatus: user.status,
      primaryRole,
      memberships,
      menus: STAGE22_ROLE_MENUS[primaryRole] || STAGE22_ROLE_MENUS.TEACHER,
    });
  });

